_SOURCES = {'src': '"""Deadlock Build Lab — motor local de análise e otimização de builds."""\n\n__version__ = "0.3.1"\n', 'src.analytics': '"""Análise estatística: intervalos de confiança, tamanho de amostra, associações."""\n', 'src.analytics.confidence': '"""Intervalos de confiança e classificação do tamanho de amostra."""\n\nfrom __future__ import annotations\n\nimport math\n\nfrom scipy.stats import norm\n\n\ndef z_value(confidence: float = 0.95) -> float:\n    return float(norm.ppf(1 - (1 - confidence) / 2))\n\n\ndef wilson_interval(successes: int, n: int, confidence: float = 0.95) -> tuple[float, float]:\n    """Intervalo de Wilson para uma proporção (robusto com amostras pequenas e p perto de 0/1)."""\n    if n <= 0:\n        return (math.nan, math.nan)\n    z = z_value(confidence)\n    p = successes / n\n    denom = 1 + z * z / n\n    center = (p + z * z / (2 * n)) / denom\n    half = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / denom\n    return (max(0.0, center - half), min(1.0, center + half))\n\n\ndef sample_label(n: int, small: int = 200, reliable: int = 1000) -> str:\n    if n < small:\n        return "insuficiente"\n    if n < reliable:\n        return "moderada"\n    return "robusta"\n\n\ndef margin_of_error(successes: int, n: int, confidence: float = 0.95) -> float:\n    lo, hi = wilson_interval(successes, n, confidence)\n    return (hi - lo) / 2 if n > 0 else math.nan\n\n\ndef binom_pvalue(successes: int, n: int, p0: float) -> float:\n    """Teste binomial bilateral exato: a proporção observada difere de p0?"""\n    from scipy.stats import binomtest\n\n    if n <= 0 or not (0 < p0 < 1):\n        return math.nan\n    return float(binomtest(int(successes), int(n), p0).pvalue)\n\n\ndef bh_adjust(pvalues: list[float]) -> list[float]:\n    """Correção de Benjamini–Hochberg (taxa de falsas descobertas) para comparações múltiplas."""\n    idx = [i for i, p in enumerate(pvalues) if p is not None and not math.isnan(p)]\n    m = len(idx)\n    out = [math.nan] * len(pvalues)\n    if m == 0:\n        return out\n    order = sorted(idx, key=lambda i: pvalues[i])\n    prev = 1.0\n    for rank in range(m, 0, -1):\n        i = order[rank - 1]\n        q = min(prev, pvalues[i] * m / rank)\n        out[i] = q\n        prev = q\n    return out\n', 'src.analytics.hero_stats': '"""Estatísticas de heróis a partir de /v1/analytics/hero-stats."""\n\nfrom __future__ import annotations\n\nimport pandas as pd\n\nfrom .confidence import sample_label, wilson_interval\n\n\ndef hero_stats_frame(rows: list[dict], heroes_by_id: dict[int, dict], *, confidence: float = 0.95,\n                     small: int = 200, reliable: int = 1000) -> pd.DataFrame:\n    """Uma linha por herói, com win rate, IC de Wilson e quota de jogadores.\n\n    Quota de jogadores = partidas do herói / soma das partidas de todos os heróis no\n    mesmo filtro (fração dos lugares de jogador ocupados pelo herói). É uma medida\n    de popularidade, não de força.\n    """\n    if not rows:\n        return pd.DataFrame()\n    total = sum(int(r.get("matches") or 0) for r in rows)\n    out = []\n    for r in rows:\n        n = int(r.get("matches") or 0)\n        w = int(r.get("wins") or 0)\n        lo, hi = wilson_interval(w, n, confidence)\n        hero = heroes_by_id.get(int(r["hero_id"]), {})\n        rec = {\n            "hero_id": int(r["hero_id"]),\n            "herói": hero.get("name") or f"herói #{r[\'hero_id\']}",\n            "partidas": n,\n            "vitórias": w,\n            "win rate": w / n if n else None,\n            "IC inferior": lo,\n            "IC superior": hi,\n            "quota de jogadores": n / total if total else None,\n            "amostra": sample_label(n, small, reliable),\n        }\n        for key, label in (("total_kills", "abates/partida"), ("total_deaths", "mortes/partida"),\n                           ("total_assists", "assistências/partida"), ("total_net_worth", "souls/partida"),\n                           ("total_player_damage", "dano a heróis/partida")):\n            if r.get(key) is not None and n:\n                rec[label] = r[key] / n\n        out.append(rec)\n    df = pd.DataFrame(out).sort_values("partidas", ascending=False).reset_index(drop=True)\n    return df\n', 'src.analytics.item_stats': '"""Estatísticas de itens por herói a partir de /v1/analytics/item-stats.\n\nIMPORTANTE — o que estes números NÃO dizem:\nO win rate de quem comprou um item é uma associação observada, não o efeito causal\ndo item. Itens caros e tardios aparecem sobretudo em partidas que já estão a correr\nbem (quem ganha tem mais souls e compra mais cedo). Por isso a diferença face ao win\nrate do herói está enviesada a favor de itens de fim de jogo. A UI mostra sempre o\nmomento médio de compra para expor esse enviesamento; o controlo por tempo/economia\né trabalho da Fase 2/3 (buckets por minuto de compra e por net worth).\n"""\n\nfrom __future__ import annotations\n\nimport pandas as pd\n\nfrom ..models.item import SLOT_LABELS_PT\nfrom .confidence import bh_adjust, binom_pvalue, sample_label, wilson_interval\n\n\ndef item_stats_frame(rows: list[dict], items_by_id: dict[int, dict], hero_wins: int | None,\n                     hero_matches: int | None, *, confidence: float = 0.95, small: int = 200,\n                     reliable: int = 1000) -> pd.DataFrame:\n    if not rows:\n        return pd.DataFrame()\n    hero_wr = (hero_wins / hero_matches) if hero_wins is not None and hero_matches else None\n    out = []\n    for r in rows:\n        n = int(r.get("matches") or 0)\n        w = int(r.get("wins") or 0)\n        lo, hi = wilson_interval(w, n, confidence)\n        item = items_by_id.get(int(r["item_id"]))\n        wr = w / n if n else None\n        out.append({\n            "item_id": int(r["item_id"]),\n            "item": item.get("name") if item else f"item #{r[\'item_id\']} (fora da versão ativa)",\n            "slot": SLOT_LABELS_PT.get((item or {}).get("item_slot_type"), (item or {}).get("item_slot_type")),\n            "tier": (item or {}).get("item_tier"),\n            "custo": (item or {}).get("cost"),\n            "partidas com item": n,\n            "% partidas do herói": (n / hero_matches) if hero_matches else None,\n            "win rate": wr,\n            "IC inferior": lo,\n            "IC superior": hi,\n            "Δ vs herói (pp)": ((wr - hero_wr) * 100) if (wr is not None and hero_wr is not None) else None,\n            "IC exclui WR do herói": (hero_wr is not None and n > 0 and (hi < hero_wr or lo > hero_wr)),\n            "compra média (min)": (r.get("avg_buy_time_s") or 0) / 60 if r.get("avg_buy_time_s") is not None else None,\n            "compra (% da partida)": r.get("avg_buy_time_relative"),\n            "vendido (%)": (r.get("sold") / n * 100) if (r.get("sold") is not None and n) else None,\n            "amostra": sample_label(n, small, reliable),\n        })\n    return pd.DataFrame(out).sort_values("partidas com item", ascending=False).reset_index(drop=True)\n\n\ndef item_window_frame(rows: list[dict], items_by_id: dict[int, dict], *, confidence: float = 0.95,\n                      small: int = 200, reliable: int = 1000) -> pd.DataFrame:\n    """Itens comprados DENTRO de uma janela de tempo (min/max_bought_at_s).\n\n    Linha de base = win rate de todas as compras de itens nessa mesma janela (ponderado por partidas).\n    Comparar itens comprados no mesmo intervalo remove grande parte do enviesamento de "itens tardios\n    aparecem em partidas já ganhas". Continua a ser associação, não causalidade.\n    Teste binomial exato contra a linha de base + correção de Benjamini–Hochberg.\n    """\n    if not rows:\n        return pd.DataFrame()\n    tw = sum(int(r.get("wins") or 0) for r in rows)\n    tn = sum(int(r.get("matches") or 0) for r in rows)\n    base = tw / tn if tn else None\n    out = []\n    for r in rows:\n        n, w = int(r.get("matches") or 0), int(r.get("wins") or 0)\n        lo, hi = wilson_interval(w, n, confidence)\n        item = items_by_id.get(int(r["item_id"])) or {}\n        out.append({\n            "item_id": int(r["item_id"]),\n            "item": item.get("name") or f"item #{r[\'item_id\']}",\n            "slot": SLOT_LABELS_PT.get(item.get("item_slot_type"), item.get("item_slot_type")),\n            "custo": item.get("cost"),\n            "compras na janela": n,\n            "win rate": w / n if n else None, "IC inferior": lo, "IC superior": hi,\n            "Δ vs janela (pp)": ((w / n - base) * 100) if (n and base is not None) else None,\n            "p": binom_pvalue(w, n, base) if base else None,\n            "amostra": sample_label(n, small, reliable),\n        })\n    df = pd.DataFrame(out)\n    df["q (BH)"] = bh_adjust(df["p"].tolist())\n    df["significativo"] = df["q (BH)"] < 0.05\n    df.attrs["baseline"] = base\n    return df.sort_values("compras na janela", ascending=False).reset_index(drop=True)\n', 'src.analytics.matchups': '"""Matchups: win rate de um herói contra cada inimigo e com cada aliado.\n\nFonte: /v1/analytics/hero-counter-stats e /v1/analytics/hero-synergy-stats.\nPor omissão a API usa same_lane_filter=true nos counters (adversários da mesma lane).\n"""\n\nfrom __future__ import annotations\n\nimport pandas as pd\n\nfrom .confidence import bh_adjust, binom_pvalue, sample_label, wilson_interval\n\n\ndef _frame(rows: list[dict], heroes_by_id: dict[int, dict], other_key: str, baseline: float | None,\n           confidence: float, small: int, reliable: int) -> pd.DataFrame:\n    out = []\n    for r in rows:\n        n, w = int(r.get("matches_played") or 0), int(r.get("wins") or 0)\n        lo, hi = wilson_interval(w, n, confidence)\n        oid = int(r[other_key])\n        out.append({"hero_id": oid, "herói": heroes_by_id.get(oid, {}).get("name", f"#{oid}"), "partidas": n,\n                    "win rate": w / n if n else None, "IC inferior": lo, "IC superior": hi,\n                    "p": binom_pvalue(w, n, baseline) if baseline else None, "amostra": sample_label(n, small, reliable)})\n    df = pd.DataFrame(out)\n    if df.empty:\n        return df\n    if baseline:\n        df["Δ vs média do herói (pp)"] = (df["win rate"] - baseline) * 100\n        df["q (BH)"] = bh_adjust(df["p"].tolist())\n        df["significativo"] = df["q (BH)"] < 0.05\n    return df.sort_values("win rate").reset_index(drop=True)\n\n\ndef counters(rows: list[dict], hero_id: int, heroes_by_id: dict[int, dict], baseline: float | None = None,\n             confidence: float = 0.95, small: int = 200, reliable: int = 1000) -> pd.DataFrame:\n    mine = [r for r in rows if int(r.get("hero_id", -1)) == int(hero_id)]\n    return _frame(mine, heroes_by_id, "enemy_hero_id", baseline, confidence, small, reliable)\n\n\ndef synergies(rows: list[dict], hero_id: int, heroes_by_id: dict[int, dict], baseline: float | None = None,\n              confidence: float = 0.95, small: int = 200, reliable: int = 1000) -> pd.DataFrame:\n    norm = []\n    for r in rows:\n        a, b = int(r.get("hero_id1", -1)), int(r.get("hero_id2", -1))\n        if hero_id in (a, b):\n            norm.append({**r, "ally": b if a == hero_id else a})\n    return _frame(norm, heroes_by_id, "ally", baseline, confidence, small, reliable)\n', 'src.api': '"""Clientes das APIs externas (apenas endpoints verificados na documentação)."""\n', 'src.api.analytics_api': '"""Endpoints de estatísticas (/v1/analytics/*) da Deadlock API.\n\nNotas verificadas no OpenAPI:\n* `game_mode`: normal | street_brawl | explore_n_y_c | internal | internal02 (predef. normal)\n* `match_mode`: unranked, private_lobby, coop_bot, ranked, server_test, tutorial,\n  hero_labs — separados por vírgula (predef. "ranked,unranked").\n* `min_average_badge` / `max_average_badge`: 0–116, média do badge das DUAS equipas;\n  tier = dígitos iniciais, sub-rank = último dígito. Não é o rank de um jogador.\n* Sem `min_unix_timestamp`, a API aplica a sua própria data mínima predefinida.\n* Limites: 200 pedidos/min por IP (partilhados por todos os endpoints de analytics);\n  respostas 503 com Retry-After em sobrecarga; 504 em consultas demasiado pesadas.\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom dataclasses import asdict, dataclass\nfrom typing import Any\n\nfrom .http_client import FetchResult, HttpClient\n\nMATCH_MODES = {\n    "ranked": "ranked",\n    "unranked": "unranked",\n    "ambos": "ranked,unranked",\n}\n\n\n@dataclass(frozen=True)\nclass StatsFilters:\n    game_mode: str = "normal"\n    match_mode: str = "ranked"\n    min_average_badge: int | None = None\n    max_average_badge: int | None = None\n    min_unix_timestamp: int | None = None\n    max_unix_timestamp: int | None = None\n    min_duration_s: int | None = None\n    max_duration_s: int | None = None\n    min_matches: int | None = None\n    min_bought_at_s: int | None = None  # só item-stats: compras feitas a partir deste segundo\n    max_bought_at_s: int | None = None\n\n    ITEM_ONLY = ("min_bought_at_s", "max_bought_at_s")\n\n    def to_params(self) -> dict[str, Any]:\n        return {k: v for k, v in asdict(self).items() if v is not None}\n\n    def key(self) -> str:\n        raw = json.dumps(self.to_params(), sort_keys=True)\n        return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:16]\n\n    def describe(self) -> str:\n        parts = [f"modo={self.game_mode}", f"partidas={self.match_mode}"]\n        if self.min_average_badge is not None or self.max_average_badge is not None:\n            parts.append(f"badge médio {self.min_average_badge or 0}–{self.max_average_badge or 116}")\n        if self.min_unix_timestamp:\n            parts.append(f"desde {self.min_unix_timestamp}")\n        if self.min_duration_s or self.max_duration_s:\n            parts.append(f"duração {(self.min_duration_s or 0) // 60}–{(self.max_duration_s or 0) // 60 or \'∞\'} min")\n        if self.min_bought_at_s is not None or self.max_bought_at_s is not None:\n            parts.append(f"compras entre {(self.min_bought_at_s or 0) // 60} e {(self.max_bought_at_s or 0) // 60} min")\n        return ", ".join(parts)\n\n\nclass AnalyticsAPI:\n    SOURCE = "deadlock-api/analytics"\n\n    def __init__(self, client: HttpClient, ttl_s: float = 3600):\n        self.client = client\n        self.ttl_s = ttl_s\n\n    def _get(self, path: str, params: dict[str, Any]) -> FetchResult:\n        return self.client.get_json(path, params, ttl_s=self.ttl_s)\n\n    @staticmethod\n    def _without(f: StatsFilters, *keys: str) -> dict[str, Any]:\n        params = f.to_params()\n        for k in keys:\n            params.pop(k, None)\n        return params\n\n    def hero_stats(self, f: StatsFilters) -> FetchResult:\n        """GET /v1/analytics/hero-stats -> list[AnalyticsHeroStats] (todos os heróis)."""\n        params = self._without(f, "min_matches", *StatsFilters.ITEM_ONLY)  # não existem neste endpoint\n        params["bucket"] = "no_bucket"\n        return self._get("/v1/analytics/hero-stats", params)\n\n    def item_stats(self, hero_id: int, f: StatsFilters) -> FetchResult:\n        """GET /v1/analytics/item-stats -> list[ItemStats] para um herói."""\n        params = f.to_params()\n        params.update({"hero_ids": str(int(hero_id)), "bucket": "no_bucket"})\n        return self._get("/v1/analytics/item-stats", params)\n\n    def item_permutation_stats(\n        self, hero_id: int, f: StatsFilters, comb_size: int = 2, item_ids: list[int] | None = None\n    ) -> FetchResult:\n        """GET /v1/analytics/item-permutation-stats -> list[ItemPermutationStats]."""\n        params = self._without(f, *StatsFilters.ITEM_ONLY)\n        params.update({"hero_ids": str(int(hero_id)), "comb_size": int(comb_size)})\n        if item_ids:\n            params["item_ids"] = list(item_ids)\n        return self._get("/v1/analytics/item-permutation-stats", params)\n\n    def build_item_stats(self, hero_id: int) -> FetchResult:\n        """GET /v1/analytics/build-item-stats -> list[BuildItemStats {item_id, builds}]."""\n        return self._get("/v1/analytics/build-item-stats", {"hero_id": int(hero_id)})\n\n    def hero_counter_stats(self, f: StatsFilters) -> FetchResult:\n        """GET /v1/analytics/hero-counter-stats -> list[HeroCounterStats]."""\n        return self._get("/v1/analytics/hero-counter-stats", self._without(f, *StatsFilters.ITEM_ONLY))\n\n    def hero_synergy_stats(self, f: StatsFilters) -> FetchResult:\n        """GET /v1/analytics/hero-synergy-stats -> list[HeroSynergyStats]."""\n        return self._get("/v1/analytics/hero-synergy-stats", self._without(f, *StatsFilters.ITEM_ONLY))\n', 'src.api.data_api': '"""Deadlock Data API (https://deadlock-data-api.iainfox.dev) — fonte secundária.\n\nDados extraídos diretamente dos ficheiros do jogo (vdata), com `_metadata.build_id`\npor versão de depot da Steam. Endpoints confirmados no OpenAPI do serviço:\n/heroes, /heroes/{id}, /items, /items/{id}, /versions, /versions/{buildId}/items|heroes.\n\nUsada para validação cruzada (ex.: custo dos itens) e para o histórico de builds.\nNunca é a fonte única de verdade.\n"""\n\nfrom __future__ import annotations\n\nfrom .http_client import FetchResult, HttpClient\n\nH = 3600\n\n\nclass DataAPI:\n    SOURCE = "deadlock-data-api"\n\n    def __init__(self, client: HttpClient, ttl_s: float = 24 * H):\n        self.client = client\n        self.ttl_s = ttl_s\n\n    def heroes(self) -> FetchResult:\n        """GET /heroes -> {_metadata, heroes: {id: Hero}}."""\n        return self.client.get_json("/heroes", ttl_s=self.ttl_s)\n\n    def items(self) -> FetchResult:\n        """GET /items -> {_metadata, items: {id: Item}}."""\n        return self.client.get_json("/items", ttl_s=self.ttl_s)\n\n    def versions(self) -> FetchResult:\n        """GET /versions -> {count, builds: [VersionEntry]}."""\n        return self.client.get_json("/versions", ttl_s=6 * H)\n', 'src.api.deadlock_api': '"""Deadlock API (https://api.deadlock-api.com) — assets, versão do jogo, patches, estado.\n\nTodos os caminhos abaixo foram confirmados no OpenAPI público\n(https://api.deadlock-api.com/openapi.json). Não há endpoints inventados.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom .http_client import FetchResult, HttpClient\n\nH = 3600\n\n\nclass DeadlockAPI:\n    SOURCE = "deadlock-api"\n\n    def __init__(self, client: HttpClient, language: str = "english", ttl: dict[str, float] | None = None):\n        self.client = client\n        self.language = language\n        ttl = ttl or {}\n        self.ttl_assets = ttl.get("assets", 24 * H)\n        self.ttl_meta = ttl.get("meta", 1 * H)\n        self.ttl_patches = ttl.get("patches", 6 * H)\n\n    def _assets_params(self, client_version: int | None, extra: dict[str, Any] | None = None) -> dict[str, Any]:\n        params: dict[str, Any] = {"language": self.language}\n        if client_version is not None:\n            params["client_version"] = client_version\n        params.update(extra or {})\n        return params\n\n    # ---- meta / versão -------------------------------------------------\n    def health(self) -> FetchResult:\n        """GET /v1/info/health -> Status {services: {clickhouse, postgres, redis}}."""\n        return self.client.get_json("/v1/info/health", ttl_s=60, use_cache=False, retries=1)\n\n    def info(self) -> FetchResult:\n        """GET /v1/info -> APIInfo."""\n        return self.client.get_json("/v1/info", ttl_s=self.ttl_meta)\n\n    def steam_info(self) -> FetchResult:\n        """GET /v1/assets/steam-info -> SteamInfo {client_version, version_datetime, ...}."""\n        return self.client.get_json("/v1/assets/steam-info", ttl_s=self.ttl_meta)\n\n    def client_versions(self) -> FetchResult:\n        """GET /v1/assets/client-versions — versões de cliente disponíveis nos assets."""\n        return self.client.get_json("/v1/assets/client-versions", ttl_s=self.ttl_meta)\n\n    # ---- assets ---------------------------------------------------------\n    def heroes(self, client_version: int | None = None, only_active: bool = True) -> FetchResult:\n        """GET /v1/assets/heroes -> list[Hero]."""\n        return self.client.get_json(\n            "/v1/assets/heroes",\n            self._assets_params(client_version, {"only_active": only_active}),\n            ttl_s=self.ttl_assets,\n        )\n\n    def items(self, client_version: int | None = None) -> FetchResult:\n        """GET /v1/assets/items -> list[Item] (oneOf Ability | Weapon | Upgrade, campo `type`)."""\n        return self.client.get_json("/v1/assets/items", self._assets_params(client_version), ttl_s=self.ttl_assets)\n\n    def items_by_hero(self, hero_id: int, client_version: int | None = None) -> FetchResult:\n        """GET /v1/assets/items/by-hero-id/{id}."""\n        return self.client.get_json(\n            f"/v1/assets/items/by-hero-id/{int(hero_id)}", self._assets_params(client_version), ttl_s=self.ttl_assets\n        )\n\n    def ranks(self, client_version: int | None = None) -> FetchResult:\n        """GET /v1/assets/ranks -> list[Rank {tier, name, images, color}]."""\n        return self.client.get_json("/v1/assets/ranks", self._assets_params(client_version), ttl_s=self.ttl_assets)\n\n    def generic_data(self, client_version: int | None = None) -> FetchResult:\n        """GET /v1/assets/generic-data -> GenericData (inclui item_price_per_tier)."""\n        return self.client.get_json(\n            "/v1/assets/generic-data", self._assets_params(client_version), ttl_s=self.ttl_assets\n        )\n\n    # ---- patches ----------------------------------------------------------\n    def patches(self) -> FetchResult:\n        """GET /v2/patches -> list[Patch {title, pub_date, link, guid, ...}]."""\n        return self.client.get_json("/v2/patches", ttl_s=self.ttl_patches)\n', 'src.api.http_client': '"""Cliente HTTP robusto: cache em disco, limite de pedidos, retries com backoff.\n\nRegras implementadas (ver ARQUITETURA.md):\n* 429 / 500 / 502 / 503 e erros de rede -> retry com backoff exponencial e jitter;\n  se a resposta trouxer `Retry-After`, esse valor é respeitado.\n* 504 -> SEM retry. A documentação da Deadlock API diz que um pedido que excede o\n  tempo volta a falhar rapidamente durante alguns minutos; repetir só gasta quota.\n* Outros 4xx -> erro imediato (pedido inválido; repetir não ajuda).\n* Se a rede falhar e existir uma cópia em cache (mesmo expirada), devolve-a marcada\n  como `stale=True`, para a aplicação continuar a funcionar offline.\n"""\n\nfrom __future__ import annotations\n\nimport email.utils\nimport hashlib\nimport json\nimport os\nimport random\nimport threading\nimport time\nimport uuid\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any, Callable\n\nimport httpx\n\nRETRYABLE_STATUS = {429, 500, 502, 503}\n\n\nclass ApiError(Exception):\n    """Falha definitiva de um pedido (após retries, ou não repetível)."""\n\n    def __init__(self, message: str, url: str, status: int | None = None):\n        super().__init__(message)\n        self.url = url\n        self.status = status\n\n    @property\n    def is_network(self) -> bool:\n        return self.status is None\n\n\n@dataclass\nclass FetchResult:\n    data: Any\n    url: str\n    params: dict[str, str]\n    fetched_at: float\n    from_cache: bool = False\n    stale: bool = False\n    status: int | None = None\n    error: str | None = None\n\n\ndef encode_params(params: dict[str, Any] | None) -> dict[str, str]:\n    """Converte parâmetros para strings: ignora None, listas -> \'a,b,c\', bool -> true/false."""\n    out: dict[str, str] = {}\n    for key, value in (params or {}).items():\n        if value is None:\n            continue\n        if isinstance(value, bool):\n            out[key] = "true" if value else "false"\n        elif isinstance(value, (list, tuple, set)):\n            if not value:\n                continue\n            out[key] = ",".join(str(v) for v in value)\n        else:\n            out[key] = str(value)\n    return out\n\n\ndef parse_retry_after(value: str | None, now: float | None = None) -> float | None:\n    """Interpreta o cabeçalho Retry-After (segundos ou data HTTP)."""\n    if not value:\n        return None\n    value = value.strip()\n    try:\n        return max(0.0, float(value))\n    except ValueError:\n        pass\n    try:\n        dt = email.utils.parsedate_to_datetime(value)\n    except (TypeError, ValueError):\n        return None\n    if dt is None:\n        return None\n    return max(0.0, dt.timestamp() - (now if now is not None else time.time()))\n\n\nclass RateLimiter:\n    """Token bucket simples e thread-safe."""\n\n    def __init__(\n        self,\n        per_minute: int,\n        clock: Callable[[], float] = time.monotonic,\n        sleep: Callable[[float], None] = time.sleep,\n    ):\n        self.capacity = max(1, int(per_minute))\n        self.rate = self.capacity / 60.0\n        self.tokens = float(self.capacity)\n        self._clock = clock\n        self._sleep = sleep\n        self._last = clock()\n        self._lock = threading.Lock()\n\n    def _refill(self) -> None:\n        now = self._clock()\n        self.tokens = min(self.capacity, self.tokens + (now - self._last) * self.rate)\n        self._last = now\n\n    def acquire(self) -> None:\n        with self._lock:\n            self._refill()\n            if self.tokens < 1:\n                self._sleep((1 - self.tokens) / self.rate)\n                self._refill()\n            self.tokens = max(0.0, self.tokens - 1)\n\n\nclass DiskCache:\n    """Cache de respostas JSON em ficheiros (uma entrada por URL + parâmetros)."""\n\n    def __init__(self, directory: Path):\n        self.directory = Path(directory)\n        self.directory.mkdir(parents=True, exist_ok=True)\n\n    @staticmethod\n    def key(url: str, params: dict[str, str]) -> str:\n        raw = url + "?" + json.dumps(params, sort_keys=True)\n        return hashlib.sha256(raw.encode("utf-8")).hexdigest()\n\n    def _path(self, key: str) -> Path:\n        return self.directory / f"{key}.json"\n\n    def get(self, key: str) -> dict[str, Any] | None:\n        path = self._path(key)\n        if not path.exists():\n            return None\n        try:\n            return json.loads(path.read_text(encoding="utf-8"))\n        except (OSError, json.JSONDecodeError):\n            return None\n\n    def set(self, key: str, url: str, params: dict[str, str], data: Any, fetched_at: float) -> None:\n        """Escrita atómica e tolerante: a cache é um acelerador, nunca pode fazer falhar um pedido.\n\n        Ficheiro temporário com nome único (várias sessões podem pedir o mesmo URL ao mesmo tempo num servidor\n        partilhado) e a pasta é recriada se tiver desaparecido (ex.: limpeza do disco na nuvem).\n        """\n        entry = {"url": url, "params": params, "fetched_at": fetched_at, "data": data}\n        tmp = self.directory / f"{key}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp"\n        try:\n            self.directory.mkdir(parents=True, exist_ok=True)\n            tmp.write_text(json.dumps(entry), encoding="utf-8")\n            os.replace(tmp, self._path(key))\n        except OSError:\n            try:\n                tmp.unlink()\n            except OSError:\n                pass\n\n    def clear(self) -> int:\n        count = 0\n        for path in self.directory.glob("*.json"):\n            try:\n                path.unlink()\n                count += 1\n            except OSError:\n                pass\n        return count\n\n\nclass HttpClient:\n    def __init__(\n        self,\n        base_url: str,\n        *,\n        timeout_s: float = 30,\n        max_retries: int = 4,\n        backoff_base_s: float = 1.5,\n        backoff_max_s: float = 60,\n        user_agent: str = "DeadlockBuildLab/0.1",\n        cache: DiskCache | None = None,\n        limiter: RateLimiter | None = None,\n        transport: httpx.BaseTransport | None = None,\n        sleep: Callable[[float], None] = time.sleep,\n        clock: Callable[[], float] = time.time,\n    ):\n        self.base_url = base_url.rstrip("/")\n        self.max_retries = max(0, int(max_retries))\n        self.backoff_base_s = backoff_base_s\n        self.backoff_max_s = backoff_max_s\n        self.cache = cache\n        self.limiter = limiter\n        self._sleep = sleep\n        self._clock = clock\n        self._client = httpx.Client(\n            timeout=timeout_s,\n            headers={"User-Agent": user_agent, "Accept": "application/json"},\n            follow_redirects=True,\n            transport=transport,\n        )\n\n    def close(self) -> None:\n        self._client.close()\n\n    def _backoff(self, attempt: int) -> float:\n        delay = min(self.backoff_max_s, self.backoff_base_s * (2**attempt))\n        return delay * random.uniform(0.5, 1.0)\n\n    def _request(self, url: str, params: dict[str, str], retries: int | None = None) -> tuple[Any, int]:\n        last_error = "erro desconhecido"\n        max_retries = self.max_retries if retries is None else max(0, int(retries))\n        for attempt in range(max_retries + 1):\n            if self.limiter:\n                self.limiter.acquire()\n            try:\n                resp = self._client.get(url, params=params)\n            except httpx.TransportError as exc:\n                last_error = f"erro de rede: {exc.__class__.__name__}: {exc}"\n                if attempt >= max_retries:\n                    raise ApiError(last_error, url) from exc\n                self._sleep(self._backoff(attempt))\n                continue\n\n            if resp.status_code == 200:\n                try:\n                    return resp.json(), 200\n                except ValueError as exc:\n                    raise ApiError("resposta 200 sem JSON válido", url, 200) from exc\n\n            if resp.status_code in RETRYABLE_STATUS:\n                last_error = f"HTTP {resp.status_code}"\n                if attempt >= max_retries:\n                    raise ApiError(f"{last_error} após {attempt + 1} tentativas", url, resp.status_code)\n                wait = parse_retry_after(resp.headers.get("Retry-After"), self._clock())\n                self._sleep(min(self.backoff_max_s, wait if wait is not None else self._backoff(attempt)))\n                continue\n\n            detail = resp.text[:300] if resp.text else ""\n            if resp.status_code == 504:\n                raise ApiError(\n                    "HTTP 504 (consulta demasiado pesada; a API recomenda filtros mais "\n                    "restritos em vez de repetir)",\n                    url,\n                    504,\n                )\n            raise ApiError(f"HTTP {resp.status_code}: {detail}", url, resp.status_code)\n        raise ApiError(last_error, url)  # pragma: no cover\n\n    def get_json(\n        self,\n        path: str,\n        params: dict[str, Any] | None = None,\n        *,\n        ttl_s: float = 3600,\n        use_cache: bool = True,\n        absolute_url: bool = False,\n        retries: int | None = None,\n    ) -> FetchResult:\n        url = path if absolute_url else f"{self.base_url}{path}"\n        enc = encode_params(params)\n        key = DiskCache.key(url, enc)\n        cached = self.cache.get(key) if self.cache else None\n        now = self._clock()\n\n        if use_cache and cached is not None and now - float(cached.get("fetched_at", 0)) < ttl_s:\n            return FetchResult(cached["data"], url, enc, float(cached["fetched_at"]), from_cache=True)\n\n        try:\n            data, status = self._request(url, enc, retries)\n        except ApiError as err:\n            recoverable = err.status is None or err.status >= 500 or err.status == 429\n            if cached is not None and recoverable:\n                return FetchResult(\n                    cached["data"], url, enc, float(cached["fetched_at"]),\n                    from_cache=True, stale=True, error=str(err),\n                )\n            raise\n\n        fetched_at = self._clock()\n        if self.cache:\n            self.cache.set(key, url, enc, data, fetched_at)\n        return FetchResult(data, url, enc, fetched_at, status=status)\n\n    def get_bytes(self, url: str) -> bytes:\n        """Descarga simples de binários (imagens). Um retry em erro de rede."""\n        for attempt in range(2):\n            if self.limiter:\n                self.limiter.acquire()\n            try:\n                resp = self._client.get(url, headers={"Accept": "*/*"})\n            except httpx.TransportError as exc:\n                if attempt == 1:\n                    raise ApiError(f"erro de rede: {exc}", url) from exc\n                self._sleep(self._backoff(attempt))\n                continue\n            if resp.status_code == 200:\n                return resp.content\n            raise ApiError(f"HTTP {resp.status_code}", url, resp.status_code)\n        raise ApiError("falha na descarga", url)  # pragma: no cover\n', 'src.cli': '"""Linha de comandos: atualização sem abrir a interface (para o Agendador de Tarefas).\n\n    python -m src.cli update        # recolhe tudo (heróis, itens, ranks, patches, estatísticas)\n    python -m src.cli update --no-stats\n    python -m src.cli status        # versão ativa, contagens, última atualização\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport sys\n\nfrom .config import load_config\nfrom .data.collector import Collector\n\n\ndef main(argv: list[str] | None = None) -> int:\n    parser = argparse.ArgumentParser(prog="deadlock-build-lab")\n    sub = parser.add_subparsers(dest="cmd", required=True)\n    up = sub.add_parser("update", help="atualizar dados")\n    up.add_argument("--no-stats", action="store_true", help="não recolher estatísticas")\n    up.add_argument("--if-needed", action="store_true", help="só atualizar se os dados estiverem desatualizados")\n    sub.add_parser("status", help="mostrar estado")\n    sub.add_parser("amostra", help="exportar amostra de diagnóstico (data/amostra_diagnostico.json)")\n    args = parser.parse_args(argv)\n\n    col = Collector.from_config(load_config())\n    if args.cmd == "status":\n        v = col.active_version\n        print(f"Versão ativa: {v or \'—\'}")\n        if v:\n            print(f"Contagens: {col.db.counts(v)}")\n        print(f"Última atualização com sucesso: {col.db.get_kv(\'last_success_at\') or \'nunca\'}")\n        return 0\n\n    if args.cmd == "amostra":\n        from pathlib import Path\n\n        from .engine.diagnostics import export_sample\n\n        v = col.active_version\n        if not v:\n            print("Ainda não há dados. Corre primeiro: python -m src.cli update")\n            return 1\n        dest = export_sample(col.db, v, col.cfg, Path(col.base_dir) / "amostra_diagnostico.json")\n        print(f"Amostra criada: {dest}")\n        return 0\n\n    if args.if_needed and not col.needs_update():\n        print("Dados atualizados; nada a fazer.")\n        return 0\n\n    def progress(msg: str, frac: float) -> None:\n        print(f"[{frac:4.0%}] {msg}", flush=True)\n\n    rep = col.update_all(include_stats=not args.no_stats, progress=progress)\n    for s in rep.steps:\n        print(f"  {\'OK \' if s.ok else \'ERRO\'}  {s.name}: {s.message}")\n    if not rep.online:\n        print("Sem ligação — dados anteriores mantidos.")\n        return 2\n    return 0 if rep.ok else 1\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'src.config': '"""Carregamento da configuração (config.yaml + predefinições)."""\n\nfrom __future__ import annotations\n\nimport copy\nimport os\nfrom pathlib import Path\nfrom typing import Any\n\nimport yaml\n\nROOT_DIR = Path(__file__).resolve().parent.parent\nDEFAULT_CONFIG_PATH = ROOT_DIR / "config.yaml"\n\nDEFAULTS: dict[str, Any] = {\n    "app": {"name": "Deadlock Build Lab", "language": "english"},\n    "paths": {"data_dir": "data", "database_file": "deadlock.db"},\n    "heroes": {"initial": ["Graves", "Mina", "Seven"]},\n    "sources": {\n        "deadlock_api": {"base_url": "https://api.deadlock-api.com", "enabled": True},\n        "data_api": {"base_url": "https://deadlock-data-api.iainfox.dev", "enabled": True},\n    },\n    "http": {\n        "timeout_s": 30,\n        "max_retries": 4,\n        "backoff_base_s": 1.5,\n        "backoff_max_s": 60,\n        "requests_per_minute": 60,\n        "user_agent": "DeadlockBuildLab/0.1 (uso pessoal)",\n    },\n    "cache": {"ttl_assets_h": 24, "ttl_analytics_h": 1, "ttl_meta_h": 1, "ttl_patches_h": 6},\n    "update": {\n        "auto_on_start": True,\n        "check_interval_h": 24,\n        "min_count_ratio": 0.8,\n        "max_invalid_fraction": 0.05,\n        "fetch_stats_on_update": True,\n    },\n    "backups": {"keep": 10},\n    "statistics": {\n        "game_mode": "normal",\n        "min_matches_query": 20,\n        "small_sample": 200,\n        "reliable_sample": 1000,\n        "confidence_level": 0.95,\n    },\n    "engine": {\n        "no_crit_heroes": ["Graves", "Paige", "Deadman Danny"],\n        "apply_indeterminate": False,\n        "default_scenario": {"target_bullet_resist": 0, "target_spirit_resist": 0, "distance_m": 0,\n                             "headshot_rate": 0, "incoming_bullet_share": 50, "flex_slots": 4, "combat_s": 10},\n    },\n    "optimizer": {"budget": 25000, "beam_width": 12, "early_max": 6000, "mid_max": 18000,\n                  "sensitivity_runs": 10},\n    "ability_property_keys": {\n        "cooldown": ["AbilityCooldown"],\n        "duration": ["AbilityDuration"],\n        "cast_range": ["AbilityCastRange"],\n        "charges": ["AbilityCharges"],\n    },\n}\n\n\ndef _deep_merge(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:\n    out = copy.deepcopy(base)\n    for key, value in (override or {}).items():\n        if isinstance(value, dict) and isinstance(out.get(key), dict):\n            out[key] = _deep_merge(out[key], value)\n        else:\n            out[key] = value\n    return out\n\n\ndef load_config(path: Path | str | None = None) -> dict[str, Any]:\n    """Lê o config.yaml (se existir) e junta-o às predefinições.\n\n    A variável de ambiente DBL_CONFIG permite apontar para outro ficheiro (usada nos testes).\n    """\n    env = os.environ.get("DBL_CONFIG")\n    cfg_path = Path(path) if path else (Path(env) if env else DEFAULT_CONFIG_PATH)\n    user_cfg: dict[str, Any] = {}\n    if cfg_path.exists():\n        with cfg_path.open("r", encoding="utf-8") as fh:\n            user_cfg = yaml.safe_load(fh) or {}\n    cfg = _deep_merge(DEFAULTS, user_cfg)\n    cfg["_config_path"] = str(cfg_path)\n    return cfg\n\n\ndef data_dir(cfg: dict[str, Any]) -> Path:\n    raw = Path(cfg["paths"]["data_dir"])\n    path = raw if raw.is_absolute() else ROOT_DIR / raw\n    for sub in ("", "cache", "cache/http", "cache/images", "backups"):\n        (path / sub).mkdir(parents=True, exist_ok=True)\n    return path\n\n\ndef database_path(cfg: dict[str, Any]) -> Path:\n    return data_dir(cfg) / cfg["paths"]["database_file"]\n', 'src.data': '"""Recolha, validação, armazenamento e versionamento dos dados."""\n', 'src.data.collector': '"""Orquestração da recolha: API -> validação -> base de dados (com histórico por versão).\n\nGarantias:\n* Sem Internet: a recolha termina cedo e a app continua com os últimos dados guardados.\n* Dados válidos nunca são substituídos por respostas incompletas ou erros temporários\n  (validação antes de escrever; escrita numa transação por tipo de dado).\n* Antes de escrever uma versão nova é feito um backup da base de dados.\n* A versão "ativa" só avança quando heróis E itens dessa versão foram guardados.\n"""\n\nfrom __future__ import annotations\n\nimport threading\nimport time\nfrom dataclasses import asdict, dataclass, field\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Callable\n\nimport httpx\n\nfrom ..api.analytics_api import AnalyticsAPI, StatsFilters\nfrom ..api.data_api import DataAPI\nfrom ..api.deadlock_api import DeadlockAPI\nfrom ..api.http_client import ApiError, DiskCache, FetchResult, HttpClient, RateLimiter\nfrom ..config import data_dir, database_path\nfrom ..models.meta import Patch, SteamInfo\nfrom ..models.stats import (AnalyticsHeroStats, HeroCounterStats, HeroSynergyStats, ItemPermutationStats,\n                            ItemStats)\nfrom .database import Database, utc_now\nfrom .normalizer import find_hero\nfrom .patch_tracker import diff_heroes, diff_items\nfrom .validation import validate_heroes, validate_items, validate_ranks\n\nH = 3600\nProgress = Callable[[str, float], None]\n\n\ndef _iso(ts: float) -> str:\n    return datetime.fromtimestamp(ts, timezone.utc).isoformat(timespec="seconds")\n\n\n@dataclass\nclass StepResult:\n    name: str\n    ok: bool\n    message: str = ""\n    changed: bool = False\n    stale: bool = False\n    warnings: list[str] = field(default_factory=list)\n\n\n@dataclass\nclass UpdateReport:\n    started_at: str\n    finished_at: str | None = None\n    online: bool = True\n    version: str | None = None\n    previous_version: str | None = None\n    new_version: bool = False\n    steps: list[StepResult] = field(default_factory=list)\n\n    @property\n    def ok(self) -> bool:\n        core = [s for s in self.steps if s.name in ("Heróis", "Itens")]\n        return self.online and bool(core) and all(s.ok for s in core)\n\n    def add(self, step: StepResult) -> StepResult:\n        self.steps.append(step)\n        return step\n\n    def to_dict(self) -> dict[str, Any]:\n        d = asdict(self)\n        d["ok"] = self.ok\n        return d\n\n\n@dataclass\nclass VersionInfo:\n    version: str\n    assets_client_version: int | None\n    steam_client_version: int | None\n    version_datetime: str | None\n    source: str\n\n\n# Uma atualização de cada vez no processo: na nuvem, várias sessões (separadores) partilham a mesma base de dados.\n_UPDATE_LOCK = threading.Lock()\n\n\nclass Collector:\n    def __init__(self, cfg: dict[str, Any], db: Database, deadlock: DeadlockAPI, analytics: AnalyticsAPI,\n                 data_api: DataAPI | None, base_dir: Path):\n        self.cfg = cfg\n        self.db = db\n        self.deadlock = deadlock\n        self.analytics = analytics\n        self.data_api = data_api\n        self.base_dir = Path(base_dir)\n\n    # ------------------------------------------------------------------ fábrica\n    @classmethod\n    def from_config(cls, cfg: dict[str, Any], transport: httpx.BaseTransport | None = None,\n                    sleep: Callable[[float], None] = time.sleep) -> "Collector":\n        ddir = data_dir(cfg)\n        db = Database(database_path(cfg))\n        cache = DiskCache(ddir / "cache" / "http")\n        http = cfg["http"]\n        ttl = cfg["cache"]\n\n        def client(base_url: str, per_minute: int) -> HttpClient:\n            return HttpClient(\n                base_url, timeout_s=http["timeout_s"], max_retries=http["max_retries"],\n                backoff_base_s=http["backoff_base_s"], backoff_max_s=http["backoff_max_s"],\n                user_agent=http["user_agent"], cache=cache, limiter=RateLimiter(per_minute, sleep=sleep),\n                transport=transport, sleep=sleep,\n            )\n\n        main = client(cfg["sources"]["deadlock_api"]["base_url"], http["requests_per_minute"])\n        deadlock = DeadlockAPI(main, cfg["app"]["language"], {\n            "assets": ttl["ttl_assets_h"] * H, "meta": ttl["ttl_meta_h"] * H, "patches": ttl["ttl_patches_h"] * H})\n        analytics = AnalyticsAPI(main, ttl_s=ttl["ttl_analytics_h"] * H)\n        data_api = None\n        if cfg["sources"]["data_api"].get("enabled", True):\n            data_api = DataAPI(client(cfg["sources"]["data_api"]["base_url"], 30), ttl_s=ttl["ttl_assets_h"] * H)\n        return cls(cfg, db, deadlock, analytics, data_api, ddir)\n\n    # ------------------------------------------------------------------ estado\n    @property\n    def active_version(self) -> str | None:\n        return self.db.get_kv("active_version")\n\n    def needs_update(self, now: float | None = None) -> bool:\n        last = self.db.get_kv("last_success_ts")\n        if last is None:\n            return True\n        return (now or time.time()) - float(last) > self.cfg["update"]["check_interval_h"] * H\n\n    def _fetch(self, source: str, fn: Callable[..., FetchResult], *args: Any, **kwargs: Any\n               ) -> tuple[FetchResult | None, ApiError | None]:\n        try:\n            res = fn(*args, **kwargs)\n        except ApiError as err:\n            self.db.log_fetch(source, err.url, None, False, http_status=err.status, message=str(err))\n            return None, err\n        self.db.log_fetch(source, res.url, res.params, True, http_status=res.status, from_cache=res.from_cache,\n                          stale=res.stale, message=res.error or "")\n        return res, None\n\n    # ------------------------------------------------------------------ recolha completa\n    def update_all(self, include_stats: bool | None = None, progress: Progress | None = None) -> UpdateReport:\n        if not _UPDATE_LOCK.acquire(blocking=False):\n            if progress:\n                progress("Outra sessão está a atualizar os dados — a aguardar…", 0.0)\n            _UPDATE_LOCK.acquire()\n        try:\n            return self._update_all(include_stats, progress)\n        finally:\n            _UPDATE_LOCK.release()\n\n    def _update_all(self, include_stats: bool | None, progress: Progress | None) -> UpdateReport:\n        def p(msg: str, frac: float) -> None:\n            if progress:\n                progress(msg, frac)\n\n        rep = UpdateReport(started_at=utc_now(), previous_version=self.active_version)\n\n        p("A verificar o estado das APIs…", 0.02)\n        if not self._step_health(rep):\n            rep.online = False\n            rep.finished_at = utc_now()\n            self.db.set_kv("last_update_report", rep.to_dict())\n            return rep\n\n        p("A identificar a versão do jogo…", 0.08)\n        ver = self._step_version(rep)\n        if ver is not None:\n            rep.version = ver.version\n            if self.db.counts(self.active_version or "").get("all_items"):\n                try:\n                    self.db.backup(self.base_dir / "backups", self.cfg["backups"]["keep"])\n                except OSError as exc:  # backup falhado não bloqueia, mas fica registado\n                    rep.add(StepResult("Backup", False, f"falhou: {exc}"))\n            p("A recolher heróis…", 0.15)\n            heroes_ok = self._step_heroes(rep, ver)\n            p("A recolher itens e habilidades…", 0.30)\n            items_ok = self._step_items(rep, ver)\n            p("A recolher ranks…", 0.45)\n            self._step_ranks(rep, ver)\n            if heroes_ok and items_ok:\n                prev = self.active_version\n                self.db.set_kv("active_version", ver.version)\n                self.db.set_kv("active_version_info", asdict(ver))\n                if prev and prev != ver.version:\n                    rep.new_version = True\n                    p("A comparar com a versão anterior…", 0.5)\n                    self._step_diffs(rep, prev, ver.version)\n                p("A guardar imagens dos heróis…", 0.55)\n                self._step_images(rep, ver.version)\n\n        p("A recolher notas de patch…", 0.6)\n        self._step_patches(rep)\n        if self.data_api is not None:\n            p("A consultar a fonte secundária (Deadlock Data API)…", 0.68)\n            self._step_data_api(rep)\n\n        do_stats = self.cfg["update"]["fetch_stats_on_update"] if include_stats is None else include_stats\n        if do_stats and self.active_version:\n            p("A recolher estatísticas dos heróis iniciais…", 0.75)\n            self._step_stats(rep, p)\n\n        rep.finished_at = utc_now()\n        if rep.ok:\n            self.db.set_kv("last_success_at", rep.finished_at)\n            self.db.set_kv("last_success_ts", time.time())\n        self.db.set_kv("last_update_report", rep.to_dict())\n        p("Concluído", 1.0)\n        return rep\n\n    # ------------------------------------------------------------------ passos\n    def _step_health(self, rep: UpdateReport) -> bool:\n        res, err = self._fetch("deadlock-api/health", self.deadlock.health)\n        if res is not None and res.stale:  # resposta antiga em cache não prova que a API está acessível\n            err, res = ApiError(res.error or "sem ligação", res.url), None\n        if err is not None:\n            if err.is_network:\n                rep.add(StepResult("Estado das APIs", False,\n                                   "Sem ligação à Deadlock API — a usar os últimos dados guardados."))\n                self.db.set_kv("api_status", {"at": utc_now(), "reachable": False, "error": str(err)})\n                return False\n            rep.add(StepResult("Estado das APIs", False, f"Health check falhou ({err}); a tentar continuar."))\n            self.db.set_kv("api_status", {"at": utc_now(), "reachable": True, "error": str(err)})\n            return True\n        services = (res.data or {}).get("services") if isinstance(res.data, dict) else None\n        self.db.set_kv("api_status", {"at": utc_now(), "reachable": True, "services": services})\n        degraded = [k for k, v in (services or {}).items() if v is False]\n        msg = "Todos os serviços OK" if not degraded else f"Serviços em baixo: {\', \'.join(degraded)}"\n        rep.add(StepResult("Estado das APIs", True, msg))\n        return True\n\n    def _step_version(self, rep: UpdateReport) -> VersionInfo | None:\n        steam = None\n        res, err = self._fetch("deadlock-api/steam-info", self.deadlock.steam_info)\n        if res is not None:\n            try:\n                steam = SteamInfo.model_validate(res.data)\n            except ValueError as exc:\n                rep.add(StepResult("Versão do jogo", False, f"steam-info com formato inesperado: {exc}"))\n\n        assets_cv = None\n        warnings: list[str] = []\n        res_cv, _ = self._fetch("deadlock-api/client-versions", self.deadlock.client_versions)\n        if res_cv is not None and isinstance(res_cv.data, list) and res_cv.data:\n            if all(isinstance(v, int) for v in res_cv.data):\n                assets_cv = max(res_cv.data)\n            else:\n                warnings.append("client-versions com formato não reconhecido; a usar steam-info")\n\n        if assets_cv is not None:\n            info = VersionInfo(str(assets_cv), assets_cv, steam.client_version if steam else None,\n                               steam.version_datetime if steam else None, "assets/client-versions")\n        elif steam is not None:\n            info = VersionInfo(str(steam.client_version), None, steam.client_version, steam.version_datetime,\n                               "steam-info (assets pedidos como \'latest\')")\n        else:\n            rep.add(StepResult("Versão do jogo", False,\n                               f"Não foi possível determinar a versão ({err}). Heróis e itens não atualizados, "\n                               "porque todos os dados têm de ficar associados a uma versão."))\n            return None\n\n        is_new = self.db.upsert_game_version(info.version, info.steam_client_version, info.version_datetime,\n                                             info.source, res.data if res is not None else None)\n        rep.add(StepResult("Versão do jogo", True,\n                           f"Versão {info.version} ({info.source})" + (" — NOVA" if is_new else ""),\n                           changed=is_new, warnings=warnings))\n        return info\n\n    def _store_list(self, rep: UpdateReport, label: str, kind: str, res: FetchResult, validation: Any,\n                    ver: VersionInfo, writer: Callable[[int, str], int]) -> bool:\n        if not validation.ok:\n            rep.add(StepResult(label, False, "; ".join(validation.errors) + " — dados anteriores mantidos.",\n                               warnings=validation.warnings))\n            self.db.log_fetch(kind, res.url, res.params, False, message="validação: " + "; ".join(validation.errors))\n            return False\n        snap_id, is_new = self.db.save_snapshot(kind, ver.version, ver.source, res.url, res.data,\n                                                len(validation.records), validation.warnings, _iso(res.fetched_at))\n        n = writer(snap_id, _iso(res.fetched_at))\n        msg = f"{n} registos ({\'novos dados\' if is_new else \'sem alterações\'})"\n        if res.stale:\n            msg += " — cópia em cache (rede indisponível)"\n        rep.add(StepResult(label, True, msg, changed=is_new, stale=res.stale, warnings=validation.warnings))\n        return True\n\n    def _step_heroes(self, rep: UpdateReport, ver: VersionInfo) -> bool:\n        res, err = self._fetch("deadlock-api/heroes", self.deadlock.heroes, ver.assets_client_version, True)\n        if res is None:\n            rep.add(StepResult("Heróis", False, f"{err} — dados anteriores mantidos."))\n            return False\n        prev = self.db.latest_snapshot("heroes")\n        upd = self.cfg["update"]\n        val = validate_heroes(res.data, previous_count=prev["record_count"] if prev else None,\n                              min_count_ratio=upd["min_count_ratio"], max_invalid_fraction=upd["max_invalid_fraction"],\n                              required_names=self.cfg["heroes"]["initial"])\n        return self._store_list(rep, "Heróis", "heroes", res, val, ver,\n                                lambda sid, at: self.db.replace_heroes(ver.version, sid, val.records, res.url, at))\n\n    def _step_items(self, rep: UpdateReport, ver: VersionInfo) -> bool:\n        res, err = self._fetch("deadlock-api/items", self.deadlock.items, ver.assets_client_version)\n        if res is None:\n            rep.add(StepResult("Itens", False, f"{err} — dados anteriores mantidos."))\n            return False\n        prev = self.db.latest_snapshot("items")\n        upd = self.cfg["update"]\n        val = validate_items(res.data, previous_count=prev["record_count"] if prev else None,\n                             min_count_ratio=upd["min_count_ratio"], max_invalid_fraction=upd["max_invalid_fraction"])\n        return self._store_list(rep, "Itens", "items", res, val, ver,\n                                lambda sid, at: self.db.replace_items(ver.version, sid, val.records, res.url, at))\n\n    def _step_ranks(self, rep: UpdateReport, ver: VersionInfo) -> bool:\n        res, err = self._fetch("deadlock-api/ranks", self.deadlock.ranks, ver.assets_client_version)\n        if res is None:\n            rep.add(StepResult("Ranks", False, f"{err} — dados anteriores mantidos."))\n            return False\n        prev = self.db.latest_snapshot("ranks")\n        val = validate_ranks(res.data, previous_count=prev["record_count"] if prev else None)\n        return self._store_list(rep, "Ranks", "ranks", res, val, ver,\n                                lambda sid, at: self.db.replace_ranks(ver.version, val.records))\n\n    def _step_diffs(self, rep: UpdateReport, prev: str, new: str) -> None:\n        diffs = diff_items(self.db.items(prev), self.db.items(new), prev, new)\n        diffs += diff_heroes(self.db.heroes(prev), self.db.heroes(new), prev, new)\n        n = self.db.insert_patch_diffs(diffs)\n        rep.add(StepResult("Comparação de versões", True, f"{n} alterações registadas entre {prev} e {new}",\n                           changed=n > 0))\n\n    def _step_images(self, rep: UpdateReport, version: str) -> None:\n        img_dir = self.base_dir / "cache" / "images"\n        try:\n            img_dir.mkdir(parents=True, exist_ok=True)\n        except OSError:\n            pass\n        saved, failed = 0, 0\n        for name in self.cfg["heroes"]["initial"]:\n            hero = find_hero(self.db.heroes(version), name)\n            if not hero:\n                continue\n            images = hero.get("images") or {}\n            url = images.get("icon_hero_card") or images.get("icon_image_small")\n            if not url:\n                continue\n            ext = Path(url.split("?")[0]).suffix or ".png"\n            dest = img_dir / f"hero_{hero[\'id\']}{ext}"\n            if dest.exists():\n                continue\n            try:\n                dest.write_bytes(self.deadlock.client.get_bytes(url))\n                saved += 1\n            except (ApiError, OSError):\n                failed += 1\n        if saved or failed:\n            rep.add(StepResult("Imagens", failed == 0, f"{saved} guardadas, {failed} falharam"))\n\n    def _step_patches(self, rep: UpdateReport) -> None:\n        res, err = self._fetch("deadlock-api/patches", self.deadlock.patches)\n        if res is None:\n            rep.add(StepResult("Notas de patch", False, str(err)))\n            return\n        good = []\n        for p in res.data if isinstance(res.data, list) else []:\n            try:\n                Patch.model_validate(p)\n                good.append(p)\n            except ValueError:\n                continue\n        n = self.db.upsert_patch_notes(good)\n        rep.add(StepResult("Notas de patch", bool(good), f"{len(good)} notas, {n} novas", changed=n > 0,\n                           stale=res.stale))\n\n    def _step_data_api(self, rep: UpdateReport) -> None:\n        assert self.data_api is not None\n        for kind, fn, key in (("data_api_items", self.data_api.items, "items"),\n                              ("data_api_heroes", self.data_api.heroes, "heroes")):\n            res, err = self._fetch(f"data-api/{key}", fn)\n            label = f"Fonte secundária: {key}"\n            if res is None:\n                rep.add(StepResult(label, False, str(err)))\n                continue\n            data = res.data\n            if not (isinstance(data, dict) and isinstance(data.get(key), dict) and data[key]):\n                rep.add(StepResult(label, False, "formato inesperado — ignorado"))\n                continue\n            meta = data.get("_metadata") or {}\n            build_id = str(meta.get("build_id") or "desconhecido")\n            _, is_new = self.db.save_snapshot(kind, build_id, "data-api/_metadata.build_id", res.url, data,\n                                              len(data[key]), [], _iso(res.fetched_at))\n            rep.add(StepResult(label, True, f"{len(data[key])} registos (build {build_id[:24]}…)", changed=is_new,\n                               stale=res.stale))\n        res, _ = self._fetch("data-api/versions", self.data_api.versions)\n        if res is not None and isinstance(res.data, dict):\n            self.db.set_kv("data_api_versions", res.data)\n\n    def _step_stats(self, rep: UpdateReport, p: Progress) -> None:\n        version = self.active_version\n        heroes = self.db.heroes(version) if version else []\n        st = self.cfg["statistics"]\n        targets = [h for h in (find_hero(heroes, n) for n in self.cfg["heroes"]["initial"]) if h]\n        ok, fail = 0, 0\n        for mode in ("ranked", "unranked"):\n            f = StatsFilters(game_mode=st["game_mode"], match_mode=mode, min_matches=st["min_matches_query"])\n            try:\n                self.fetch_hero_stats(f)\n                ok += 1\n            except ApiError:\n                fail += 1\n            for h in targets:\n                try:\n                    self.fetch_item_stats(int(h["id"]), f)\n                    ok += 1\n                except ApiError:\n                    fail += 1\n        rep.add(StepResult("Estatísticas", fail == 0, f"{ok} consultas OK, {fail} falharam"))\n\n    # ------------------------------------------------------------------ estatísticas (também usadas pela UI)\n    def _stats(self, endpoint: str, fn: Callable[[], FetchResult], model: Any, f: StatsFilters,\n               hero_id: int | None) -> dict[str, Any]:\n        source = f"deadlock-api/{endpoint}"\n        res, err = self._fetch(source, fn)\n        if res is None:\n            stored = self.db.latest_stats(endpoint, f.key(), hero_id)\n            if stored is not None:\n                stored["offline"] = True\n                stored["error"] = str(err)\n                return stored\n            raise err  # type: ignore[misc]\n        rows = []\n        for r in res.data if isinstance(res.data, list) else []:\n            try:\n                rows.append(model.model_validate(r).model_dump())\n            except ValueError:\n                continue\n        if not isinstance(res.data, list):\n            raise ApiError(f"{endpoint}: resposta não é uma lista", res.url, res.status)\n        self.db.save_stats(endpoint, hero_id, f.to_params(), f.key(), self.active_version, res.url, rows,\n                           _iso(res.fetched_at), res.from_cache)\n        stored = self.db.latest_stats(endpoint, f.key(), hero_id) or {}\n        stored["offline"] = res.stale\n        stored["discarded"] = len(res.data) - len(rows)\n        return stored\n\n    def fetch_hero_stats(self, f: StatsFilters) -> dict[str, Any]:\n        return self._stats("hero-stats", lambda: self.analytics.hero_stats(f), AnalyticsHeroStats, f, None)\n\n    def fetch_item_stats(self, hero_id: int, f: StatsFilters) -> dict[str, Any]:\n        return self._stats("item-stats", lambda: self.analytics.item_stats(hero_id, f), ItemStats, f, hero_id)\n\n    def fetch_counter_stats(self, f: StatsFilters) -> dict[str, Any]:\n        return self._stats("hero-counter-stats", lambda: self.analytics.hero_counter_stats(f), HeroCounterStats, f, None)\n\n    def fetch_synergy_stats(self, f: StatsFilters) -> dict[str, Any]:\n        return self._stats("hero-synergy-stats", lambda: self.analytics.hero_synergy_stats(f), HeroSynergyStats, f, None)\n\n    def fetch_permutation_stats(self, hero_id: int, f: StatsFilters, comb_size: int = 2) -> dict[str, Any]:\n        return self._stats("item-permutation-stats",\n                           lambda: self.analytics.item_permutation_stats(hero_id, f, comb_size), ItemPermutationStats,\n                           f, hero_id)\n', 'src.data.cross_validation': '"""Validação cruzada entre a fonte principal (Deadlock API) e a secundária (Deadlock Data API).\n\nCompara o custo dos itens de loja pelo nome. As duas fontes têm identificadores\ndiferentes, por isso a correspondência é feita pelo nome normalizado; itens sem\ncorrespondência são listados, não adivinhados.\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom typing import Any\n\nfrom .normalizer import shop_items\n\n\ndef _norm(name: str | None) -> str:\n    return re.sub(r"[^a-z0-9]", "", (name or "").lower())\n\n\ndef compare_item_costs(main_items: list[dict], data_api_payload: dict[str, Any] | None) -> dict[str, Any]:\n    if not data_api_payload or not isinstance(data_api_payload.get("items"), dict):\n        return {"available": False, "reason": "sem dados da fonte secundária"}\n\n    main = {_norm(it.get("name")): it for it in shop_items(main_items)}\n    secondary: dict[str, dict] = {}\n    for rec in data_api_payload["items"].values():\n        if isinstance(rec, dict) and rec.get("available_in", "main_game") == "main_game":\n            secondary[_norm(rec.get("display_name"))] = rec\n\n    matched, mismatches = 0, []\n    for key, it in main.items():\n        rec = secondary.get(key)\n        if rec is None:\n            continue\n        matched += 1\n        if it.get("cost") != rec.get("soul_cost"):\n            mismatches.append({"item": it.get("name"), "custo (Deadlock API)": it.get("cost"),\n                               "custo (Data API)": rec.get("soul_cost"), "tier (Deadlock API)": it.get("item_tier"),\n                               "tier (Data API)": rec.get("tier")})\n    meta = data_api_payload.get("_metadata") or {}\n    return {\n        "available": True,\n        "matched": matched,\n        "mismatches": mismatches,\n        "only_main": sorted(main[k].get("name") for k in main.keys() - secondary.keys()),\n        "only_secondary": sorted(secondary[k].get("display_name") for k in secondary.keys() - main.keys()),\n        "secondary_build_id": meta.get("build_id"),\n        "secondary_captured_at": meta.get("captured_at"),\n    }\n', 'src.data.database': '"""Base de dados SQLite local.\n\nPrincípios:\n* Cada dado guarda a origem (URL), o momento da recolha e a versão do jogo.\n* As respostas brutas ficam em `snapshots` (histórico completo, deduplicado por SHA-256).\n* As tabelas normalizadas (`heroes`, `items`, `ranks`) têm uma linha por versão:\n  versões anteriores nunca são apagadas, o que permite comparar patches.\n* A versão "ativa" (a mais recente validada) fica na tabela `kv`.\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport shutil\nimport sqlite3\nfrom contextlib import contextmanager\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Iterable, Iterator\n\nSCHEMA_VERSION = 1\n\nSCHEMA = """\nCREATE TABLE IF NOT EXISTS kv (\n    key TEXT PRIMARY KEY,\n    value TEXT,\n    updated_at TEXT\n);\nCREATE TABLE IF NOT EXISTS fetch_log (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    at TEXT NOT NULL,\n    source TEXT NOT NULL,\n    url TEXT,\n    params TEXT,\n    ok INTEGER NOT NULL,\n    http_status INTEGER,\n    from_cache INTEGER DEFAULT 0,\n    stale INTEGER DEFAULT 0,\n    message TEXT\n);\nCREATE TABLE IF NOT EXISTS game_versions (\n    version TEXT PRIMARY KEY,\n    client_version INTEGER,\n    version_datetime TEXT,\n    first_seen TEXT,\n    last_seen TEXT,\n    source TEXT,\n    payload TEXT\n);\nCREATE TABLE IF NOT EXISTS snapshots (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    kind TEXT NOT NULL,\n    version TEXT,\n    version_source TEXT,\n    source_url TEXT,\n    fetched_at TEXT NOT NULL,\n    last_checked TEXT,\n    sha256 TEXT NOT NULL,\n    record_count INTEGER,\n    warnings TEXT,\n    payload TEXT NOT NULL,\n    UNIQUE(kind, version, sha256)\n);\nCREATE TABLE IF NOT EXISTS heroes (\n    hero_id INTEGER NOT NULL,\n    version TEXT NOT NULL,\n    snapshot_id INTEGER,\n    name TEXT,\n    class_name TEXT,\n    playable INTEGER,\n    source_url TEXT,\n    fetched_at TEXT,\n    payload TEXT,\n    PRIMARY KEY (hero_id, version)\n);\nCREATE TABLE IF NOT EXISTS items (\n    item_id INTEGER NOT NULL,\n    version TEXT NOT NULL,\n    snapshot_id INTEGER,\n    class_name TEXT,\n    name TEXT,\n    type TEXT,\n    slot TEXT,\n    tier INTEGER,\n    cost INTEGER,\n    is_active INTEGER,\n    shopable INTEGER,\n    disabled INTEGER,\n    hero_id INTEGER,\n    source_url TEXT,\n    fetched_at TEXT,\n    payload TEXT,\n    PRIMARY KEY (item_id, version)\n);\nCREATE INDEX IF NOT EXISTS idx_items_class ON items(class_name, version);\nCREATE TABLE IF NOT EXISTS ranks (\n    tier INTEGER NOT NULL,\n    version TEXT NOT NULL,\n    name TEXT,\n    color TEXT,\n    payload TEXT,\n    PRIMARY KEY (tier, version)\n);\nCREATE TABLE IF NOT EXISTS patch_notes (\n    guid TEXT PRIMARY KEY,\n    title TEXT,\n    pub_date TEXT,\n    link TEXT,\n    fetched_at TEXT,\n    payload TEXT\n);\nCREATE TABLE IF NOT EXISTS patch_diffs (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    from_version TEXT NOT NULL,\n    to_version TEXT NOT NULL,\n    entity_type TEXT NOT NULL,\n    entity_id INTEGER,\n    entity_name TEXT,\n    change TEXT NOT NULL,\n    field TEXT,\n    old_value TEXT,\n    new_value TEXT,\n    created_at TEXT,\n    UNIQUE(from_version, to_version, entity_type, entity_id, change, field)\n);\nCREATE TABLE IF NOT EXISTS stats_queries (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    endpoint TEXT NOT NULL,\n    hero_id INTEGER,\n    filters TEXT NOT NULL,\n    filters_key TEXT NOT NULL,\n    version TEXT,\n    source_url TEXT,\n    fetched_at TEXT NOT NULL,\n    data_fetched_at TEXT,\n    from_cache INTEGER DEFAULT 0,\n    row_count INTEGER\n);\nCREATE INDEX IF NOT EXISTS idx_stats_q ON stats_queries(endpoint, hero_id, filters_key);\nCREATE TABLE IF NOT EXISTS hero_stats (\n    query_id INTEGER NOT NULL,\n    hero_id INTEGER NOT NULL,\n    wins INTEGER, losses INTEGER, matches INTEGER,\n    payload TEXT\n);\nCREATE TABLE IF NOT EXISTS saved_builds (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    created_at TEXT NOT NULL,\n    version TEXT,\n    hero_id INTEGER,\n    hero_name TEXT,\n    name TEXT,\n    params TEXT,\n    item_ids TEXT,\n    score REAL,\n    metrics TEXT\n);\nCREATE TABLE IF NOT EXISTS generic_stats (\n    query_id INTEGER NOT NULL,\n    payload TEXT\n);\nCREATE TABLE IF NOT EXISTS item_stats (\n    query_id INTEGER NOT NULL,\n    hero_id INTEGER,\n    item_id INTEGER NOT NULL,\n    wins INTEGER, losses INTEGER, matches INTEGER, players INTEGER,\n    avg_buy_time_s REAL, avg_buy_time_relative REAL, sold INTEGER,\n    payload TEXT\n);\n"""\n\n\ndef utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat(timespec="seconds")\n\n\ndef canonical_sha256(payload: Any) -> str:\n    raw = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)\n    return hashlib.sha256(raw.encode("utf-8")).hexdigest()\n\n\nclass Database:\n    def __init__(self, path: Path | str):\n        self.path = Path(path)\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        self.init()\n\n    @contextmanager\n    def connect(self) -> Iterator[sqlite3.Connection]:\n        if not self.path.exists():  # a pasta/ficheiro desapareceu (ex.: limpeza na nuvem) -> recriar vazio\n            self._create_schema()\n        conn = sqlite3.connect(self.path, timeout=30)\n        conn.row_factory = sqlite3.Row\n        conn.execute("PRAGMA foreign_keys = ON")\n        try:\n            yield conn\n            conn.commit()\n        except Exception:\n            conn.rollback()\n            raise\n        finally:\n            conn.close()\n\n    def init(self) -> None:\n        self._create_schema()\n\n    def _create_schema(self) -> None:\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        conn = sqlite3.connect(self.path, timeout=30)\n        try:\n            conn.execute("PRAGMA journal_mode = WAL")\n            conn.executescript(SCHEMA)\n            conn.execute(f"PRAGMA user_version = {SCHEMA_VERSION}")\n            conn.commit()\n        finally:\n            conn.close()\n\n    # ---- kv ---------------------------------------------------------------\n    def get_kv(self, key: str, default: Any = None) -> Any:\n        with self.connect() as conn:\n            row = conn.execute("SELECT value FROM kv WHERE key = ?", (key,)).fetchone()\n        if row is None:\n            return default\n        try:\n            return json.loads(row["value"])\n        except (TypeError, json.JSONDecodeError):\n            return row["value"]\n\n    def set_kv(self, key: str, value: Any) -> None:\n        with self.connect() as conn:\n            conn.execute(\n                "INSERT INTO kv(key, value, updated_at) VALUES(?,?,?) "\n                "ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at",\n                (key, json.dumps(value, ensure_ascii=False), utc_now()),\n            )\n\n    # ---- log --------------------------------------------------------------\n    def log_fetch(\n        self, source: str, url: str | None, params: dict | None, ok: bool, *,\n        http_status: int | None = None, from_cache: bool = False, stale: bool = False, message: str = "",\n    ) -> None:\n        with self.connect() as conn:\n            conn.execute(\n                "INSERT INTO fetch_log(at, source, url, params, ok, http_status, from_cache, stale, message) "\n                "VALUES(?,?,?,?,?,?,?,?,?)",\n                (utc_now(), source, url, json.dumps(params or {}), int(ok), http_status,\n                 int(from_cache), int(stale), message[:2000]),\n            )\n\n    def fetch_log(self, limit: int = 200) -> list[dict]:\n        with self.connect() as conn:\n            rows = conn.execute("SELECT * FROM fetch_log ORDER BY id DESC LIMIT ?", (limit,)).fetchall()\n        return [dict(r) for r in rows]\n\n    # ---- versões ----------------------------------------------------------\n    def upsert_game_version(self, version: str, client_version: int | None, version_datetime: str | None,\n                            source: str, payload: Any) -> bool:\n        """Regista uma versão. Devolve True se for nova."""\n        now = utc_now()\n        with self.connect() as conn:\n            exists = conn.execute("SELECT 1 FROM game_versions WHERE version = ?", (version,)).fetchone()\n            if exists:\n                conn.execute("UPDATE game_versions SET last_seen = ? WHERE version = ?", (now, version))\n                return False\n            conn.execute(\n                "INSERT INTO game_versions(version, client_version, version_datetime, first_seen, last_seen, "\n                "source, payload) VALUES(?,?,?,?,?,?,?)",\n                (version, client_version, version_datetime, now, now, source, json.dumps(payload)),\n            )\n            return True\n\n    def game_versions(self) -> list[dict]:\n        with self.connect() as conn:\n            rows = conn.execute(\n                "SELECT version, client_version, version_datetime, first_seen, last_seen, source "\n                "FROM game_versions ORDER BY first_seen DESC"\n            ).fetchall()\n        return [dict(r) for r in rows]\n\n    def versions_with_data(self, kind: str = "items") -> list[str]:\n        table = "items" if kind == "items" else "heroes"\n        with self.connect() as conn:\n            rows = conn.execute(\n                f"SELECT version, MIN(fetched_at) AS f FROM {table} GROUP BY version ORDER BY f DESC"\n            ).fetchall()\n        return [r["version"] for r in rows]\n\n    # ---- snapshots --------------------------------------------------------\n    def latest_snapshot(self, kind: str, version: str | None = None) -> dict | None:\n        q = "SELECT * FROM snapshots WHERE kind = ?"\n        args: list[Any] = [kind]\n        if version is not None:\n            q += " AND version = ?"\n            args.append(version)\n        q += " ORDER BY id DESC LIMIT 1"\n        with self.connect() as conn:\n            row = conn.execute(q, args).fetchone()\n        if row is None:\n            return None\n        out = dict(row)\n        out["payload"] = json.loads(out["payload"])\n        out["warnings"] = json.loads(out["warnings"] or "[]")\n        return out\n\n    def snapshot_meta(self, kind: str | None = None) -> list[dict]:\n        q = ("SELECT id, kind, version, version_source, source_url, fetched_at, last_checked, sha256, "\n             "record_count FROM snapshots")\n        args: list[Any] = []\n        if kind:\n            q += " WHERE kind = ?"\n            args.append(kind)\n        q += " ORDER BY id DESC"\n        with self.connect() as conn:\n            return [dict(r) for r in conn.execute(q, args).fetchall()]\n\n    def save_snapshot(self, kind: str, version: str | None, version_source: str, source_url: str,\n                      payload: Any, record_count: int, warnings: list[str] | None = None,\n                      fetched_at: str | None = None) -> tuple[int, bool]:\n        """Guarda a resposta bruta. Devolve (id, é_nova). Respostas idênticas não são duplicadas."""\n        sha = canonical_sha256(payload)\n        now = utc_now()\n        with self.connect() as conn:\n            row = conn.execute(\n                "SELECT id FROM snapshots WHERE kind = ? AND IFNULL(version,\'\') = IFNULL(?, \'\') AND sha256 = ?",\n                (kind, version, sha),\n            ).fetchone()\n            if row:\n                conn.execute("UPDATE snapshots SET last_checked = ? WHERE id = ?", (now, row["id"]))\n                return int(row["id"]), False\n            try:\n                cur = conn.execute(\n                    "INSERT INTO snapshots(kind, version, version_source, source_url, fetched_at, last_checked, "\n                    "sha256, record_count, warnings, payload) VALUES(?,?,?,?,?,?,?,?,?,?)",\n                    (kind, version, version_source, source_url, fetched_at or now, now, sha, record_count,\n                     json.dumps(warnings or [], ensure_ascii=False), json.dumps(payload, ensure_ascii=False)),\n                )\n            except sqlite3.IntegrityError:  # outra sessão guardou a mesma resposta entretanto\n                row = conn.execute(\n                    "SELECT id FROM snapshots WHERE kind = ? AND IFNULL(version,\'\') = IFNULL(?, \'\') AND sha256 = ?",\n                    (kind, version, sha),\n                ).fetchone()\n                if row is None:\n                    raise\n                return int(row["id"]), False\n            return int(cur.lastrowid), True\n\n    # ---- heróis / itens / ranks -------------------------------------------\n    def replace_heroes(self, version: str, snapshot_id: int, heroes: Iterable[dict], source_url: str,\n                       fetched_at: str) -> int:\n        rows = [\n            (h["id"], version, snapshot_id, h.get("name"), h.get("class_name"),\n             int(bool(h.get("player_selectable", True)) and not h.get("disabled") and not h.get("in_development")),\n             source_url, fetched_at, json.dumps(h, ensure_ascii=False))\n            for h in heroes\n        ]\n        with self.connect() as conn:\n            conn.execute("DELETE FROM heroes WHERE version = ?", (version,))\n            conn.executemany(\n                "INSERT INTO heroes(hero_id, version, snapshot_id, name, class_name, playable, source_url, "\n                "fetched_at, payload) VALUES(?,?,?,?,?,?,?,?,?)", rows)\n        return len(rows)\n\n    def replace_items(self, version: str, snapshot_id: int, items: Iterable[dict], source_url: str,\n                      fetched_at: str) -> int:\n        rows = []\n        for it in items:\n            rows.append((\n                it["id"], version, snapshot_id, it.get("class_name"), it.get("name"), it.get("type"),\n                it.get("item_slot_type"), it.get("item_tier"), it.get("cost"),\n                None if it.get("is_active_item") is None else int(bool(it.get("is_active_item"))),\n                None if it.get("shopable") is None else int(bool(it.get("shopable"))),\n                None if it.get("disabled") is None else int(bool(it.get("disabled"))),\n                it.get("hero"), source_url, fetched_at, json.dumps(it, ensure_ascii=False),\n            ))\n        with self.connect() as conn:\n            conn.execute("DELETE FROM items WHERE version = ?", (version,))\n            conn.executemany(\n                "INSERT INTO items(item_id, version, snapshot_id, class_name, name, type, slot, tier, cost, "\n                "is_active, shopable, disabled, hero_id, source_url, fetched_at, payload) "\n                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", rows)\n        return len(rows)\n\n    def replace_ranks(self, version: str, ranks: Iterable[dict]) -> int:\n        rows = [(r["tier"], version, r.get("name"), r.get("color"), json.dumps(r, ensure_ascii=False))\n                for r in ranks]\n        with self.connect() as conn:\n            conn.execute("DELETE FROM ranks WHERE version = ?", (version,))\n            conn.executemany("INSERT INTO ranks(tier, version, name, color, payload) VALUES(?,?,?,?,?)", rows)\n        return len(rows)\n\n    def heroes(self, version: str) -> list[dict]:\n        with self.connect() as conn:\n            rows = conn.execute(\n                "SELECT payload, source_url, fetched_at FROM heroes WHERE version = ? ORDER BY name", (version,)\n            ).fetchall()\n        out = []\n        for r in rows:\n            h = json.loads(r["payload"])\n            h["_source_url"], h["_fetched_at"], h["_version"] = r["source_url"], r["fetched_at"], version\n            out.append(h)\n        return out\n\n    def items(self, version: str, item_type: str | None = None) -> list[dict]:\n        q = "SELECT payload, source_url, fetched_at FROM items WHERE version = ?"\n        args: list[Any] = [version]\n        if item_type:\n            q += " AND type = ?"\n            args.append(item_type)\n        with self.connect() as conn:\n            rows = conn.execute(q, args).fetchall()\n        out = []\n        for r in rows:\n            it = json.loads(r["payload"])\n            it["_source_url"], it["_fetched_at"], it["_version"] = r["source_url"], r["fetched_at"], version\n            out.append(it)\n        return out\n\n    def ranks(self, version: str) -> list[dict]:\n        with self.connect() as conn:\n            rows = conn.execute("SELECT payload FROM ranks WHERE version = ? ORDER BY tier", (version,)).fetchall()\n        return [json.loads(r["payload"]) for r in rows]\n\n    def counts(self, version: str) -> dict[str, int]:\n        with self.connect() as conn:\n            heroes = conn.execute(\n                "SELECT COUNT(*) c FROM heroes WHERE version = ? AND playable = 1", (version,)).fetchone()["c"]\n            items = conn.execute(\n                "SELECT COUNT(*) c FROM items WHERE version = ? AND type = \'upgrade\' AND shopable = 1 "\n                "AND IFNULL(disabled, 0) = 0", (version,)).fetchone()["c"]\n            all_items = conn.execute("SELECT COUNT(*) c FROM items WHERE version = ?", (version,)).fetchone()["c"]\n        return {"heroes": heroes, "shop_items": items, "all_items": all_items}\n\n    # ---- patches ------------------------------------------------------------\n    def upsert_patch_notes(self, patches: Iterable[dict]) -> int:\n        now = utc_now()\n        new = 0\n        with self.connect() as conn:\n            for p in patches:\n                guid = (p.get("guid") or {}).get("text") or p.get("link")\n                cur = conn.execute(\n                    "INSERT OR IGNORE INTO patch_notes(guid, title, pub_date, link, fetched_at, payload) "\n                    "VALUES(?,?,?,?,?,?)",\n                    (guid, p.get("title"), p.get("pub_date"), p.get("link"), now, json.dumps(p, ensure_ascii=False)),\n                )\n                new += cur.rowcount\n        return new\n\n    def patch_notes(self, limit: int = 50) -> list[dict]:\n        with self.connect() as conn:\n            rows = conn.execute(\n                "SELECT guid, title, pub_date, link, fetched_at FROM patch_notes ORDER BY pub_date DESC LIMIT ?",\n                (limit,)).fetchall()\n        return [dict(r) for r in rows]\n\n    def insert_patch_diffs(self, diffs: Iterable[dict]) -> int:\n        now = utc_now()\n        n = 0\n        with self.connect() as conn:\n            for d in diffs:\n                cur = conn.execute(\n                    "INSERT OR IGNORE INTO patch_diffs(from_version, to_version, entity_type, entity_id, "\n                    "entity_name, change, field, old_value, new_value, created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",\n                    (d["from_version"], d["to_version"], d["entity_type"], d.get("entity_id"),\n                     d.get("entity_name"), d["change"], d.get("field"),\n                     None if d.get("old_value") is None else str(d.get("old_value")),\n                     None if d.get("new_value") is None else str(d.get("new_value")), now),\n                )\n                n += cur.rowcount\n        return n\n\n    def patch_diffs(self, from_version: str | None = None, to_version: str | None = None,\n                    limit: int = 5000) -> list[dict]:\n        q = "SELECT * FROM patch_diffs"\n        args: list[Any] = []\n        conds = []\n        if from_version:\n            conds.append("from_version = ?")\n            args.append(from_version)\n        if to_version:\n            conds.append("to_version = ?")\n            args.append(to_version)\n        if conds:\n            q += " WHERE " + " AND ".join(conds)\n        q += " ORDER BY id DESC LIMIT ?"\n        args.append(limit)\n        with self.connect() as conn:\n            return [dict(r) for r in conn.execute(q, args).fetchall()]\n\n    # ---- estatísticas -------------------------------------------------------\n    def save_stats(self, endpoint: str, hero_id: int | None, filters: dict, filters_key: str,\n                   version: str | None, source_url: str, rows: list[dict], data_fetched_at: str,\n                   from_cache: bool) -> int:\n        with self.connect() as conn:\n            cur = conn.execute(\n                "INSERT INTO stats_queries(endpoint, hero_id, filters, filters_key, version, source_url, "\n                "fetched_at, data_fetched_at, from_cache, row_count) VALUES(?,?,?,?,?,?,?,?,?,?)",\n                (endpoint, hero_id, json.dumps(filters, sort_keys=True), filters_key, version, source_url,\n                 utc_now(), data_fetched_at, int(from_cache), len(rows)),\n            )\n            qid = int(cur.lastrowid)\n            if endpoint == "hero-stats":\n                conn.executemany(\n                    "INSERT INTO hero_stats(query_id, hero_id, wins, losses, matches, payload) VALUES(?,?,?,?,?,?)",\n                    [(qid, r["hero_id"], r["wins"], r["losses"], r["matches"], json.dumps(r)) for r in rows])\n            elif endpoint == "item-stats":\n                conn.executemany(\n                    "INSERT INTO item_stats(query_id, hero_id, item_id, wins, losses, matches, players, "\n                    "avg_buy_time_s, avg_buy_time_relative, sold, payload) VALUES(?,?,?,?,?,?,?,?,?,?,?)",\n                    [(qid, hero_id, r["item_id"], r["wins"], r["losses"], r["matches"], r.get("players"),\n                      r.get("avg_buy_time_s"), r.get("avg_buy_time_relative"), r.get("sold"), json.dumps(r))\n                     for r in rows])\n            else:\n                conn.executemany("INSERT INTO generic_stats(query_id, payload) VALUES(?,?)",\n                                 [(qid, json.dumps(r)) for r in rows])\n        return qid\n\n    def latest_stats(self, endpoint: str, filters_key: str, hero_id: int | None = None) -> dict | None:\n        q = "SELECT * FROM stats_queries WHERE endpoint = ? AND filters_key = ?"\n        args: list[Any] = [endpoint, filters_key]\n        if hero_id is not None:\n            q += " AND hero_id = ?"\n            args.append(hero_id)\n        q += " ORDER BY id DESC LIMIT 1"\n        with self.connect() as conn:\n            meta = conn.execute(q, args).fetchone()\n            if meta is None:\n                return None\n            table = {"hero-stats": "hero_stats", "item-stats": "item_stats"}.get(endpoint, "generic_stats")\n            rows = conn.execute(f"SELECT payload FROM {table} WHERE query_id = ?", (meta["id"],)).fetchall()\n        out = dict(meta)\n        out["filters"] = json.loads(out["filters"])\n        out["rows"] = [json.loads(r["payload"]) for r in rows]\n        return out\n\n    def stats_examples(self) -> dict[str, Any]:\n        """Uma linha de exemplo de cada tipo de estatística guardada (para diagnóstico)."""\n        out: dict[str, Any] = {}\n        with self.connect() as conn:\n            for table in ("hero_stats", "item_stats", "generic_stats"):\n                row = conn.execute(f"SELECT payload FROM {table} ORDER BY rowid DESC LIMIT 1").fetchone()\n                out[table] = json.loads(row["payload"]) if row else None\n        return out\n\n    def stats_query_count(self) -> int:\n        with self.connect() as conn:\n            return int(conn.execute("SELECT COUNT(*) c FROM stats_queries").fetchone()["c"])\n\n    # ---- builds guardadas ---------------------------------------------------\n    def save_build(self, version: str | None, hero_id: int, hero_name: str, name: str, params: dict,\n                   item_ids: list[int], score: float, metrics: dict) -> int:\n        with self.connect() as conn:\n            cur = conn.execute(\n                "INSERT INTO saved_builds(created_at, version, hero_id, hero_name, name, params, item_ids, score, metrics) "\n                "VALUES(?,?,?,?,?,?,?,?,?)",\n                (utc_now(), version, hero_id, hero_name, name, json.dumps(params, ensure_ascii=False),\n                 json.dumps(item_ids), score, json.dumps(metrics)))\n            return int(cur.lastrowid)\n\n    def saved_builds(self, hero_id: int | None = None) -> list[dict]:\n        q = "SELECT * FROM saved_builds"\n        args: list[Any] = []\n        if hero_id is not None:\n            q += " WHERE hero_id = ?"\n            args.append(hero_id)\n        q += " ORDER BY id DESC"\n        with self.connect() as conn:\n            rows = [dict(r) for r in conn.execute(q, args).fetchall()]\n        for r in rows:\n            r["params"] = json.loads(r["params"] or "{}")\n            r["item_ids"] = json.loads(r["item_ids"] or "[]")\n            r["metrics"] = json.loads(r["metrics"] or "{}")\n        return rows\n\n    def delete_build(self, build_id: int) -> None:\n        with self.connect() as conn:\n            conn.execute("DELETE FROM saved_builds WHERE id = ?", (build_id,))\n\n    def saved_build_count(self) -> int:\n        with self.connect() as conn:\n            return int(conn.execute("SELECT COUNT(*) c FROM saved_builds").fetchone()["c"])\n\n    # ---- backups ------------------------------------------------------------\n    def backup(self, backup_dir: Path, keep: int = 10) -> Path:\n        backup_dir.mkdir(parents=True, exist_ok=True)\n        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n        dest = backup_dir / f"deadlock_{stamp}.db"\n        src = sqlite3.connect(self.path)\n        dst = sqlite3.connect(dest)\n        try:\n            src.backup(dst)\n        finally:\n            dst.close()\n            src.close()\n        backups = sorted(backup_dir.glob("deadlock_*.db"))\n        for old in backups[:-keep] if keep > 0 else []:\n            try:\n                old.unlink()\n            except OSError:\n                pass\n        return dest\n\n    def restore(self, backup_file: Path) -> None:\n        shutil.copy2(backup_file, self.path)\n', 'src.data.normalizer': '"""Transforma os JSON brutos (já validados) em vistas prontas para análise e UI.\n\nNada aqui estima valores: se um dado não existe na resposta, devolve-se None e a UI\nmostra "desconhecido".\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom ..models.common import to_number\nfrom ..models.hero import STARTING_STAT_LABELS_PT\nfrom ..models.item import SLOT_LABELS_PT\n\nWEAPON_INFO_LABELS_PT = {\n    "damage_per_second": "DPS (valor da API)",\n    "damage_per_second_with_reload": "DPS com recarga (valor da API)",\n    "bullet_damage": "Dano por bala",\n    "bullets": "Projéteis por disparo",\n    "bullets_per_second": "Balas por segundo",\n    "shots_per_second": "Disparos por segundo",\n    "damage_per_shot": "Dano por disparo",\n    "damage_per_magazine": "Dano por carregador",\n    "clip_size": "Carregador",\n    "reload_duration": "Tempo de recarga (s)",\n    "cycle_time": "Tempo de ciclo (s)",\n    "burst_shot_count": "Tiros por rajada",\n    "crit_bonus_start": "Bónus crítico (início)",\n    "crit_bonus_end": "Bónus crítico (fim)",\n    "damage_falloff_start_range": "Queda de dano — início",\n    "damage_falloff_end_range": "Queda de dano — fim",\n    "damage_falloff_end_scale": "Escala de dano no fim da queda",\n    "bullet_speed": "Velocidade da bala",\n    "range": "Alcance",\n}\n\n\ndef index_by_class(items: list[dict]) -> dict[str, dict]:\n    return {it["class_name"]: it for it in items if it.get("class_name")}\n\n\ndef index_by_id(items: list[dict]) -> dict[int, dict]:\n    return {int(it["id"]): it for it in items if it.get("id") is not None}\n\n\ndef find_hero(heroes: list[dict], name: str) -> dict | None:\n    target = name.strip().lower()\n    for h in heroes:\n        if str(h.get("name", "")).strip().lower() == target:\n            return h\n    return None\n\n\n# ---- propriedades --------------------------------------------------------------\ndef describe_scaling(prop: dict[str, Any] | None) -> str | None:\n    sf = (prop or {}).get("scale_function") or None\n    if not sf:\n        return None\n    scale = sf.get("stat_scale")\n    stat = sf.get("specific_stat_scale_type") or ", ".join(sf.get("scaling_stats") or []) or None\n    if scale is None and stat is None:\n        return None\n    if scale is None:\n        return f"escala com {stat} (fator desconhecido)"\n    return f"{scale:g} × {stat or \'stat desconhecido\'}"\n\n\ndef find_property(props: dict[str, Any] | None, candidates: list[str]) -> dict | None:\n    for key in candidates:\n        prop = (props or {}).get(key)\n        if prop is not None:\n            raw = prop.get("value")\n            return {"key": key, "value": to_number(raw), "raw": raw, "unit": prop.get("postfix"),\n                    "scaling": describe_scaling(prop)}\n    return None\n\n\ndef property_rows(props: dict[str, Any] | None) -> list[dict]:\n    rows = []\n    for key, prop in sorted((props or {}).items()):\n        if not isinstance(prop, dict):\n            continue\n        raw = prop.get("value")\n        rows.append({\n            "propriedade": key,\n            "rótulo": prop.get("label"),\n            "valor": raw,\n            "numérico": to_number(raw),\n            "unidade": prop.get("postfix") or prop.get("display_units"),\n            "escala": describe_scaling(prop),\n            "condicional": prop.get("conditional"),\n        })\n    return rows\n\n\ndef upgrade_rows(item: dict) -> list[dict]:\n    rows = []\n    for tier, up in enumerate(item.get("upgrades") or [], start=1):\n        for pu in (up or {}).get("property_upgrades") or []:\n            rows.append({\n                "melhoria": f"T{tier}",\n                "propriedade": pu.get("name"),\n                "bónus": pu.get("bonus"),\n                "tipo": pu.get("upgrade_type"),\n                "filtro de escala": pu.get("scale_stat_filter"),\n            })\n    return rows\n\n\n# ---- herói -----------------------------------------------------------------------\ndef hero_base_stats(hero: dict) -> list[dict]:\n    rows = []\n    for key, stat in (hero.get("starting_stats") or {}).items():\n        rows.append({\n            "chave": key,\n            "estatística": STARTING_STAT_LABELS_PT.get(key, key),\n            "nome interno": (stat or {}).get("display_stat_name"),\n            "valor": None if stat is None else stat.get("value"),\n        })\n    return rows\n\n\ndef hero_level_gains(hero: dict) -> list[dict]:\n    return [{"chave": k, "ganho por nível": v} for k, v in sorted((hero.get("standard_level_up_upgrades") or {}).items())]\n\n\ndef hero_weapon(hero: dict, items_by_class: dict[str, dict]) -> dict | None:\n    slots = hero.get("items") or {}\n    cls = slots.get("weapon_primary")\n    if cls is None:\n        cls = next((v for k, v in sorted(slots.items()) if k.startswith("weapon_primary")), None)\n    weapon = items_by_class.get(cls) if cls else None\n    if weapon is None:\n        weapon = next((it for it in items_by_class.values()\n                       if it.get("type") == "weapon" and it.get("hero") == hero.get("id")), None)\n    if weapon is None:\n        return None\n    info = weapon.get("weapon_info") or {}\n    rows = [{"chave": k, "estatística": label, "valor": info.get(k)}\n            for k, label in WEAPON_INFO_LABELS_PT.items() if k in info]\n    return {"name": weapon.get("name"), "class_name": weapon.get("class_name"), "rows": rows,\n            "weapon_info": info, "properties": property_rows(weapon.get("properties"))}\n\n\ndef hero_abilities(hero: dict, items_by_class: dict[str, dict], prop_keys: dict[str, list[str]]) -> list[dict]:\n    slots = hero.get("items") or {}\n    sig_keys = sorted(k for k in slots if k.startswith("signature"))\n    abilities: list[tuple[str, str | None, dict | None]] = [(k, slots[k], items_by_class.get(slots[k])) for k in sig_keys]\n    if not abilities:  # recurso: procurar pelo herói nos itens do tipo ability\n        found = [it for it in items_by_class.values()\n                 if it.get("type") == "ability" and it.get("hero") == hero.get("id")\n                 and it.get("ability_type") in ("signature", "ultimate")]\n        abilities = [(f"ability_{i + 1}", it.get("class_name"), it) for i, it in enumerate(found)]\n\n    out = []\n    for slot, cls, it in abilities:\n        if it is None:\n            out.append({"slot": slot, "class_name": cls, "name": cls, "missing": True})\n            continue\n        props = it.get("properties") or {}\n        entry = {\n            "slot": slot,\n            "class_name": cls,\n            "name": it.get("name"),\n            "ability_type": it.get("ability_type"),\n            "image": it.get("image_webp") or it.get("image"),\n            "missing": False,\n            "properties": property_rows(props),\n            "upgrades": upgrade_rows(it),\n        }\n        for field, candidates in prop_keys.items():\n            entry[field] = find_property(props, candidates)\n        entry["scaling"] = [r for r in entry["properties"] if r["escala"]]\n        out.append(entry)\n    return out\n\n\ndef hero_data_completeness(hero: dict, weapon: dict | None, abilities: list[dict]) -> list[dict]:\n    """Diagnóstico: que entradas do futuro simulador estão disponíveis nos dados atuais."""\n    ss = hero.get("starting_stats") or {}\n\n    def has(key: str) -> bool:\n        return ss.get(key) is not None and ss[key].get("value") is not None\n\n    info = (weapon or {}).get("weapon_info") or {}\n    checks = [\n        ("Vida base", has("max_health")),\n        ("Regeneração base", has("base_health_regen")),\n        ("Resistência a balas", has("bullet_armor_damage_reduction")),\n        ("Resistência Spirit", has("tech_armor_damage_reduction")),\n        ("Velocidade de movimento", has("max_move_speed")),\n        ("Arma: dano por bala", info.get("bullet_damage") is not None),\n        ("Arma: cadência", info.get("bullets_per_second") is not None or info.get("cycle_time") is not None),\n        ("Arma: carregador / recarga", info.get("clip_size") is not None and info.get("reload_duration") is not None),\n        ("Arma: queda de dano", info.get("damage_falloff_start_range") is not None),\n        ("Ganhos por nível", bool(hero.get("standard_level_up_upgrades"))),\n        ("Bónus por investimento em slots", bool(hero.get("purchase_bonuses"))),\n        ("4 habilidades encontradas", sum(1 for a in abilities if not a.get("missing")) >= 4),\n        ("Cooldowns de todas as habilidades", bool(abilities) and all(a.get("cooldown") for a in abilities if not a.get("missing"))),\n        ("Escalamento Spirit nas habilidades", any(a.get("scaling") for a in abilities)),\n    ]\n    return [{"entrada": name, "disponível": ok} for name, ok in checks]\n\n\n# ---- itens de loja ---------------------------------------------------------------\ndef shop_items(items: list[dict]) -> list[dict]:\n    return [it for it in items if it.get("type") == "upgrade" and it.get("shopable") and not it.get("disabled")]\n\n\ndef item_catalog(items: list[dict]) -> list[dict]:\n    by_class = index_by_class(items)\n    rows = []\n    for it in shop_items(items):\n        comps = [by_class.get(c, {}).get("name", c) for c in (it.get("component_items") or [])]\n        props = it.get("properties") or {}\n        scaled = [k for k, p in props.items() if isinstance(p, dict) and describe_scaling(p)]\n        rows.append({\n            "id": it.get("id"),\n            "item": it.get("name"),\n            "slot": SLOT_LABELS_PT.get(it.get("item_slot_type"), it.get("item_slot_type")),\n            "tier": it.get("item_tier"),\n            "custo": it.get("cost"),\n            "ativo": bool(it.get("is_active_item")),\n            "componentes": ", ".join(comps) if comps else "",\n            "nº propriedades": len(props),\n            "propriedades com escala": ", ".join(scaled),\n            "class_name": it.get("class_name"),\n        })\n    rows.sort(key=lambda r: (str(r["slot"]), r["tier"] or 0, r["custo"] or 0, str(r["item"])))\n    return rows\n', 'src.data.patch_tracker': '"""Comparação entre versões (patches): o que mudou em itens, habilidades e heróis.\n\nOs diffs ficam guardados em `patch_diffs` e servem, nas fases seguintes, para saber\nque cálculos e builds são afetados por um patch.\n"""\n\nfrom __future__ import annotations\n\nimport json\nfrom typing import Any\n\nITEM_FIELDS = ("name", "cost", "item_tier", "item_slot_type", "shopable", "disabled", "is_active_item",\n               "activation", "ability_type")\n\n\ndef _j(value: Any) -> str | None:\n    if value is None:\n        return None\n    if isinstance(value, (dict, list)):\n        return json.dumps(value, sort_keys=True, ensure_ascii=False)\n    return str(value)\n\n\ndef _prop_signature(prop: Any) -> dict[str, Any]:\n    if not isinstance(prop, dict):\n        return {"value": prop}\n    sf = prop.get("scale_function") or {}\n    return {"value": prop.get("value"), "stat_scale": sf.get("stat_scale"),\n            "scale_stat": sf.get("specific_stat_scale_type")}\n\n\ndef _upgrade_signature(item: dict) -> list[list[tuple]]:\n    out = []\n    for up in item.get("upgrades") or []:\n        out.append(sorted((str(p.get("name")), _j(p.get("bonus"))) for p in (up or {}).get("property_upgrades") or []))\n    return out\n\n\ndef diff_items(old: list[dict], new: list[dict], from_version: str, to_version: str) -> list[dict]:\n    o = {int(i["id"]): i for i in old}\n    n = {int(i["id"]): i for i in new}\n    base = {"from_version": from_version, "to_version": to_version}\n    diffs: list[dict] = []\n\n    def etype(it: dict) -> str:\n        return "ability" if it.get("type") == "ability" else ("weapon" if it.get("type") == "weapon" else "item")\n\n    for iid in sorted(n.keys() - o.keys()):\n        it = n[iid]\n        diffs.append({**base, "entity_type": etype(it), "entity_id": iid, "entity_name": it.get("name"),\n                      "change": "added", "field": None, "old_value": None, "new_value": it.get("cost")})\n    for iid in sorted(o.keys() - n.keys()):\n        it = o[iid]\n        diffs.append({**base, "entity_type": etype(it), "entity_id": iid, "entity_name": it.get("name"),\n                      "change": "removed", "field": None, "old_value": it.get("cost"), "new_value": None})\n    for iid in sorted(o.keys() & n.keys()):\n        a, b = o[iid], n[iid]\n        name = b.get("name")\n        for f in ITEM_FIELDS:\n            if _j(a.get(f)) != _j(b.get(f)):\n                diffs.append({**base, "entity_type": etype(b), "entity_id": iid, "entity_name": name,\n                              "change": "field", "field": f, "old_value": _j(a.get(f)), "new_value": _j(b.get(f))})\n        pa, pb = a.get("properties") or {}, b.get("properties") or {}\n        for key in sorted(set(pa) | set(pb)):\n            sa, sb = _prop_signature(pa.get(key)), _prop_signature(pb.get(key))\n            if key not in pa or key not in pb or sa != sb:\n                diffs.append({**base, "entity_type": etype(b), "entity_id": iid, "entity_name": name,\n                              "change": "property", "field": key,\n                              "old_value": _j(sa) if key in pa else None, "new_value": _j(sb) if key in pb else None})\n        ua, ub = _upgrade_signature(a), _upgrade_signature(b)\n        if ua != ub:\n            diffs.append({**base, "entity_type": etype(b), "entity_id": iid, "entity_name": name,\n                          "change": "upgrades", "field": "upgrades", "old_value": _j(ua), "new_value": _j(ub)})\n    return diffs\n\n\ndef diff_heroes(old: list[dict], new: list[dict], from_version: str, to_version: str) -> list[dict]:\n    o = {int(h["id"]): h for h in old}\n    n = {int(h["id"]): h for h in new}\n    base = {"from_version": from_version, "to_version": to_version, "entity_type": "hero"}\n    diffs: list[dict] = []\n    for hid in sorted(n.keys() - o.keys()):\n        diffs.append({**base, "entity_id": hid, "entity_name": n[hid].get("name"), "change": "added"})\n    for hid in sorted(o.keys() - n.keys()):\n        diffs.append({**base, "entity_id": hid, "entity_name": o[hid].get("name"), "change": "removed"})\n    for hid in sorted(o.keys() & n.keys()):\n        a, b = o[hid], n[hid]\n        name = b.get("name")\n        sa, sb = a.get("starting_stats") or {}, b.get("starting_stats") or {}\n        for key in sorted(set(sa) | set(sb)):\n            va = (sa.get(key) or {}).get("value") if sa.get(key) else None\n            vb = (sb.get(key) or {}).get("value") if sb.get(key) else None\n            if va != vb:\n                diffs.append({**base, "entity_id": hid, "entity_name": name, "change": "starting_stat",\n                              "field": key, "old_value": va, "new_value": vb})\n        la, lb = a.get("standard_level_up_upgrades") or {}, b.get("standard_level_up_upgrades") or {}\n        for key in sorted(set(la) | set(lb)):\n            if la.get(key) != lb.get(key):\n                diffs.append({**base, "entity_id": hid, "entity_name": name, "change": "level_up",\n                              "field": key, "old_value": la.get(key), "new_value": lb.get(key)})\n        ia, ib = a.get("items") or {}, b.get("items") or {}\n        for key in sorted(set(ia) | set(ib)):\n            if ia.get(key) != ib.get(key):\n                diffs.append({**base, "entity_id": hid, "entity_name": name, "change": "slot",\n                              "field": key, "old_value": ia.get(key), "new_value": ib.get(key)})\n        if _j(a.get("purchase_bonuses")) != _j(b.get("purchase_bonuses")):\n            diffs.append({**base, "entity_id": hid, "entity_name": name, "change": "field",\n                          "field": "purchase_bonuses", "old_value": _j(a.get("purchase_bonuses")),\n                          "new_value": _j(b.get("purchase_bonuses"))})\n    return diffs\n\n\ndef affected_entities(diffs: list[dict], item_ids: set[int] | None = None, hero_ids: set[int] | None = None\n                      ) -> list[dict]:\n    """Filtra os diffs que tocam num conjunto de itens/heróis (ex.: itens de uma build)."""\n    out = []\n    for d in diffs:\n        eid = d.get("entity_id")\n        if d["entity_type"] == "hero" and hero_ids and eid in hero_ids:\n            out.append(d)\n        elif d["entity_type"] != "hero" and item_ids and eid in item_ids:\n            out.append(d)\n    return out\n', 'src.data.validation': '"""Validação das respostas antes de qualquer escrita na base de dados.\n\nUma resposta só substitui dados existentes se:\n1. tiver a forma esperada (lista de objetos);\n2. pelo menos (1 - max_invalid_fraction) dos registos passarem a validação de esquema;\n3. o número de registos válidos não cair abaixo de min_count_ratio × contagem anterior.\nCaso contrário é rejeitada e os dados anteriores mantêm-se intactos.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any, Callable\n\nfrom pydantic import ValidationError\n\nfrom ..models.hero import DOCUMENTED_REQUIRED, Hero\nfrom ..models.item import parse_item\nfrom ..models.meta import Rank\n\n\n@dataclass\nclass ValidationResult:\n    ok: bool\n    records: list[dict] = field(default_factory=list)\n    errors: list[str] = field(default_factory=list)\n    warnings: list[str] = field(default_factory=list)\n\n\ndef _validate_list(\n    payload: Any,\n    validator: Callable[[dict], Any],\n    *,\n    label: str,\n    previous_count: int | None,\n    min_count_ratio: float,\n    max_invalid_fraction: float,\n) -> ValidationResult:\n    if not isinstance(payload, list):\n        return ValidationResult(False, errors=[f"{label}: esperava uma lista, recebi {type(payload).__name__}"])\n    if not payload:\n        return ValidationResult(False, errors=[f"{label}: resposta vazia"])\n\n    good: list[dict] = []\n    bad: list[str] = []\n    for i, raw in enumerate(payload):\n        if not isinstance(raw, dict):\n            bad.append(f"#{i}: não é objeto")\n            continue\n        try:\n            validator(raw)\n            good.append(raw)\n        except (ValidationError, ValueError) as exc:\n            ident = raw.get("name") or raw.get("class_name") or raw.get("id") or i\n            first = str(exc).splitlines()[0:3]\n            bad.append(f"{ident}: {\' | \'.join(first)}")\n\n    res = ValidationResult(True, records=good)\n    invalid_frac = len(bad) / len(payload)\n    if bad:\n        res.warnings.append(f"{label}: {len(bad)} de {len(payload)} registos falharam a validação")\n        res.warnings.extend(bad[:20])\n    if invalid_frac > max_invalid_fraction:\n        res.ok = False\n        res.errors.append(\n            f"{label}: {invalid_frac:.1%} dos registos inválidos (limite {max_invalid_fraction:.0%}) — rejeitado"\n        )\n    if previous_count and len(good) < min_count_ratio * previous_count:\n        res.ok = False\n        res.errors.append(\n            f"{label}: {len(good)} registos válidos vs {previous_count} na última versão "\n            f"(mínimo {min_count_ratio:.0%}) — possível resposta incompleta, rejeitado"\n        )\n    return res\n\n\ndef validate_heroes(payload: Any, *, previous_count: int | None = None, min_count_ratio: float = 0.8,\n                    max_invalid_fraction: float = 0.05, required_names: list[str] | None = None\n                    ) -> ValidationResult:\n    res = _validate_list(payload, Hero.model_validate, label="heróis", previous_count=previous_count,\n                         min_count_ratio=min_count_ratio, max_invalid_fraction=max_invalid_fraction)\n    if not res.records:\n        return res\n    missing_fields: dict[str, int] = {}\n    for h in res.records:\n        for f in DOCUMENTED_REQUIRED:\n            if f not in h:\n                missing_fields[f] = missing_fields.get(f, 0) + 1\n    for f, n in sorted(missing_fields.items()):\n        res.warnings.append(f"heróis: campo documentado \'{f}\' ausente em {n} registos")\n    if required_names:\n        names = {str(h.get("name", "")).lower() for h in res.records}\n        for name in required_names:\n            if name.lower() not in names:\n                res.warnings.append(f"heróis: herói inicial \'{name}\' não encontrado na resposta")\n    return res\n\n\ndef validate_items(payload: Any, *, previous_count: int | None = None, min_count_ratio: float = 0.8,\n                   max_invalid_fraction: float = 0.05) -> ValidationResult:\n    res = _validate_list(payload, parse_item, label="itens", previous_count=previous_count,\n                         min_count_ratio=min_count_ratio, max_invalid_fraction=max_invalid_fraction)\n    if res.records:\n        types: dict[str, int] = {}\n        for it in res.records:\n            types[it.get("type", "?")] = types.get(it.get("type", "?"), 0) + 1\n        if not types.get("upgrade"):\n            res.ok = False\n            res.errors.append("itens: nenhum item de loja (type=upgrade) na resposta — rejeitado")\n    return res\n\n\ndef validate_ranks(payload: Any, *, previous_count: int | None = None) -> ValidationResult:\n    return _validate_list(payload, Rank.model_validate, label="ranks", previous_count=previous_count,\n                          min_count_ratio=1.0, max_invalid_fraction=0.0)\n', 'src.engine': '"""Motor matemático (Fase 3).\n\nCada fórmula está registada em `rules.py` com o seu estado de validação:\n* documentado — descrita numa fonte pública (ligação incluída);\n* validado    — confirmada contra valores independentes nos dados (ex.: DPS calculado pela API);\n* hipótese    — necessária para calcular, mas ainda sem fonte; aparece SEMPRE junto do resultado.\n\nNenhum número sai do motor sem a lista das regras e hipóteses que o produziram.\n"""\n', 'src.engine.build': '"""Build e cenário: definição e validação de restrições (slots, ativos, componentes)."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nBASE_SLOTS_PER_COLUMN = 4   # R-SLOTS\nMAX_FLEX = 4\nMAX_ACTIVES = 4\n\n\n@dataclass\nclass Scenario:\n    """Parâmetros que NÃO vêm dos dados: são escolhas explícitas do utilizador."""\n\n    target_bullet_resist: float = 0.0     # fração 0–1\n    target_spirit_resist: float = 0.0\n    shred_bullet: float = 0.0             # shred aplicado ao alvo (fração), R-SHRED\n    shred_spirit: float = 0.0\n    distance_m: float | None = None       # None = sem queda de dano\n    headshot_rate: float = 0.0            # 0–1\n    incoming_bullet_share: float = 0.5    # fração do dano recebido que é de balas (para EHP misto)\n    flex_slots: int = MAX_FLEX\n    combat_s: float = 10.0\n\n    def describe(self) -> dict[str, Any]:\n        return {\n            "resist. a balas do alvo": f"{self.target_bullet_resist:.0%}",\n            "resist. Spirit do alvo": f"{self.target_spirit_resist:.0%}",\n            "distância": "sem queda" if not self.distance_m else f"{self.distance_m:g} m",\n            "headshots": f"{self.headshot_rate:.0%}",\n            "dano recebido de balas": f"{self.incoming_bullet_share:.0%}",\n            "slots flex": self.flex_slots,\n            "duração do combate": f"{self.combat_s:g} s",\n        }\n\n\n@dataclass\nclass Build:\n    hero: dict[str, Any]\n    items: list[dict[str, Any]]\n    ability_tiers: dict[str, int] = field(default_factory=dict)  # slot -> 0..3\n    name: str = "Build"\n\n    def effective_items(self) -> tuple[list[dict[str, Any]], list[str]]:\n        """Itens realmente possuídos: componentes consumidos por uma melhoria presente saem."""\n        classes = {i.get("class_name") for i in self.items}\n        consumed = {c for i in self.items for c in (i.get("component_items") or []) if c in classes}\n        kept = [i for i in self.items if i.get("class_name") not in consumed]\n        notes = [f"{i.get(\'name\')} ignorado (consumido pela melhoria)" for i in self.items\n                 if i.get("class_name") in consumed]\n        return kept, notes\n\n    @property\n    def cost(self) -> int:\n        """Souls gastas: a melhoria custa o preço total (o componente já pago faz parte dele)."""\n        return sum(int(i.get("cost") or 0) for i in self.effective_items()[0])\n\n    def without(self, item_id: int) -> "Build":\n        return Build(self.hero, [i for i in self.items if i.get("id") != item_id], dict(self.ability_tiers), self.name)\n\n    def with_item(self, item: dict[str, Any]) -> "Build":\n        return Build(self.hero, self.items + [item], dict(self.ability_tiers), self.name)\n\n    def invested(self) -> dict[str, int]:\n        out = {"weapon": 0, "vitality": 0, "spirit": 0}\n        for it in self.effective_items()[0]:\n            slot = it.get("item_slot_type")\n            if slot in out:\n                out[slot] += int(it.get("cost") or 0)\n        return out\n\n\ndef validate_build(build: Build, flex_slots: int = MAX_FLEX) -> list[str]:\n    """Erros/avisos de restrições (R-SLOTS) e de componentes."""\n    issues: list[str] = []\n    ids = [i.get("id") for i in build.items]\n    if len(ids) != len(set(ids)):\n        issues.append("Itens repetidos na build.")\n    cols = {"weapon": 0, "vitality": 0, "spirit": 0}\n    for it in build.items:\n        if it.get("item_slot_type") in cols:\n            cols[it["item_slot_type"]] += 1\n    overflow = sum(max(0, n - BASE_SLOTS_PER_COLUMN) for n in cols.values())\n    if overflow > flex_slots:\n        issues.append(f"Slots insuficientes: {overflow} itens acima dos 4 por coluna, mas só {flex_slots} slots flex.")\n    if len(build.items) > 3 * BASE_SLOTS_PER_COLUMN + flex_slots:\n        issues.append(f"Mais de {3 * BASE_SLOTS_PER_COLUMN + flex_slots} itens.")\n    actives = sum(1 for i in build.items if i.get("is_active_item"))\n    if actives > MAX_ACTIVES:\n        issues.append(f"{actives} itens ativos (máximo {MAX_ACTIVES}).")\n    by_class = {i.get("class_name"): i for i in build.items}\n    for it in build.items:\n        for comp in it.get("component_items") or []:\n            if comp in by_class:\n                issues.append(f"\'{by_class[comp].get(\'name\')}\' é componente de \'{it.get(\'name\')}\' "\n                              "(ao melhorar, o componente é consumido — não ocupa slot nem soma efeitos).")\n    if any(i.get("disabled") for i in build.items):\n        issues.append("A build contém itens desativados nesta versão.")\n    return issues\n', 'src.engine.diagnostics': '"""Diagnóstico do motor sobre os dados reais e exportação de uma amostra para validação.\n\nA amostra (`amostra_diagnostico.json`) contém apenas dados públicos do jogo (heróis, itens,\nestatísticas agregadas) — nada pessoal. Serve para confirmar formatos que não puderam ser\nverificados durante o desenvolvimento.\n"""\n\nfrom __future__ import annotations\n\nimport json\nfrom collections import Counter\nfrom pathlib import Path\nfrom typing import Any\n\nfrom ..data.normalizer import find_hero, hero_weapon, index_by_class, shop_items  # noqa: F401\nfrom .model import parse_purchase_bonuses\nfrom .stats import STATS, classify_property, normalize_provided, stat_for\nfrom .weapon import WeaponBase, consistency_checks\n\n\ndef mapping_coverage(items: list[dict]) -> list[dict[str, Any]]:\n    """Frequência de cada provided_property_type nos itens de loja e se o motor o mapeia."""\n    counter: Counter = Counter()\n    examples: dict[str, set[str]] = {}\n    kinds: dict[str, Counter] = {}\n    for it in shop_items(items):\n        for name, prop in (it.get("properties") or {}).items():\n            if not isinstance(prop, dict):\n                continue\n            key = normalize_provided(prop.get("provided_property_type")) or f"(sem tipo) {name}"\n            counter[key] += 1\n            examples.setdefault(key, set()).add(name)\n            kinds.setdefault(key, Counter())[classify_property(it, name, prop)] += 1\n    rows = []\n    for key, n in counter.most_common():\n        name = sorted(examples[key])[0]\n        sdef, how = stat_for(name, {"provided_property_type": None if key.startswith("(sem tipo)") else key})\n        rows.append({"tipo / propriedade": key, "ocorrências": n,\n                     "nomes": ", ".join(sorted(examples[key])[:4]),\n                     "stat do motor": sdef.label if sdef else "— não mapeado",\n                     "inato/condicional/indet.": "/".join(str(kinds[key].get(k, 0))\n                                                        for k in ("inato", "condicional", "indeterminado"))})\n    return rows\n\n\ndef weapon_checks_all(heroes: list[dict], items: list[dict]) -> list[dict[str, Any]]:\n    by_class = index_by_class(items)\n    rows = []\n    for h in heroes:\n        w = hero_weapon(h, by_class)\n        wb = WeaponBase.from_weapon({"name": w["name"], "weapon_info": w["weapon_info"]} if w else None)\n        for c in consistency_checks(wb):\n            rows.append({"herói": h.get("name"), **c})\n    return rows\n\n\ndef h_sust_status(checks: list[dict[str, Any]]) -> str:\n    sus = [c for c in checks if c["regra"] == "H-SUST" and c["resultado"] != "sem dados"]\n    if not sus:\n        return "sem dados para validar"\n    bad = [c for c in sus if c["resultado"] != "OK"]\n    return "validado (erro < 2% em todos os heróis)" if not bad else f"diverge em {len(bad)} de {len(sus)} heróis"\n\n\ndef export_sample(db, version: str, cfg: dict[str, Any], dest: Path) -> Path:\n    heroes = db.heroes(version)\n    items = db.items(version)\n    by_class = index_by_class(items)\n    sample: dict[str, Any] = {"versao": version, "heroes": [], "abilities_and_weapons": [], "shop_items_sample": [],\n                              "mapping_coverage": mapping_coverage(items), "purchase_bonuses_parsed": {}}\n    for name in cfg["heroes"]["initial"]:\n        h = find_hero(heroes, name)\n        if not h:\n            continue\n        clean = {k: v for k, v in h.items() if not k.startswith("_")}\n        sample["heroes"].append(clean)\n        sample["purchase_bonuses_parsed"][name] = parse_purchase_bonuses(h.get("purchase_bonuses")) is not None\n        for cls in (h.get("items") or {}).values():\n            it = by_class.get(cls)\n            if it and it.get("type") in ("ability", "weapon"):\n                sample["abilities_and_weapons"].append({k: v for k, v in it.items() if not k.startswith("_")})\n    shop = shop_items(items)\n    seen_slots: Counter = Counter()\n    for it in sorted(shop, key=lambda i: (i.get("item_tier") or 0, i.get("name") or "")):\n        key = (it.get("item_slot_type"), it.get("item_tier"))\n        if seen_slots[key] < 2:\n            seen_slots[key] += 1\n            sample["shop_items_sample"].append({k: v for k, v in it.items() if not k.startswith("_")})\n    sample["stats_defs"] = {k: {"provided": s.provided, "names": s.names} for k, s in STATS.items()}\n    sample["stats_row_examples"] = db.stats_examples()\n    dest.parent.mkdir(parents=True, exist_ok=True)\n    dest.write_text(json.dumps(sample, ensure_ascii=False, indent=1), encoding="utf-8")\n    return dest\n\n\ndef quick_checks(db, version: str | None, cfg: dict[str, Any], heroes: list[dict], items: list[dict],\n                 evaluator) -> list[dict[str, str]]:\n    """Verificações automáticas da app com dados reais (para o utilizador não ter de ler logs)."""\n    from ..engine.build import Scenario\n    from ..optimizer.build_optimizer import select_candidates\n    from ..optimizer.fast_model import FastModel\n    from ..optimizer.objective_function import STYLES, Objective\n    from .stats import item_effects\n\n    ok, warn, bad = "✔", "⚠", "✖"\n    rows: list[dict[str, str]] = []\n\n    def add(name: str, state: str, detail: str, action: str = "") -> None:\n        rows.append({"verificação": name, "estado": state, "detalhe": detail, "o que fazer": action})\n\n    if not version:\n        add("Dados carregados", bad, "ainda não há dados", "Atualizar dados (barra lateral)")\n        return rows\n    add("Dados carregados", ok, f"versão {version}, {len(heroes)} heróis, {len(items)} itens")\n\n    by_class = index_by_class(items)\n    initial = cfg["heroes"]["initial"]\n    found = [find_hero(heroes, n) for n in initial]\n    missing = [n for n, h in zip(initial, found) if not h]\n    add("Heróis iniciais", ok if not missing else warn,\n        "todos encontrados" if not missing else f"não encontrados: {\', \'.join(missing)}",\n        "" if not missing else "Confirmar nomes em config.yaml (heroes.initial)")\n\n    from ..data.normalizer import hero_abilities\n    for h in [h for h in found if h]:\n        ab = [a for a in hero_abilities(h, by_class, cfg["ability_property_keys"]) if not a.get("missing")]\n        with_cd = sum(1 for a in ab if a.get("cooldown"))\n        state = ok if len(ab) >= 4 and with_cd >= 3 else warn\n        add(f"Habilidades — {h[\'name\']}", state, f"{len(ab)} habilidades, {with_cd} com cooldown identificado",\n            "" if state == ok else "Exportar amostra de diagnóstico e enviá-la numa conversa")\n\n    status = h_sust_status(weapon_checks_all(heroes, items))\n    add("Fórmula do DPS com recarga (H-SUST)", ok if status.startswith("validado") else warn, status,\n        "" if status.startswith("validado") else "Ver Otimizador › Fórmulas e validação")\n\n    total = applied = indeterminate = 0\n    for it in shop_items(items):\n        eff = item_effects(it)\n        n_all = len(eff.applied) + len(eff.not_applied)\n        total += n_all\n        applied += len(eff.applied)\n        indeterminate += sum(1 for e in eff.not_applied if e.kind == "indeterminado" and e.stat)\n    frac = applied / total if total else 0.0\n    add("Efeitos de itens modelados", ok if frac >= 0.5 else (warn if frac >= 0.2 else bad),\n        f"{frac:.0%} das propriedades dos itens de loja entram nos cálculos",\n        "" if frac >= 0.5 else "Exportar amostra para mapear os efeitos em falta")\n    if indeterminate:\n        add("Secções do tooltip", warn, f"{indeterminate} efeitos mapeados ficam fora por secção desconhecida",\n            "Se forem muitos: engine.apply_indeterminate: true no config.yaml")\n\n    parsed = [h["name"] for h in found if h and parse_purchase_bonuses(h.get("purchase_bonuses")) is not None]\n    add("Bónus de investimento", ok if parsed else warn,\n        f"reconhecidos para: {\', \'.join(parsed)}" if parsed else "formato não reconhecido — não aplicados (hipótese)",\n        "" if parsed else "Exportar amostra de diagnóstico")\n\n    if found and found[0]:\n        obj = Objective(FastModel(evaluator, found[0], Scenario()), STYLES["Híbrido"])\n        cands, out = select_candidates(obj, shop_items(items), set())\n        add("Candidatos do otimizador", ok if len(cands) >= 15 else warn,\n            f"{len(cands)} itens com ganho modelado, {len(out)} fora da procura ({found[0][\'name\']})",\n            "" if len(cands) >= 15 else "Poucos efeitos mapeados — exportar amostra")\n\n    errors = db.get_kv("error_log", []) or []\n    add("Erros recentes", ok if not errors else bad, "nenhum" if not errors else\n        f"{len(errors)} — último: {errors[0][\'error\'][:120]}", "" if not errors else "Captura de ecrã desta tabela")\n    return rows\n', 'src.engine.economy': '"""Economia: benefício marginal, eficiência por Soul e ranking de itens por eficiência.\n\nEficiência = ganho no atributo escolhido por 1000 Souls, calculado pelo motor a partir das\npropriedades reais dos itens — nunca a partir de popularidade ou win rate.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom .build import Build, Scenario, validate_build\nfrom .model import METRIC_LABELS, Evaluation, Evaluator\nfrom .stats import item_effects\n\n\ndef _delta(a: float | None, b: float | None) -> float | None:\n    if a is None or b is None:\n        return None\n    return a - b\n\n\ndef marginal_contributions(ev: Evaluator, build: Build, scenario: Scenario, metrics: list[str]) -> list[dict[str, Any]]:\n    """Leave-one-out: quanto cada item acrescenta à build completa (e por 1000 Souls)."""\n    full = ev.evaluate(build, scenario)\n    rows = []\n    for it in build.items:\n        without = ev.evaluate(build.without(it["id"]), scenario)\n        cost = int(it.get("cost") or 0)\n        eff = item_effects(it, ev.apply_indeterminate)\n        row: dict[str, Any] = {"item": it.get("name"), "custo": cost, "cobertura": eff.coverage}\n        for m in metrics:\n            d = _delta(full.metrics.get(m), without.metrics.get(m))\n            row[f"Δ {METRIC_LABELS[m]}"] = d\n            row[f"Δ/1000 Souls · {METRIC_LABELS[m]}"] = (d / cost * 1000) if (d is not None and cost) else None\n        rows.append(row)\n    return rows\n\n\ndef rank_items(ev: Evaluator, base: Build, candidates: list[dict[str, Any]], scenario: Scenario, metric: str,\n               respect_slots: bool = True) -> list[dict[str, Any]]:\n    """Ganho de cada item candidato quando adicionado à build base."""\n    base_eval: Evaluation = ev.evaluate(base, scenario)\n    base_val = base_eval.metrics.get(metric)\n    have = {i.get("id") for i in base.items}\n    rows = []\n    for it in candidates:\n        if it.get("id") in have:\n            continue\n        b = base.with_item(it)\n        if respect_slots and any(("Slots insuficientes" in x or "Mais de" in x or "ativos" in x)\n                                 for x in validate_build(b, scenario.flex_slots)):\n            continue\n        val = ev.evaluate(b, scenario).metrics.get(metric)\n        d = _delta(val, base_val)\n        cost = int(it.get("cost") or 0)\n        eff = item_effects(it, ev.apply_indeterminate)\n        rows.append({\n            "item_id": it.get("id"), "item": it.get("name"), "slot": it.get("item_slot_type"),\n            "tier": it.get("item_tier"), "custo": cost, "ganho": d,\n            "ganho %": (d / base_val * 100) if (d is not None and base_val) else None,\n            "ganho por 1000 Souls": (d / cost * 1000) if (d is not None and cost) else None,\n            "efeitos aplicados": len(eff.applied), "efeitos fora do modelo": len(eff.not_applied),\n            "cobertura": eff.coverage,\n        })\n    rows.sort(key=lambda r: (r["ganho por 1000 Souls"] is None, -(r["ganho por 1000 Souls"] or 0)))\n    return rows\n', 'src.engine.model': '"""Avaliação de uma build: atributos agregados, arma, sobrevivência, habilidades.\n\nDevolve sempre: os números, as regras usadas e as hipóteses de que dependem.\n"""\n\nfrom __future__ import annotations\n\nimport copy\nimport re\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nfrom ..data.normalizer import find_property, hero_abilities, hero_weapon\nfrom ..models.common import to_number\nfrom .build import Build, Scenario, validate_build\nfrom .rules import RULES\nfrom .stats import STATS, ItemEffect, item_effects, normalize_provided\nfrom .weapon import WeaponBase, WeaponResult, evaluate_weapon\n\nDAMAGE_PROP = re.compile(r"damage", re.I)\nNOT_DAMAGE_PROP = re.compile(r"percent|reduction|amp|resist|bonus|scale|mult|radius|range|duration|threshold|"\n                             r"pct|falloff|lifesteal|heal|shield|slow|stack", re.I)\n\n\ndef _resist_value(stat: dict | None) -> float:\n    """H-UNIT: starting_stats de resistência > 1 = percentagem."""\n    if not stat or stat.get("value") is None:\n        return 0.0\n    v = float(stat["value"])\n    return v / 100.0 if abs(v) > 1 else v\n\n\ndef combine_multiplicative(values: list[float]) -> float:\n    """R-RES / R-CDR: 1 − Π(1 − xᵢ)."""\n    prod = 1.0\n    for v in values:\n        prod *= (1.0 - v)\n    return 1.0 - prod\n\n\ndef effective_items(build: Build) -> tuple[list[dict], list[str]]:\n    """Remove componentes consumidos por melhorias presentes na mesma build."""\n    return build.effective_items()\n\n\n# ---------------------------------------------------------------- bónus de investimento (R-INV)\ndef parse_purchase_bonuses(pb: Any) -> dict[str, list[tuple[float, str, float]]] | None:\n    """Tenta ler Hero.purchase_bonuses: {slot: [(limiar, stat, valor_fração_ou_fixo)]}. None se não reconhecido."""\n    if not isinstance(pb, dict) or not pb:\n        return None\n    out: dict[str, list[tuple[float, str, float]]] = {}\n    for slot, entries in pb.items():\n        if not isinstance(entries, list):\n            return None\n        parsed = []\n        for e in entries:\n            if not isinstance(e, dict):\n                return None\n            thr = next((to_number(v) for k, v in e.items()\n                        if any(t in k.lower() for t in ("gold", "threshold", "souls")) and to_number(v) is not None), None)\n            vtype = next((normalize_provided(v) for k, v in e.items()\n                          if isinstance(v, str) and ("type" in k.lower() or "modifier" in k.lower())), None)\n            val = next((to_number(v) for k, v in e.items()\n                        if any(t in k.lower() for t in ("bonus", "value")) and "type" not in k.lower()\n                        and to_number(v) is not None), None)\n            if thr is None or val is None or vtype is None:\n                return None\n            sdef = next((s for s in STATS.values() if vtype in s.provided), None)\n            if sdef is None:\n                continue\n            parsed.append((thr, sdef.key, val / 100.0 if sdef.unit == "percent" else val))\n        out[str(slot)] = sorted(parsed)\n    return out\n\n\ndef investment_bonuses(hero: dict, invested: dict[str, int]) -> tuple[dict[str, float], str]:\n    table = parse_purchase_bonuses(hero.get("purchase_bonuses"))\n    if table is None:\n        return {}, "não aplicado: formato de purchase_bonuses não reconhecido"\n    bonus: dict[str, float] = {}\n    for slot, entries in table.items():\n        souls = invested.get(slot.lower(), 0)\n        per_stat: dict[str, float] = {}\n        for thr, stat, val in entries:\n            if souls >= thr:\n                per_stat[stat] = val  # cumulativo: o maior limiar atingido dá o total\n        for stat, val in per_stat.items():\n            bonus[stat] = bonus.get(stat, 0.0) + val\n    return bonus, "aplicado (R-INV)"\n\n\n# ---------------------------------------------------------------- avaliação\n@dataclass\nclass Evaluation:\n    build: Build\n    scenario: Scenario\n    metrics: dict[str, float | None]\n    stats: dict[str, float]\n    weapon: WeaponResult | None\n    survivability: dict[str, float | None]\n    abilities: list[dict[str, Any]]\n    applied: list[ItemEffect]\n    not_applied: list[ItemEffect]\n    investment: dict[str, float]\n    investment_status: str\n    issues: list[str]\n    notes: list[str]\n    rules_used: list[str] = field(default_factory=list)\n\n    def hypotheses(self) -> list[dict[str, str]]:\n        return [{"regra": r, "nome": RULES[r].name, "fórmula": RULES[r].formula, "estado": RULES[r].status,\n                 "fonte": RULES[r].source} for r in sorted(set(self.rules_used)) if r in RULES]\n\n\nMETRIC_LABELS = {\n    "weapon_dps_effective": "DPS da arma efetivo (sustentado, cenário)",\n    "weapon_dps_sustained": "DPS da arma sustentado (com recarga)",\n    "weapon_dps": "DPS da arma contínuo",\n    "magazine_damage": "Dano por carregador",\n    "ehp_bullet": "Vida efetiva vs balas",\n    "ehp_spirit": "Vida efetiva vs Spirit",\n    "ehp_mixed": "Vida efetiva (mistura do cenário)",\n    "health": "Vida",\n    "spirit_power": "Spirit Power",\n    "ability_cdr": "Redução de cooldown",\n    "ability_damage_index": "Índice de dano de habilidades /s (heurístico)",\n    "ability_burst_index": "Burst de habilidades (heurístico)",\n}\n\n\nclass Evaluator:\n    def __init__(self, items_by_class: dict[str, dict], prop_keys: dict[str, list[str]],\n                 no_crit_heroes: list[str] | None = None, apply_indeterminate: bool = False):\n        self.items_by_class = items_by_class\n        self.prop_keys = prop_keys\n        self.no_crit = {n.lower() for n in (no_crit_heroes or [])}\n        self.apply_indeterminate = apply_indeterminate\n\n    # -------------------------------------------------------- atributos\n    def aggregate(self, build: Build) -> tuple[dict[str, float], list[ItemEffect], list[ItemEffect], dict[str, float],\n                                               str, list[str], list[str]]:\n        items, notes = effective_items(build)\n        additive: dict[str, float] = {}\n        multiplicative: dict[str, list[float]] = {}\n        applied: list[ItemEffect] = []\n        not_applied: list[ItemEffect] = []\n        rules = {"R-PROV", "H-INNATE"}\n        for it in items:\n            eff = item_effects(it, self.apply_indeterminate)\n            applied += eff.applied\n            not_applied += eff.not_applied\n            for e in eff.applied:\n                sdef = STATS[e.stat]  # type: ignore[index]\n                rules.add(sdef.rule)\n                if sdef.stacking == "multiplicative":\n                    multiplicative.setdefault(sdef.key, []).append(e.value or 0.0)\n                else:\n                    additive[sdef.key] = additive.get(sdef.key, 0.0) + (e.value or 0.0)\n        inv, inv_status = investment_bonuses(build.hero, build.invested())\n        if inv:\n            rules.add("R-INV")\n        for k, v in inv.items():\n            if STATS[k].stacking == "multiplicative":\n                multiplicative.setdefault(k, []).append(v)\n            else:\n                additive[k] = additive.get(k, 0.0) + v\n        stats = dict(additive)\n        for k, vals in multiplicative.items():\n            stats[k] = combine_multiplicative(vals)\n        return stats, applied, not_applied, inv, inv_status, notes, sorted(rules)\n\n    # -------------------------------------------------------- avaliação completa\n    def evaluate(self, build: Build, scenario: Scenario) -> Evaluation:\n        hero = build.hero\n        stats, applied, not_applied, inv, inv_status, notes, rules = self.aggregate(build)\n        rules = list(rules) + ["H-LEVEL"]\n        issues = validate_build(build, scenario.flex_slots)\n\n        # arma\n        weapon = hero_weapon(hero, self.items_by_class)\n        wb = WeaponBase.from_weapon({"name": weapon["name"], "weapon_info": weapon["weapon_info"]} if weapon else None)\n        can_crit = str(hero.get("name", "")).lower() not in self.no_crit\n        target_br = max(-1.0, scenario.target_bullet_resist - scenario.shred_bullet)\n        wres = evaluate_weapon(\n            wb, weapon_damage_pct=stats.get("weapon_damage_pct", 0.0), fire_rate_pct=stats.get("fire_rate_pct", 0.0),\n            ammo_pct=stats.get("ammo_pct", 0.0), ammo_flat=stats.get("ammo_flat", 0.0), distance=scenario.distance_m,\n            headshot_rate=scenario.headshot_rate, crit_bonus_scale=0.0, can_crit=can_crit,\n            target_bullet_resist=target_br)\n        rules += ["H-WD", "H-FR", "H-AMMO", "H-SUST", "R-SHRED"]\n        if scenario.distance_m:\n            rules.append("R-FALL")\n        if scenario.headshot_rate > 0:\n            rules.append("R-HS")\n            if not can_crit:\n                notes.append(f"{hero.get(\'name\')} não faz dano crítico (configuração, fonte: wiki) — headshots ignorados.")\n\n        # sobrevivência\n        ss = hero.get("starting_stats") or {}\n        base_hp = (ss.get("max_health") or {}).get("value")\n        surv: dict[str, float | None] = {}\n        if base_hp is not None:\n            hp = float(base_hp) * (1.0 + stats.get("health_pct", 0.0)) + stats.get("health_flat", 0.0)\n            br = combine_multiplicative([_resist_value(ss.get("bullet_armor_damage_reduction")),\n                                         stats.get("bullet_resist", 0.0)])\n            sr = combine_multiplicative([_resist_value(ss.get("tech_armor_damage_reduction")),\n                                         stats.get("spirit_resist", 0.0)])\n            m = scenario.incoming_bullet_share\n            surv = {\n                "health": hp, "bullet_resist": br, "spirit_resist": sr,\n                "ehp_bullet": hp / (1 - br) if br < 1 else None,\n                "ehp_spirit": hp / (1 - sr) if sr < 1 else None,\n                "ehp_mixed": hp / (m * (1 - br) + (1 - m) * (1 - sr)) if (m * (1 - br) + (1 - m) * (1 - sr)) > 0 else None,\n                "health_regen": float((ss.get("base_health_regen") or {}).get("value") or 0) + stats.get("health_regen", 0.0),\n            }\n            rules += ["R-RES", "R-EHP", "H-UNIT"]\n            if stats.get("health_pct"):\n                rules.append("H-HPPCT")\n\n        # habilidades\n        sp = stats.get("spirit_power", 0.0)\n        cdr = stats.get("ability_cdr", 0.0)\n        abilities = self._abilities(hero, build.ability_tiers, sp, cdr)\n        rules += ["R-SP", "R-CDR", "R-UPG", "H-ABDMG"]\n        dmg_index = sum(a["damage_per_cycle"] / a["cooldown_eff"] for a in abilities\n                        if a["damage_per_cycle"] and a.get("cooldown_eff"))\n        burst = sum(a["damage_per_cycle"] for a in abilities if a["damage_per_cycle"])\n\n        metrics: dict[str, float | None] = {\n            "weapon_dps_effective": wres.effective_dps if wres else None,\n            "weapon_dps_sustained": wres.sustained_dps if wres else None,\n            "weapon_dps": wres.dps if wres else None,\n            "magazine_damage": wres.damage_per_magazine if wres else None,\n            "ehp_bullet": surv.get("ehp_bullet"),\n            "ehp_spirit": surv.get("ehp_spirit"),\n            "ehp_mixed": surv.get("ehp_mixed"),\n            "health": surv.get("health"),\n            "spirit_power": sp,\n            "ability_cdr": cdr,\n            "ability_damage_index": dmg_index if abilities else None,\n            "ability_burst_index": burst if abilities else None,\n        }\n        notes.append(f"Bónus de investimento: {inv_status}.")\n        return Evaluation(build, scenario, metrics, stats, wres, surv, abilities, applied, not_applied, inv,\n                          inv_status, issues, notes, rules)\n\n    # -------------------------------------------------------- habilidades\n    def ability_profiles(self, hero: dict, tiers: dict[str, int]) -> list[dict[str, Any]]:\n        """Dados estáticos de cada habilidade (após melhorias T1–T3): cooldown base e termos numéricos.\n\n        Cada termo = (propriedade, valor base, coeficiente de Spirit Power ou 0, conta como dano?).\n        Separado do cálculo para o otimizador poder reavaliar milhares de builds sem repetir este trabalho.\n        """\n        out = []\n        for ab in hero_abilities(hero, self.items_by_class, self.prop_keys):\n            if ab.get("missing"):\n                continue\n            item = copy.deepcopy(self.items_by_class.get(ab["class_name"]) or {})\n            props: dict[str, dict] = item.get("properties") or {}\n            tier = int(tiers.get(ab["slot"], 0))\n            applied_upgrades = []\n            for t, up in enumerate(item.get("upgrades") or [], start=1):\n                if t > tier:\n                    break\n                for pu in (up or {}).get("property_upgrades") or []:\n                    name, bonus = pu.get("name"), to_number(pu.get("bonus"))\n                    if name not in props or bonus is None:\n                        continue\n                    utype = str(pu.get("upgrade_type") or "")\n                    if "scale" in utype.lower() and props[name].get("scale_function"):\n                        sf = props[name]["scale_function"]\n                        sf["stat_scale"] = (to_number(sf.get("stat_scale")) or 0.0) + bonus\n                    else:\n                        base = to_number(props[name].get("value")) or 0.0\n                        props[name]["value"] = base + bonus\n                    applied_upgrades.append(f"T{t}: {name} {bonus:+g}")\n            cd = find_property(props, self.prop_keys.get("cooldown", []))\n            terms = []\n            for name, p in sorted(props.items()):\n                if not isinstance(p, dict):\n                    continue\n                base = to_number(p.get("value"))\n                if base is None:\n                    continue\n                sf = p.get("scale_function") or {}\n                stype = str(sf.get("specific_stat_scale_type") or "").lower()\n                coef = to_number(sf.get("stat_scale"))\n                tech = bool(coef) and ("tech" in stype or "spirit" in stype)\n                is_dmg = bool(DAMAGE_PROP.search(name) and not NOT_DAMAGE_PROP.search(name))\n                terms.append((name, base, coef if tech else 0.0, is_dmg))\n            out.append({"slot": ab["slot"], "name": ab["name"], "tier": tier, "upgrades": applied_upgrades,\n                        "cooldown_base": cd["value"] if cd else None, "terms": terms})\n        return out\n\n    @staticmethod\n    def ability_values(profile: dict[str, Any], sp: float, cdr: float) -> tuple[float | None, float | None, list]:\n        """(cooldown efetivo, dano por ciclo, propriedades escaladas) para um Spirit Power e CDR."""\n        cd_base = profile["cooldown_base"]\n        cd_eff = cd_base * (1 - cdr) if cd_base else None\n        dmg, scaled = 0.0, []\n        for name, base, coef, is_dmg in profile["terms"]:\n            val = base + coef * sp if coef else base\n            if coef:\n                scaled.append({"propriedade": name, "base": base, "coeficiente": coef, "com build": val})\n            if is_dmg and val > 0:\n                dmg += val\n        return cd_eff, (dmg if dmg > 0 else None), scaled\n\n    def _abilities(self, hero: dict, tiers: dict[str, int], sp: float, cdr: float) -> list[dict[str, Any]]:\n        out = []\n        for prof in self.ability_profiles(hero, tiers):\n            cd_eff, dmg, scaled = self.ability_values(prof, sp, cdr)\n            out.append({"slot": prof["slot"], "name": prof["name"], "tier": prof["tier"], "upgrades": prof["upgrades"],\n                        "cooldown_base": prof["cooldown_base"], "cooldown_eff": cd_eff, "scaled": scaled,\n                        "damage_per_cycle": dmg})\n        return out\n', 'src.engine.rules': '"""Registo das regras mecânicas usadas pelo motor, com fonte e estado de validação."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nDOCUMENTED = "documentado"\nHYPOTHESIS = "hipótese"\nVALIDATED = "validado"\nDECISION = "decisão de modelação"\n\n\n@dataclass(frozen=True)\nclass Rule:\n    id: str\n    name: str\n    formula: str\n    status: str\n    source: str\n    note: str = ""\n\n\nRULES: dict[str, Rule] = {r.id: r for r in [\n    Rule("R-RES", "Empilhamento de resistências",\n         "Resist total = 1 − Π(1 − Rᵢ)", DOCUMENTED, "https://deadlock.wiki/Damage_Resistance",\n         "Exceção documentada: resistências de boons/Spirit Power do próprio herói somam-se."),\n    Rule("R-SHRED", "Redução de resistência (shred)",\n         "Shred total = 1 − Π(1 − Sᵢ); resist final = resist total − shred total", DOCUMENTED,\n         "https://deadlock.wiki/Damage_Resistance"),\n    Rule("R-EHP", "Vida efetiva",\n         "EHP = vida / (1 − resist)  (50% de resist duplica a vida efetiva)", DOCUMENTED,\n         "https://deadlock.wiki/Damage_Resistance"),\n    Rule("R-CDR", "Empilhamento de redução de cooldown",\n         "CDR total = 1 − Π(1 − CDRᵢ); cooldown = base × (1 − CDR total)", DOCUMENTED,\n         "https://deadlock.wiki/Ability_Cooldown",\n         "Desde jul/2025 a CDR de habilidades não afeta itens."),\n    Rule("R-SP", "Escalamento com Spirit Power",\n         "valor = base + Spirit Power × coeficiente (stat_scale)", DOCUMENTED,\n         "https://deadlock.wiki/Spirit_Power"),\n    Rule("R-HS", "Multiplicador de headshot",\n         "crítico = 1 + (0,65 + crit bonus scale do herói); esperado = 1 + p_headshot × (crítico − 1)", DOCUMENTED,\n         "https://deadlock.wiki/Weapon_Damage",\n         "A wiki indica heróis que não fazem crítico (inclui Graves); configurável em config.yaml."),\n    Rule("R-FALL", "Queda de dano com a distância",\n         "1 até ao início; linear até à escala final no fim; constante depois", DOCUMENTED,\n         "https://deadlock.wiki/Weapon_Damage",\n         "Distâncias e escala final lidas do weapon_info de cada arma."),\n    Rule("R-INV", "Bónus de investimento por categoria",\n         "bónus = valor no maior limiar de Souls ≤ total investido na categoria (cumulativo)", DOCUMENTED,\n         "https://deadlock.wiki/Items",\n         "Estrutura lida de Hero.purchase_bonuses; se o formato não for reconhecido, não é aplicado."),\n    Rule("R-SLOTS", "Slots de itens",\n         "12 base (4 Weapon / 4 Vitality / 4 Spirit) + até 4 flex de qualquer coluna; máx. 4 ativos", DOCUMENTED,\n         "https://www.steamdb.com/en/deadlock/mechanics/flex-slots"),\n    Rule("R-UPG", "Melhorias de habilidade",\n         "cada nível T1–T3 soma o seu bónus à propriedade (ou ao coeficiente, se o tipo for de escala)", DOCUMENTED,\n         "https://deadworks.net/db/abilities/upgrade_unstoppable"),\n    Rule("R-PROV", "Efeito de cada propriedade de item",\n         "o stat afetado vem de provided_property_type (ex.: WEAPON_DAMAGE_INCREASE, HEALTH_MAX, TECH_POWER)",\n         DOCUMENTED, "https://deadworks.net/db/abilities/upgrade_reinforcing_casings",\n         "Quando o tipo não existe, usa-se o nome interno da propriedade (lista em engine/stats.py)."),\n    Rule("H-WD", "Dano de arma % entre fontes",\n         "bónus de dano % somam-se (itens + investimento) e multiplicam o dano base", HYPOTHESIS,\n         "consistente com https://deadlock.wiki/Items (investimento acumulado)"),\n    Rule("H-FR", "Fire rate % entre fontes",\n         "bónus somam-se; disparos/s = base × (1 + Σ bónus)", HYPOTHESIS, "sem fonte encontrada"),\n    Rule("H-AMMO", "Munição %",\n         "carregador = arredondar(base × (1 + Σ %) + Σ fixo)", HYPOTHESIS, "sem fonte encontrada"),\n    Rule("H-SUST", "DPS sustentado com recarga",\n         "DPS × t_carregador / (t_carregador + recarga), t_carregador = balas / (balas/s)", HYPOTHESIS,\n         "validável: comparado com damage_per_second_with_reload calculado pela API",\n         "Passa a \'validado\' na página Fórmulas quando o erro é < 2% em todos os heróis."),\n    Rule("H-INNATE", "Que efeitos contam",\n         "só propriedades inatas (secção innate) e sem condição; passivos condicionais e ativos ficam de fora",\n         DECISION, "secções do tooltip nos dados (tooltip_sections)",\n         "Subestima itens cujo valor está no passivo/ativo — a cobertura de cada item é mostrada."),\n    Rule("H-HPPCT", "Vida % do investimento Vitality",\n         "aplica-se à vida base do herói", HYPOTHESIS, "sem fonte encontrada"),\n    Rule("H-ABDMG", "Índice de dano de habilidades",\n         "Σ propriedades com \'Damage\' no nome, escaladas com Spirit Power, por ciclo de cooldown", HYPOTHESIS,\n         "heurística — serve para comparar builds do MESMO herói, não para valores absolutos"),\n    Rule("H-LEVEL", "Nível do herói",\n         "cálculos ao nível base, sem boons nem buffs permanentes", DECISION,\n         "limitação conhecida — ganhos por nível ainda não modelados"),\n    Rule("H-UNIT", "Unidades das resistências base",\n         "valores > 1 em starting_stats são percentagens (÷100); ≤ 1 são frações", HYPOTHESIS,\n         "a confirmar com a amostra de diagnóstico"),\n]}\n\n\ndef rule(rule_id: str) -> Rule:\n    return RULES[rule_id]\n', 'src.engine.simulate': '"""Simulação temporal da arma (início da Fase 5): dano acumulado e tempo para matar.\n\nModelo: disparo contínuo a balas/s até esvaziar o carregador, recarga, repetir (H-SUST).\nO dano por bala inclui bónus da build, queda de dano, headshots esperados e resistência do alvo.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nfrom .weapon import WeaponResult\n\n\n@dataclass\nclass Series:\n    t: list[float]\n    damage: list[float]\n\n\ndef weapon_series(w: WeaponResult | None, duration_s: float, dt: float = 0.05) -> Series | None:\n    if w is None or not w.bullets_per_second or not w.clip or w.dps is None or w.reload is None:\n        return None\n    reload = w.reload\n    dmg_per_bullet = w.dps / w.bullets_per_second * w.falloff_mult * w.headshot_mult * w.resist_mult\n    t, total, ammo, reloading_until = 0.0, 0.0, w.clip, -1.0\n    ts, ds = [0.0], [0.0]\n    carry = 0.0\n    while t < duration_s - 1e-9:\n        t = round(t + dt, 6)\n        if reloading_until > 0:\n            if t >= reloading_until:\n                ammo, reloading_until = w.clip, -1.0\n        else:\n            carry += w.bullets_per_second * dt\n            shots = min(int(carry), int(ammo))\n            carry -= shots\n            ammo -= shots\n            total += shots * dmg_per_bullet\n            if ammo <= 0:\n                reloading_until = t + reload\n                carry = 0.0\n        ts.append(t)\n        ds.append(total)\n    return Series(ts, ds)\n\n\ndef time_to_kill(series: Series | None, target_hp: float) -> float | None:\n    if series is None:\n        return None\n    for t, d in zip(series.t, series.damage):\n        if d >= target_hp:\n            return t\n    return None\n', 'src.engine.stats': '"""Mapeamento das propriedades de itens para atributos do motor.\n\nPrioridade:\n1. `provided_property_type` dos dados (sem o prefixo MODIFIER_VALUE_), confirmado na Deadworks\n   para os tipos marcados com evidência "deadworks";\n2. nome interno da propriedade (wiki: Data:StatLinks.json / Module:ItemData), como recurso.\n\nTudo o que não corresponde fica como "não mapeado" e é listado — nunca é adivinhado.\nO que conta como efeito permanente segue a regra H-INNATE.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nfrom ..models.common import to_number\n\n\n@dataclass(frozen=True)\nclass StatDef:\n    key: str\n    label: str\n    unit: str  # "percent" (valor em pontos percentuais nos dados) | "flat"\n    stacking: str  # "additive" | "multiplicative"\n    rule: str\n    provided: tuple[str, ...] = ()\n    names: tuple[str, ...] = ()\n    evidence: str = "hipótese"\n\n\nSTAT_DEFS: list[StatDef] = [\n    StatDef("weapon_damage_pct", "Dano de arma (%)", "percent", "additive", "H-WD",\n            ("WEAPON_DAMAGE_INCREASE",), ("BaseAttackDamagePercent",), "deadworks"),\n    StatDef("fire_rate_pct", "Fire rate (%)", "percent", "additive", "H-FR",\n            ("FIRE_RATE", "BONUS_FIRE_RATE"), ("BonusFireRate",), "wiki (nome)"),\n    StatDef("ammo_pct", "Munição (%)", "percent", "additive", "H-AMMO",\n            ("AMMO_CLIP_SIZE_PERCENT",), ("BonusClipSizePercent",), "deadworks"),\n    StatDef("ammo_flat", "Munição (fixa)", "flat", "additive", "H-AMMO",\n            ("AMMO_CLIP_SIZE", "BONUS_CLIP_SIZE"), ("BonusClipSize",), "wiki (nome)"),\n    StatDef("spirit_power", "Spirit Power", "flat", "additive", "R-SP",\n            ("TECH_POWER",), ("TechPower", "SpiritPower"), "deadworks"),\n    StatDef("health_flat", "Vida (fixa)", "flat", "additive", "R-EHP",\n            ("HEALTH_MAX",), ("BonusHealth",), "deadworks"),\n    StatDef("health_pct", "Vida base (%)", "percent", "additive", "H-HPPCT",\n            ("HEALTH_MAX_PERCENT", "BASE_HEALTH_PERCENT"), ("BonusBaseHealthPercent",), "hipótese"),\n    StatDef("bullet_resist", "Resistência a balas", "percent", "multiplicative", "R-RES",\n            ("BULLET_ARMOR_DAMAGE_RESIST",), ("BulletResist",), "deadworks"),\n    StatDef("spirit_resist", "Resistência Spirit", "percent", "multiplicative", "R-RES",\n            ("TECH_ARMOR_DAMAGE_RESIST", "TECH_RESIST"), ("TechResist",), "deadworks"),\n    StatDef("ability_cdr", "Redução de cooldown", "percent", "multiplicative", "R-CDR",\n            ("COOLDOWN_REDUCTION", "COOLDOWN_REDUCTION_PERCENTAGE", "ABILITY_COOLDOWN_REDUCTION"),\n            ("CooldownReduction",), "hipótese"),\n    StatDef("health_regen", "Regeneração de vida", "flat", "additive", "R-EHP",\n            ("HEALTH_REGEN",), ("HealthRegen", "BonusHealthRegen"), "hipótese"),\n    StatDef("bullet_lifesteal", "Lifesteal de balas (%)", "percent", "additive", "R-EHP",\n            ("BULLET_LIFESTEAL",), ("BulletLifestealPercent",), "hipótese"),\n    StatDef("spirit_lifesteal", "Lifesteal Spirit (%)", "percent", "additive", "R-EHP",\n            ("TECH_LIFESTEAL",), ("AbilityLifestealPercentHero",), "deadlock.gs"),\n    StatDef("status_resist", "Resistência a debuffs (%)", "percent", "additive", "R-PROV",\n            ("STATUS_RESISTANCE",), ("StatusResistancePercent",), "deadworks"),\n    StatDef("move_speed", "Velocidade de movimento", "flat", "additive", "R-PROV",\n            ("MOVEMENT_SPEED_MAX", "MOVE_SPEED"), ("BonusMoveSpeed",), "hipótese"),\n]\n\nSTATS: dict[str, StatDef] = {s.key: s for s in STAT_DEFS}\n_BY_PROVIDED = {p: s for s in STAT_DEFS for p in s.provided}\n_BY_NAME = {n.lower(): s for s in STAT_DEFS for n in s.names}\n\n\ndef normalize_provided(value: Any) -> str | None:\n    if not value or not isinstance(value, str):\n        return None\n    v = value.strip().upper()\n    for prefix in ("MODIFIER_VALUE_", "EMODIFIERVALUE_"):\n        if v.startswith(prefix):\n            v = v[len(prefix):]\n    return v or None\n\n\ndef stat_for(prop_name: str, prop: dict[str, Any]) -> tuple[StatDef | None, str]:\n    """Devolve (stat, como foi identificado)."""\n    provided = normalize_provided(prop.get("provided_property_type"))\n    if provided and provided in _BY_PROVIDED:\n        return _BY_PROVIDED[provided], f"provided_property_type={provided}"\n    s = _BY_NAME.get(prop_name.lower())\n    if s is not None:\n        return s, f"nome da propriedade ({prop_name})"\n    return None, f"não mapeado ({provided or \'sem provided_property_type\'})"\n\n\n# ---------------------------------------------------------------- inato vs condicional\ndef _section_index(item: dict[str, Any]) -> dict[str, set[str]]:\n    """propriedade -> conjunto de tipos de secção do tooltip em que aparece."""\n    idx: dict[str, set[str]] = {}\n    for sec in item.get("tooltip_sections") or []:\n        stype = str((sec or {}).get("section_type") or "").lower()\n        for attr in (sec or {}).get("section_attributes") or []:\n            names = list((attr or {}).get("properties") or []) + list((attr or {}).get("important_properties") or []) \\\n                + list((attr or {}).get("elevated_properties") or [])\n            for iw in (attr or {}).get("important_properties_with_icon") or []:\n                if isinstance(iw, dict) and iw.get("name"):\n                    names.append(iw["name"])\n            for n in names:\n                idx.setdefault(str(n), set()).add(stype)\n    return idx\n\n\ndef classify_property(item: dict[str, Any], name: str, prop: dict[str, Any],\n                      sections: dict[str, set[str]] | None = None) -> str:\n    """\'inato\' | \'condicional\' | \'indeterminado\' (regra H-INNATE)."""\n    if prop.get("conditional"):\n        return "condicional"\n    own = str(prop.get("tooltip_section") or "").lower()\n    if own:\n        return "inato" if "innate" in own else "condicional"\n    sections = sections if sections is not None else _section_index(item)\n    found = sections.get(name)\n    if found:\n        if any("innate" in s for s in found):\n            return "inato"\n        return "condicional"\n    return "indeterminado"\n\n\n@dataclass\nclass ItemEffect:\n    item_id: int\n    item: str\n    prop: str\n    raw: Any\n    value: float | None  # já em fração (percent ÷ 100) ou valor fixo\n    stat: str | None\n    stat_label: str | None\n    how: str\n    kind: str  # inato | condicional | indeterminado\n    applied: bool\n    rule: str | None\n\n\n@dataclass\nclass ItemEffects:\n    item: dict[str, Any]\n    applied: list[ItemEffect] = field(default_factory=list)\n    not_applied: list[ItemEffect] = field(default_factory=list)\n\n    @property\n    def coverage(self) -> float | None:\n        total = len(self.applied) + len(self.not_applied)\n        return len(self.applied) / total if total else None\n\n\nIGNORED_PROPS = {  # propriedades estruturais de habilidades/itens, não são atributos\n    "AbilityCooldown", "AbilityDuration", "AbilityCastRange", "AbilityCharges", "AbilityCastDelay",\n    "AbilityChannelTime", "AbilityResourceCost", "AbilityUnitTargetLimit", "AbilityPostCastDuration",\n    "AbilityCooldownBetweenCharge", "ChannelMoveSpeed", "WeaponPower",\n}\n\n\ndef item_effects(item: dict[str, Any], apply_indeterminate: bool = False) -> ItemEffects:\n    out = ItemEffects(item)\n    sections = _section_index(item)\n    for name, prop in sorted((item.get("properties") or {}).items()):\n        if not isinstance(prop, dict) or name in IGNORED_PROPS:\n            continue\n        num = to_number(prop.get("value"))\n        if num is None or num == 0:\n            continue\n        sdef, how = stat_for(name, prop)\n        kind = classify_property(item, name, prop, sections)\n        value = None if sdef is None else (num / 100.0 if sdef.unit == "percent" else num)\n        applied = sdef is not None and (kind == "inato" or (kind == "indeterminado" and apply_indeterminate))\n        eff = ItemEffect(int(item.get("id", 0)), item.get("name", "?"), name, prop.get("value"), value,\n                         sdef.key if sdef else None, sdef.label if sdef else None, how, kind, applied,\n                         sdef.rule if sdef else None)\n        (out.applied if applied else out.not_applied).append(eff)\n    return out\n', 'src.engine.weapon': '"""Modelo da arma: DPS, DPS sustentado, queda de dano, headshots e verificação contra a API."""\n\nfrom __future__ import annotations\n\nimport math\nfrom dataclasses import dataclass\nfrom typing import Any\n\nfrom ..models.common import to_number\n\nHEADSHOT_BASE_BONUS = 0.65  # R-HS\n\n\ndef _n(info: dict[str, Any], key: str) -> float | None:\n    return to_number(info.get(key))\n\n\n@dataclass\nclass WeaponBase:\n    name: str | None\n    bullet_damage: float | None\n    pellets: float | None\n    bullets_per_second: float | None  # munição gasta por segundo (wiki: Fire Rate)\n    shots_per_second: float | None\n    clip: float | None\n    reload: float | None\n    dps_api: float | None\n    dps_reload_api: float | None\n    damage_per_shot_api: float | None\n    damage_per_magazine_api: float | None\n    falloff_start: float | None\n    falloff_end: float | None\n    falloff_end_scale: float | None\n\n    @classmethod\n    def from_weapon(cls, weapon: dict[str, Any] | None) -> "WeaponBase | None":\n        if not weapon:\n            return None\n        info = weapon.get("weapon_info") or {}\n        return cls(\n            name=weapon.get("name"),\n            bullet_damage=_n(info, "bullet_damage"),\n            pellets=_n(info, "bullets"),\n            bullets_per_second=_n(info, "bullets_per_second"),\n            shots_per_second=_n(info, "shots_per_second"),\n            clip=_n(info, "clip_size"),\n            reload=_n(info, "reload_duration"),\n            dps_api=_n(info, "damage_per_second"),\n            dps_reload_api=_n(info, "damage_per_second_with_reload"),\n            damage_per_shot_api=_n(info, "damage_per_shot"),\n            damage_per_magazine_api=_n(info, "damage_per_magazine"),\n            falloff_start=_n(info, "damage_falloff_start_range"),\n            falloff_end=_n(info, "damage_falloff_end_range"),\n            falloff_end_scale=_n(info, "damage_falloff_end_scale"),\n        )\n\n    @property\n    def base_dps(self) -> float | None:\n        if self.dps_api is not None:\n            return self.dps_api\n        if self.damage_per_shot_api is not None and self.shots_per_second is not None:\n            return self.damage_per_shot_api * self.shots_per_second\n        if None not in (self.bullet_damage, self.pellets, self.shots_per_second):\n            return self.bullet_damage * self.pellets * self.shots_per_second  # type: ignore[operator]\n        return None\n\n\ndef sustained_fraction(clip: float | None, bullets_per_second: float | None, reload: float | None) -> float | None:\n    """H-SUST: fração do tempo a disparar = t_carregador / (t_carregador + recarga)."""\n    if not clip or not bullets_per_second or reload is None:\n        return None\n    mag_time = clip / bullets_per_second\n    return mag_time / (mag_time + reload)\n\n\ndef falloff_multiplier(distance: float | None, start: float | None, end: float | None,\n                       end_scale: float | None) -> tuple[float, bool]:\n    """R-FALL. Devolve (multiplicador, dados_disponíveis)."""\n    if distance is None or distance <= 0:\n        return 1.0, True\n    if start is None or end is None or end_scale is None or end <= start:\n        return 1.0, False\n    if distance <= start:\n        return 1.0, True\n    if distance >= end:\n        return end_scale, True\n    t = (distance - start) / (end - start)\n    return 1.0 + t * (end_scale - 1.0), True\n\n\ndef headshot_multiplier(rate: float, crit_bonus_scale: float = 0.0, can_crit: bool = True) -> float:\n    """R-HS: multiplicador esperado para uma taxa de headshots (0–1)."""\n    if not can_crit or rate <= 0:\n        return 1.0\n    crit = 1.0 + HEADSHOT_BASE_BONUS + crit_bonus_scale\n    return 1.0 + min(1.0, rate) * (crit - 1.0)\n\n\n@dataclass\nclass WeaponResult:\n    damage_per_bullet: float | None\n    dps: float | None                 # contínuo, sem recarga\n    sustained_dps: float | None       # com recarga (H-SUST)\n    effective_dps: float | None       # sustentado × queda × headshot × resistência do alvo\n    clip: float | None\n    bullets_per_second: float | None\n    magazine_time: float | None\n    damage_per_magazine: float | None  # sem recarga, antes de queda/headshot/resistência\n    falloff_mult: float\n    falloff_known: bool\n    headshot_mult: float\n    resist_mult: float\n    reload: float | None = None\n\n\ndef evaluate_weapon(wb: WeaponBase | None, *, weapon_damage_pct: float, fire_rate_pct: float, ammo_pct: float,\n                    ammo_flat: float, distance: float | None, headshot_rate: float, crit_bonus_scale: float,\n                    can_crit: bool, target_bullet_resist: float) -> WeaponResult | None:\n    if wb is None:\n        return None\n    base = wb.base_dps\n    dmg_mult = 1.0 + weapon_damage_pct          # H-WD\n    rate_mult = 1.0 + fire_rate_pct              # H-FR\n    dps = base * dmg_mult * rate_mult if base is not None else None\n    clip = None\n    if wb.clip is not None:\n        clip = float(round(wb.clip * (1.0 + ammo_pct) + ammo_flat))  # H-AMMO\n    bps = wb.bullets_per_second * rate_mult if wb.bullets_per_second else None\n    frac = sustained_fraction(clip, bps, wb.reload)\n    sustained = dps * frac if (dps is not None and frac is not None) else None\n    fall, known = falloff_multiplier(distance, wb.falloff_start, wb.falloff_end, wb.falloff_end_scale)\n    hs = headshot_multiplier(headshot_rate, crit_bonus_scale, can_crit)\n    resist_mult = 1.0 - target_bullet_resist\n    effective = sustained * fall * hs * resist_mult if sustained is not None else None\n    per_bullet = wb.bullet_damage * dmg_mult if wb.bullet_damage is not None else None\n    per_mag = None\n    if dps is not None and clip and bps:\n        per_mag = dps * (clip / bps)\n    return WeaponResult(per_bullet, dps, sustained, effective, clip, bps, (clip / bps) if clip and bps else None,\n                        per_mag, fall, known, hs, resist_mult, wb.reload)\n\n\n# ---------------------------------------------------------------- verificação contra a API\ndef consistency_checks(wb: WeaponBase | None) -> list[dict[str, Any]]:\n    """Compara fórmulas do motor com valores derivados que a própria API publica."""\n    if wb is None:\n        return []\n    out = []\n\n    def add(check: str, formula: str, ours: float | None, api: float | None, rule: str) -> None:\n        if ours is None or api is None:\n            out.append({"verificação": check, "fórmula": formula, "motor": ours, "API": api, "erro %": None,\n                        "regra": rule, "resultado": "sem dados"})\n            return\n        err = abs(ours - api) / abs(api) * 100 if api else (0.0 if ours == 0 else math.inf)\n        out.append({"verificação": check, "fórmula": formula, "motor": round(ours, 4), "API": round(api, 4),\n                    "erro %": round(err, 3), "regra": rule, "resultado": "OK" if err < 2 else "DIVERGE"})\n\n    if wb.bullet_damage is not None and wb.pellets is not None:\n        add("dano por disparo", "dano por bala × projéteis", wb.bullet_damage * wb.pellets,\n            wb.damage_per_shot_api, "base")\n    if wb.damage_per_shot_api is not None and wb.shots_per_second is not None:\n        add("DPS", "dano por disparo × disparos/s", wb.damage_per_shot_api * wb.shots_per_second, wb.dps_api, "base")\n    frac = sustained_fraction(wb.clip, wb.bullets_per_second, wb.reload)\n    add("DPS com recarga", "DPS × t_carregador/(t_carregador+recarga)",\n        wb.dps_api * frac if (wb.dps_api is not None and frac is not None) else None, wb.dps_reload_api, "H-SUST")\n    return out\n', 'src.models': '"""Modelos Pydantic alinhados com os esquemas do OpenAPI da Deadlock API.\n\nSó os campos documentados são tipados; campos extra são preservados (`extra="allow"`)\npara não perder informação quando a API evolui.\n"""\n\nfrom .common import ApiModel, to_number  # noqa: F401\nfrom .hero import Hero, StartingStat  # noqa: F401\nfrom .item import Ability, ItemProperty, Upgrade, Weapon, parse_item  # noqa: F401\nfrom .meta import Patch, Rank, SteamInfo  # noqa: F401\nfrom .stats import AnalyticsHeroStats, ItemPermutationStats, ItemStats  # noqa: F401\n', 'src.models.common': 'from __future__ import annotations\n\nfrom typing import Any, Union\n\nfrom pydantic import BaseModel, ConfigDict\n\nStringOrNumber = Union[float, int, str]\n\n\nclass ApiModel(BaseModel):\n    """Base: aceita campos extra (a API pode acrescentar propriedades)."""\n\n    model_config = ConfigDict(extra="allow", populate_by_name=True)\n\n\ndef to_number(value: Any) -> float | None:\n    """Converte StringOrNumber em float. Devolve None se não for numérico.\n\n    Não remove unidades nem adivinha formatos: "12m" -> None (fica como texto).\n    """\n    if value is None or isinstance(value, bool):\n        return None\n    if isinstance(value, (int, float)):\n        return float(value)\n    if isinstance(value, str):\n        txt = value.strip()\n        if not txt:\n            return None\n        try:\n            return float(txt)\n        except ValueError:\n            return None\n    return None\n', 'src.models.hero': '"""Hero — esquema `Hero` de /v1/assets/heroes."""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom pydantic import Field\n\nfrom .common import ApiModel\n\n# Campos marcados como obrigatórios no OpenAPI. A validação exige apenas os que a\n# aplicação usa; os restantes geram um aviso se faltarem (ver data/validation.py).\nDOCUMENTED_REQUIRED = [\n    "id", "class_name", "name", "description", "player_selectable", "disabled",\n    "in_development", "needs_testing", "assigned_players_only", "tags", "limited_testing",\n    "complexity", "skin", "images", "models", "items", "starting_stats", "item_slot_info",\n    "physics", "colors", "shop_stat_display", "stats_display", "hero_stats_ui", "level_info",\n    "scaling_stats", "purchase_bonuses", "standard_level_up_upgrades",\n]\n\n# Chaves documentadas de StartingStats (19 obrigatórias + 7 opcionais).\nSTARTING_STAT_LABELS_PT = {\n    "max_health": "Vida máxima",\n    "base_health_regen": "Regeneração de vida (base)",\n    "ooc_health_regen": "Regeneração fora de combate",\n    "bullet_armor_damage_reduction": "Resistência a balas",\n    "tech_armor_damage_reduction": "Resistência Spirit",\n    "crit_damage_received_scale": "Escala de dano crítico recebido",\n    "max_move_speed": "Velocidade de movimento",\n    "sprint_speed": "Velocidade de sprint",\n    "crouch_speed": "Velocidade agachado",\n    "move_acceleration": "Aceleração",\n    "stamina": "Stamina",\n    "stamina_regen_per_second": "Regeneração de stamina /s",\n    "light_melee_damage": "Dano de melee leve",\n    "heavy_melee_damage": "Dano de melee pesado",\n    "weapon_power": "Weapon power",\n    "weapon_power_scale": "Escala de weapon power",\n    "reload_speed": "Velocidade de recarga",\n    "proc_build_up_rate_scale": "Escala de build-up de procs",\n    "ability_resource_max": "Recurso de habilidade (máx.)",\n    "ability_resource_regen_per_second": "Regeneração do recurso /s",\n    "tech_duration": "Duração Spirit (escala)",\n    "tech_range": "Alcance Spirit (escala)",\n    "air_dash_distance_in_meters": "Dash aéreo (m)",\n    "air_dash_duration": "Dash aéreo (duração)",\n    "ground_dash_distance_in_meters": "Dash no chão (m)",\n    "ground_dash_duration": "Dash no chão (duração)",\n}\n\n\nclass StartingStat(ApiModel):\n    value: float\n    display_stat_name: str\n\n\nclass HeroDescription(ApiModel):\n    lore: str | None = None\n    playstyle: str | None = None\n    role: str | None = None\n\n\nclass HeroImages(ApiModel):\n    icon_hero_card: str | None = None\n    icon_hero_card_webp: str | None = None\n    icon_image_small: str | None = None\n    icon_image_small_webp: str | None = None\n    minimap_image: str | None = None\n    background_image: str | None = None\n    name_image: str | None = None\n    weapon_image: str | None = None\n\n\nclass Hero(ApiModel):\n    id: int\n    class_name: str\n    name: str\n    description: HeroDescription | None = None\n    player_selectable: bool = True\n    disabled: bool = False\n    in_development: bool = False\n    tags: list[str] = Field(default_factory=list)\n    complexity: int | None = None\n    hero_type: str | None = None\n    images: HeroImages | None = None\n    items: dict[str, str]\n    starting_stats: dict[str, StartingStat | None]\n    level_info: dict[str, Any] = Field(default_factory=dict)\n    standard_level_up_upgrades: dict[str, float] = Field(default_factory=dict)\n    scaling_stats: dict[str, Any] = Field(default_factory=dict)\n    purchase_bonuses: dict[str, Any] = Field(default_factory=dict)\n    item_slot_info: dict[str, Any] = Field(default_factory=dict)\n\n    @property\n    def is_playable(self) -> bool:\n        return self.player_selectable and not self.disabled and not self.in_development\n', 'src.models.item': '"""Item — oneOf Ability | Weapon | Upgrade (discriminador `type`) de /v1/assets/items."""\n\nfrom __future__ import annotations\n\nfrom typing import Any, Literal\n\nfrom pydantic import Field, ValidationError\n\nfrom .common import ApiModel, StringOrNumber, to_number\n\nITEM_TYPES = ("ability", "weapon", "upgrade")\nSLOT_TYPES = ("weapon", "spirit", "vitality")  # enum ItemSlotType\nSLOT_LABELS_PT = {"weapon": "Weapon", "spirit": "Spirit", "vitality": "Vitality"}\n\n\nclass ScaleFunction(ApiModel):\n    """RawItemPropertyScaleFunctionSubclass."""\n\n    class_name: str | None = None\n    subclass_name: str | None = None\n    specific_stat_scale_type: str | None = None\n    scaling_stats: list[str] | None = None\n    stat_scale: float | None = None\n    street_brawl_stat_scale: float | None = None\n\n\nclass ItemProperty(ApiModel):\n    value: StringOrNumber | None = None\n    street_brawl_value: StringOrNumber | None = None\n    label: str | None = None\n    prefix: str | None = None\n    postfix: str | None = None\n    postvalue_label: str | None = None\n    css_class: str | None = None\n    display_units: str | None = None\n    provided_property_type: str | None = None\n    conditional: str | None = None\n    disable_value: str | None = None\n    negative_attribute: bool | None = None\n    scale_function: ScaleFunction | None = None\n    usage_flags: list[str] | None = None\n    tooltip_section: str | None = None\n    tooltip_is_important: bool | None = None\n    tooltip_is_elevated: bool | None = None\n\n    @property\n    def number(self) -> float | None:\n        return to_number(self.value)\n\n\nclass PropertyUpgrade(ApiModel):\n    """RawAbilityUpgradePropertyUpgrade."""\n\n    name: str\n    bonus: StringOrNumber\n    upgrade_type: str | None = None\n    scale_stat_filter: str | None = None\n\n\nclass AbilityUpgrade(ApiModel):\n    property_upgrades: list[PropertyUpgrade] = Field(default_factory=list)\n\n\nclass UpgradeDescription(ApiModel):\n    desc: str | None = None\n    desc2: str | None = None\n    active: str | None = None\n    passive: str | None = None\n\n\nclass ItemBase(ApiModel):\n    id: int\n    class_name: str\n    name: str\n    type: str\n    properties: dict[str, ItemProperty] | None = None\n    hero: int | None = None\n    heroes: list[int] | None = None\n    image: str | None = None\n    image_webp: str | None = None\n    update_time: int | None = None\n\n\nclass Ability(ItemBase):\n    type: Literal["ability"] = "ability"\n    ability_type: str | None = None  # innate | item | signature | ultimate | weapon | melee | ...\n    behaviours: list[str] | None = None\n    boss_damage_scale: float | None = None\n    description: Any = None  # esquema AbilityDescription não validado -> mantido em bruto\n    upgrades: list[AbilityUpgrade] | None = None\n\n\nclass Weapon(ItemBase):\n    type: Literal["weapon"] = "weapon"\n    weapon_info: dict[str, Any] | None = None\n\n\nclass Upgrade(ItemBase):\n    type: Literal["upgrade"] = "upgrade"\n    item_slot_type: str\n    item_tier: int\n    activation: str\n    is_active_item: bool\n    shopable: bool\n    cost: int | None = None\n    component_items: list[str] | None = None\n    disabled: bool | None = None\n    description: UpgradeDescription | None = None\n    shop_image: str | None = None\n    shop_image_webp: str | None = None\n    upgrades: list[AbilityUpgrade] | None = None\n\n\n_MODELS = {"ability": Ability, "weapon": Weapon, "upgrade": Upgrade}\n\n\ndef parse_item(raw: dict[str, Any]) -> Ability | Weapon | Upgrade:\n    """Valida um item segundo o seu `type`. Lança ValueError se o tipo for desconhecido."""\n    model = _MODELS.get(str(raw.get("type")))\n    if model is None:\n        raise ValueError(f"tipo de item desconhecido: {raw.get(\'type\')!r}")\n    return model.model_validate(raw)\n\n\n__all__ = [\n    "Ability", "AbilityUpgrade", "ItemProperty", "PropertyUpgrade", "ScaleFunction",\n    "Upgrade", "UpgradeDescription", "Weapon", "parse_item", "ValidationError",\n    "ITEM_TYPES", "SLOT_TYPES", "SLOT_LABELS_PT",\n]\n', 'src.models.meta': '"""Esquemas de metadados: SteamInfo, Rank, Patch."""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom .common import ApiModel\n\n\nclass SteamInfo(ApiModel):\n    client_version: int\n    server_version: int | None = None\n    version_date: str | None = None\n    version_time: str | None = None\n    version_datetime: str | None = None\n    product_name: str | None = None\n    source_revision: int | None = None\n\n\nclass Rank(ApiModel):\n    tier: int\n    name: str\n    color: str | None = None\n    images: dict[str, Any] | None = None\n\n\nclass PatchGuid(ApiModel):\n    text: str\n    is_perma_link: bool | None = None\n\n\nclass Patch(ApiModel):\n    title: str\n    pub_date: str\n    link: str\n    guid: PatchGuid\n    author: str | None = None\n    category: dict[str, Any] | None = None\n\n\ndef badge_value(tier: int, subrank: int) -> int:\n    """Badge da API: tier nos dígitos iniciais, sub-rank no último dígito (0–116)."""\n    return int(tier) * 10 + int(subrank)\n\n\ndef badge_range_for_tiers(min_tier: int, max_tier: int) -> tuple[int, int]:\n    """Intervalo de badge que cobre todos os sub-ranks dos tiers indicados."""\n    return badge_value(min_tier, 0), min(116, badge_value(max_tier, 9))\n', 'src.models.stats': '"""Esquemas de estatísticas (/v1/analytics/*)."""\n\nfrom __future__ import annotations\n\nfrom .common import ApiModel\n\n\nclass AnalyticsHeroStats(ApiModel):\n    hero_id: int\n    bucket: int\n    wins: int\n    losses: int\n    matches: int\n    matches_per_bucket: int | None = None\n    total_kills: int | None = None\n    total_deaths: int | None = None\n    total_assists: int | None = None\n    total_net_worth: int | None = None\n    total_player_damage: int | None = None\n    total_player_damage_taken: int | None = None\n    total_shots_hit: int | None = None\n    total_shots_missed: int | None = None\n\n\nclass ItemStats(ApiModel):\n    item_id: int\n    bucket: int\n    wins: int\n    losses: int\n    matches: int\n    players: int\n    avg_buy_time_s: float\n    avg_sell_time_s: float\n    avg_buy_time_relative: float\n    avg_sell_time_relative: float\n    sold: int | None = None\n\n\nclass ItemPermutationStats(ApiModel):\n    item_ids: list[int]\n    wins: int\n    losses: int\n    matches: int\n\n\nclass BuildItemStats(ApiModel):\n    item_id: int\n    builds: int\n\n\nclass HeroCounterStats(ApiModel):\n    hero_id: int\n    enemy_hero_id: int\n    wins: int\n    matches_played: int\n\n\nclass HeroSynergyStats(ApiModel):\n    hero_id1: int\n    hero_id2: int\n    wins: int\n    matches_played: int\n', 'src.optimizer': '"""Fase 4 — procura automática de builds.\n\n* fast_model.py         — reavaliação rápida (os mesmos cálculos do motor, pré-computados)\n* objective_function.py — função objetivo configurável, estilos e calibração com dados reais\n* build_optimizer.py    — beam search + pesquisa local sob orçamento e restrições de slots\n* pareto.py             — fronteira de Pareto (dano da arma × habilidades × sobrevivência)\n* purchase_order.py     — ordem de compra por fases, testada contra ordens alternativas\n* item_synergy.py       — sinergias mecânicas (motor) e empíricas (item-permutation-stats)\n* sensitivity.py        — estabilidade da build quando os pesos mudam\n* report.py             — relatório final da build (justificação, custos, hipóteses)\n"""\n', 'src.optimizer.build_optimizer': '"""Procura de builds: beam search + pesquisa local, sob orçamento e restrições de slots.\n\nSó entram como candidatos itens cujo efeito o motor consegue modelar nos objetivos; os restantes\nsão listados à parte (a procura não os pode justificar com números).\n"""\n\nfrom __future__ import annotations\n\nimport time\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nfrom ..engine.build import BASE_SLOTS_PER_COLUMN, MAX_ACTIVES, MAX_FLEX\nfrom .fast_model import FastModel, ItemVec\nfrom .objective_function import Objective\n\n\n@dataclass\nclass OptimizerConfig:\n    budget: int\n    flex_slots: int = MAX_FLEX\n    beam_width: int = 12\n    locked: list[int] = field(default_factory=list)\n    excluded: set[int] = field(default_factory=set)\n    max_local_rounds: int = 8\n    pool_limit: int = 6000\n\n\n@dataclass\nclass Candidate:\n    ids: frozenset[int]\n    score: float\n    metrics: dict[str, float | None]\n    cost: int\n\n\n@dataclass\nclass OptimizationResult:\n    best: Candidate | None\n    top: list[Candidate]\n    pool: list[Candidate]\n    candidates: list[dict[str, Any]]\n    unmodeled: list[dict[str, Any]]\n    replacements: dict[int, list[tuple[int, float]]]\n    evaluations: int\n    seconds: float\n    messages: list[str]\n\n\nclass Constraints:\n    def __init__(self, flex_slots: int = MAX_FLEX):\n        self.flex = max(0, min(MAX_FLEX, int(flex_slots)))\n        self.max_items = 3 * BASE_SLOTS_PER_COLUMN + self.flex\n\n    def feasible(self, vecs: list[ItemVec], budget: int | None = None) -> bool:\n        ids = [v.id for v in vecs]\n        if len(ids) != len(set(ids)) or len(vecs) > self.max_items:\n            return False\n        if budget is not None and sum(v.cost for v in vecs) > budget:\n            return False\n        classes = {v.cls for v in vecs}\n        if any(c in classes for v in vecs for c in v.components):\n            return False  # componente + melhoria na mesma build: o componente seria consumido\n        cols = {"weapon": 0, "vitality": 0, "spirit": 0}\n        for v in vecs:\n            if v.slot in cols:\n                cols[v.slot] += 1\n        if sum(max(0, n - BASE_SLOTS_PER_COLUMN) for n in cols.values()) > self.flex:\n            return False\n        return sum(1 for v in vecs if v.active) <= MAX_ACTIVES\n\n    def can_add(self, vecs: list[ItemVec], new: ItemVec, budget: int) -> bool:\n        return self.feasible(vecs + [new], budget)\n\n\ndef _items(ids, by_id: dict[int, dict]) -> list[dict]:\n    return [by_id[i] for i in sorted(ids)]\n\n\ndef select_candidates(obj: Objective, shop: list[dict], excluded: set[int]) -> tuple[list[dict], list[dict]]:\n    """Itens com ganho modelado > 0 sozinhos; os outros ficam fora da procura (e são listados)."""\n    base_score, _ = obj.score([])\n    keep, out = [], []\n    for it in shop:\n        if int(it["id"]) in excluded or it.get("disabled"):\n            continue\n        s, _ = obj.score([it])\n        gain = s - base_score + COST_EPS * int(it.get("cost") or 0)\n        (keep if gain > 1e-12 else out).append(it)\n    return keep, out\n\n\nCOST_EPS = 1e-7\n\n\ndef optimize(model: FastModel, obj: Objective, shop: list[dict], cfg: OptimizerConfig) -> OptimizationResult:\n    t0 = time.perf_counter()\n    ev0 = model.evaluations\n    msgs: list[str] = []\n    by_id = {int(i["id"]): i for i in shop}\n    cons = Constraints(cfg.flex_slots)\n    cands, unmodeled = select_candidates(obj, shop, set(cfg.excluded) | set(cfg.locked))\n    cand_vecs = [model.vec(i) for i in cands]\n\n    locked = [by_id[i] for i in cfg.locked if i in by_id]\n    lvecs = [model.vec(i) for i in locked]\n    if not cons.feasible(lvecs, cfg.budget):\n        msgs.append("Os itens obrigatórios não cabem no orçamento ou nos slots.")\n        return OptimizationResult(None, [], [], cands, unmodeled, {}, 0, 0.0, msgs)\n\n    seen: dict[frozenset[int], Candidate] = {}\n\n    def evaluate(ids: frozenset[int]) -> Candidate:\n        c = seen.get(ids)\n        if c is None:\n            items = _items(ids, by_id)\n            s, m = obj.score(items)\n            c = Candidate(ids, s, m, sum(int(i.get("cost") or 0) for i in items))\n            seen[ids] = c\n        return c\n\n    start = frozenset(int(i["id"]) for i in locked)\n    beam = [evaluate(start)]\n    while True:\n        children: dict[frozenset[int], Candidate] = {}\n        for st in beam:\n            svecs = [model.vec(by_id[i]) for i in st.ids]\n            for cv in cand_vecs:\n                if cv.id in st.ids:\n                    continue\n                key = st.ids | {cv.id}\n                if key in children:\n                    continue\n                if key in seen:  # já avaliada noutro ramo (só se avaliam builds viáveis)\n                    children[key] = seen[key]\n                    continue\n                if not cons.can_add(svecs, cv, cfg.budget):\n                    continue\n                children[key] = evaluate(key)\n        if not children:\n            break\n        beam = sorted(children.values(), key=lambda c: -c.score)[:max(1, cfg.beam_width)]\n\n    best = max(seen.values(), key=lambda c: c.score)\n    best, replacements = _local_search(model, obj, best, cand_vecs, by_id, cons, cfg, evaluate, set(cfg.locked))\n\n    pool = sorted(seen.values(), key=lambda c: -c.score)[:cfg.pool_limit]\n    top = _diverse_top(pool, best, k=5)\n    return OptimizationResult(best, top, pool, cands, unmodeled, replacements,\n                              model.evaluations - ev0, time.perf_counter() - t0, msgs)\n\n\ndef _local_search(model, obj, best: Candidate, cand_vecs, by_id, cons: Constraints, cfg: OptimizerConfig,\n                  evaluate, locked: set[int]):\n    """Trocas 1-por-1 e adições enquanto melhorarem o score; regista a melhor alternativa de cada item."""\n    for _ in range(cfg.max_local_rounds):\n        improved = False\n        cur_vecs = [model.vec(by_id[i]) for i in best.ids]\n        # adições (se sobrar orçamento)\n        for cv in cand_vecs:\n            if cv.id not in best.ids and cons.can_add(cur_vecs, cv, cfg.budget):\n                c = evaluate(best.ids | {cv.id})\n                if c.score > best.score + 1e-12:\n                    best, improved = c, True\n                    break\n        if improved:\n            continue\n        for out_id in sorted(best.ids - locked):\n            rest = [v for v in cur_vecs if v.id != out_id]\n            for cv in cand_vecs:\n                if cv.id in best.ids or not cons.can_add(rest, cv, cfg.budget):\n                    continue\n                c = evaluate((best.ids - {out_id}) | {cv.id})\n                if c.score > best.score + 1e-12:\n                    best, improved = c, True\n                    break\n            if improved:\n                break\n        if not improved:\n            break\n\n    replacements: dict[int, list[tuple[int, float]]] = {}\n    cur_vecs = [model.vec(by_id[i]) for i in best.ids]\n    for out_id in sorted(best.ids - locked):\n        rest = [v for v in cur_vecs if v.id != out_id]\n        opts = []\n        for cv in cand_vecs:\n            if cv.id in best.ids or not cons.can_add(rest, cv, cfg.budget):\n                continue\n            c = evaluate((best.ids - {out_id}) | {cv.id})\n            opts.append((cv.id, best.score - c.score))\n        replacements[out_id] = sorted(opts, key=lambda x: x[1])[:3]\n    return best, replacements\n\n\ndef _diverse_top(pool: list[Candidate], best: Candidate, k: int = 5, min_diff: int = 2) -> list[Candidate]:\n    out = [best]\n    for c in pool:\n        if len(out) >= k:\n            break\n        if all(len(c.ids ^ o.ids) >= min_diff * 2 or (len(c.ids ^ o.ids) >= min_diff and len(c.ids) == len(o.ids))\n               for o in out):\n            if c.cost >= 0.8 * best.cost:\n                out.append(c)\n    return out\n\n\ndef popular_build(model: FastModel, item_rows: list[dict], shop_by_id: dict[int, dict], budget: int,\n                  flex_slots: int = MAX_FLEX) -> list[dict]:\n    """Build \'popular\' de referência: os itens mais comprados (dados observados) que cabem no orçamento.\n\n    Se um item mais comprado for melhoria de um componente já escolhido, substitui o componente.\n    """\n    cons = Constraints(flex_slots)\n    chosen: list[dict] = []\n    for r in sorted(item_rows, key=lambda r: -int(r.get("matches") or 0)):\n        it = shop_by_id.get(int(r["item_id"]))\n        if it is None or it in chosen:\n            continue\n        comps = set(it.get("component_items") or [])\n        trial = [c for c in chosen if c.get("class_name") not in comps] + [it]\n        if any(it.get("class_name") in (c.get("component_items") or []) for c in chosen):\n            continue  # já temos a melhoria deste componente\n        if cons.feasible([model.vec(x) for x in trial], budget):\n            chosen = trial\n    return chosen\n', 'src.optimizer.fast_model': '"""Modelo rápido para o otimizador.\n\nFaz EXATAMENTE os mesmos cálculos que engine.model.Evaluator (os testes comparam os dois em builds\naleatórias), mas pré-computa tudo o que não depende da build: efeitos de cada item, arma do herói,\nperfis das habilidades e tabela de investimento. Assim avaliar uma build custa microssegundos.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Any, Iterable\n\nfrom ..data.normalizer import hero_weapon\nfrom ..engine.build import Scenario\nfrom ..engine.model import Evaluator, _resist_value, parse_purchase_bonuses\nfrom ..engine.stats import STATS, item_effects\nfrom ..engine.weapon import WeaponBase, evaluate_weapon\n\nOBJECTIVE_METRICS = {\n    "weapon": "weapon_dps_effective",\n    "ability": "ability_damage_index",\n    "survival": "ehp_mixed",\n    "mobility": "move_speed",\n}\n\n\n@dataclass\nclass ItemVec:\n    id: int\n    item: dict[str, Any]\n    cost: int\n    slot: str | None\n    active: bool\n    cls: str | None\n    components: tuple[str, ...]\n    additive: dict[str, float]\n    multiplicative: dict[str, list[float]]\n    coverage: float | None\n\n\nclass FastModel:\n    def __init__(self, evaluator: Evaluator, hero: dict[str, Any], scenario: Scenario,\n                 tiers: dict[str, int] | None = None):\n        self.ev = evaluator\n        self.hero = hero\n        self.sc = scenario\n        self.tiers = tiers or {}\n        self._vec: dict[int, ItemVec] = {}\n        w = hero_weapon(hero, evaluator.items_by_class)\n        self.wb = WeaponBase.from_weapon({"name": w["name"], "weapon_info": w["weapon_info"]} if w else None)\n        self.can_crit = str(hero.get("name", "")).lower() not in evaluator.no_crit\n        ss = hero.get("starting_stats") or {}\n        hp = (ss.get("max_health") or {}).get("value")\n        self.base_hp = float(hp) if hp is not None else None\n        self.base_br = _resist_value(ss.get("bullet_armor_damage_reduction"))\n        self.base_sr = _resist_value(ss.get("tech_armor_damage_reduction"))\n        ms = (ss.get("max_move_speed") or {}).get("value")\n        self.base_move = float(ms) if ms is not None else None\n        self.profiles = evaluator.ability_profiles(hero, self.tiers)\n        self.invest = parse_purchase_bonuses(hero.get("purchase_bonuses"))\n        self.evaluations = 0\n\n    # ---------------------------------------------------------------- itens\n    def vec(self, item: dict[str, Any]) -> ItemVec:\n        iid = int(item["id"])\n        v = self._vec.get(iid)\n        if v is None:\n            eff = item_effects(item, self.ev.apply_indeterminate)\n            add: dict[str, float] = {}\n            mul: dict[str, list[float]] = {}\n            for e in eff.applied:\n                sdef = STATS[e.stat]  # type: ignore[index]\n                if sdef.stacking == "multiplicative":\n                    mul.setdefault(sdef.key, []).append(e.value or 0.0)\n                else:\n                    add[sdef.key] = add.get(sdef.key, 0.0) + (e.value or 0.0)\n            v = ItemVec(iid, item, int(item.get("cost") or 0), item.get("item_slot_type"),\n                        bool(item.get("is_active_item")), item.get("class_name"),\n                        tuple(item.get("component_items") or ()), add, mul, eff.coverage)\n            self._vec[iid] = v\n        return v\n\n    # ---------------------------------------------------------------- avaliação\n    def metrics(self, items: Iterable[dict[str, Any]]) -> dict[str, float | None]:\n        self.evaluations += 1\n        vecs = [self.vec(i) for i in items]\n        classes = {v.cls for v in vecs}\n        consumed = {c for v in vecs for c in v.components if c in classes}\n        vecs = [v for v in vecs if v.cls not in consumed]\n        add: dict[str, float] = {}\n        prod: dict[str, float] = {}\n        invested = {"weapon": 0, "vitality": 0, "spirit": 0}\n        for v in vecs:\n            for k, x in v.additive.items():\n                add[k] = add.get(k, 0.0) + x\n            for k, xs in v.multiplicative.items():\n                p = prod.get(k, 1.0)\n                for x in xs:\n                    p *= (1.0 - x)\n                prod[k] = p\n            if v.slot in invested:\n                invested[v.slot] += v.cost\n        if self.invest:\n            for slot, entries in self.invest.items():\n                souls = invested.get(slot.lower(), 0)\n                per_stat: dict[str, float] = {}\n                for thr, stat, val in entries:\n                    if souls >= thr:\n                        per_stat[stat] = val\n                for stat, val in per_stat.items():\n                    if STATS[stat].stacking == "multiplicative":\n                        prod[stat] = prod.get(stat, 1.0) * (1.0 - val)\n                    else:\n                        add[stat] = add.get(stat, 0.0) + val\n        stats = dict(add)\n        for k, p in prod.items():\n            stats[k] = 1.0 - p\n\n        sc = self.sc\n        w = evaluate_weapon(\n            self.wb, weapon_damage_pct=stats.get("weapon_damage_pct", 0.0), fire_rate_pct=stats.get("fire_rate_pct", 0.0),\n            ammo_pct=stats.get("ammo_pct", 0.0), ammo_flat=stats.get("ammo_flat", 0.0), distance=sc.distance_m,\n            headshot_rate=sc.headshot_rate, crit_bonus_scale=0.0, can_crit=self.can_crit,\n            target_bullet_resist=max(-1.0, sc.target_bullet_resist - sc.shred_bullet))\n        out: dict[str, float | None] = {\n            "weapon_dps_effective": w.effective_dps if w else None,\n            "weapon_dps_sustained": w.sustained_dps if w else None,\n            "weapon_dps": w.dps if w else None,\n            "magazine_damage": w.damage_per_magazine if w else None,\n        }\n        if self.base_hp is not None:\n            hp = self.base_hp * (1.0 + stats.get("health_pct", 0.0)) + stats.get("health_flat", 0.0)\n            br = 1.0 - (1.0 - self.base_br) * (1.0 - stats.get("bullet_resist", 0.0))\n            sr = 1.0 - (1.0 - self.base_sr) * (1.0 - stats.get("spirit_resist", 0.0))\n            m = sc.incoming_bullet_share\n            den = m * (1 - br) + (1 - m) * (1 - sr)\n            out.update({"health": hp, "ehp_bullet": hp / (1 - br) if br < 1 else None,\n                        "ehp_spirit": hp / (1 - sr) if sr < 1 else None, "ehp_mixed": hp / den if den > 0 else None})\n        else:\n            out.update({"health": None, "ehp_bullet": None, "ehp_spirit": None, "ehp_mixed": None})\n        sp = stats.get("spirit_power", 0.0)\n        cdr = stats.get("ability_cdr", 0.0)\n        idx = burst = 0.0\n        for prof in self.profiles:\n            cd_eff, dmg, _ = Evaluator.ability_values(prof, sp, cdr)\n            if dmg:\n                burst += dmg\n                if cd_eff:\n                    idx += dmg / cd_eff\n        out["ability_damage_index"] = idx if self.profiles else None\n        out["ability_burst_index"] = burst if self.profiles else None\n        out["spirit_power"] = sp\n        out["ability_cdr"] = cdr\n        out["move_speed"] = (self.base_move + stats.get("move_speed", 0.0)) if self.base_move is not None else None\n        return out\n', 'src.optimizer.item_synergy': '"""Sinergias entre itens.\n\n* Mecânicas: calculadas pelo motor. sinergia(A,B) = score(A+B) − score(A) − score(B) + score(∅).\n  Positiva quando os efeitos se multiplicam (ex.: dano % × fire rate, Spirit Power × redução de cooldown);\n  negativa quando se sobrepõem (ex.: duas resistências multiplicativas têm retornos decrescentes).\n* Empíricas: /v1/analytics/item-permutation-stats (pares de itens no mesmo jogador). Compara o win rate do\n  par com o esperado se os efeitos fossem aditivos em log-odds; teste binomial + Benjamini–Hochberg.\n  É associação observada, confundida pelo momento de compra — nunca substitui a sinergia mecânica.\n"""\n\nfrom __future__ import annotations\n\nimport math\nfrom itertools import combinations\nfrom typing import Any\n\nimport pandas as pd\n\nfrom ..analytics.confidence import bh_adjust, binom_pvalue, sample_label\nfrom ..engine.stats import STATS\nfrom .objective_function import Objective\n\n\ndef _stats_of(obj: Objective, item: dict) -> set[str]:\n    v = obj.model.vec(item)\n    return set(v.additive) | set(v.multiplicative)\n\n\nINTERACTIONS = [\n    ("weapon_damage_pct", "fire_rate_pct", "dano % × cadência (multiplicam-se)"),\n    ("spirit_power", "ability_cdr", "Spirit Power × redução de cooldown"),\n    ("health_flat", "bullet_resist", "vida × resistência a balas"),\n    ("health_flat", "spirit_resist", "vida × resistência Spirit"),\n    ("fire_rate_pct", "ammo_pct", "cadência × munição"),\n    ("weapon_damage_pct", "ammo_pct", "dano % × munição"),\n]\n\n\ndef _why(a: set[str], b: set[str]) -> str:\n    found = [txt for s1, s2, txt in INTERACTIONS if (s1 in a and s2 in b) or (s2 in a and s1 in b)]\n    if found:\n        return "; ".join(found)\n    if a & b & {"bullet_resist", "spirit_resist", "ability_cdr"}:\n        return "mesmo atributo multiplicativo (retornos decrescentes)"\n    labels = sorted({STATS[s].label for s in (a | b) if s in STATS})\n    return ", ".join(labels[:4])\n\n\ndef mechanical_synergies(obj: Objective, items: list[dict], top_candidates: int = 25) -> pd.DataFrame:\n    s0, _ = obj.score([])\n    single = []\n    for it in items:\n        s, _ = obj.score([it])\n        single.append((s - s0, it))\n    single.sort(key=lambda x: -x[0])\n    pool = [it for _, it in single[:top_candidates]]\n    gain = {int(it["id"]): g for g, it in single}\n    rows = []\n    for a, b in combinations(pool, 2):\n        if a.get("class_name") in (b.get("component_items") or []) or b.get("class_name") in (a.get("component_items") or []):\n            continue\n        sab, _ = obj.score([a, b])\n        syn = (sab - s0) - gain[int(a["id"])] - gain[int(b["id"])]\n        rows.append({"item A": a.get("name"), "item B": b.get("name"), "sinergia (pts)": syn * 100,\n                     "ganho A (pts)": gain[int(a["id"])] * 100, "ganho B (pts)": gain[int(b["id"])] * 100,\n                     "porquê": _why(_stats_of(obj, a), _stats_of(obj, b)), "_a": int(a["id"]), "_b": int(b["id"])})\n    df = pd.DataFrame(rows)\n    if df.empty:\n        return df\n    return df.sort_values("sinergia (pts)", ascending=False).reset_index(drop=True)\n\n\ndef _logit(p: float) -> float:\n    p = min(max(p, 1e-6), 1 - 1e-6)\n    return math.log(p / (1 - p))\n\n\ndef empirical_synergies(perm_rows: list[dict], item_rows: list[dict], hero_wins: int | None,\n                        hero_matches: int | None, items_by_id: dict[int, dict], min_matches: int = 100,\n                        small: int = 200, reliable: int = 1000) -> pd.DataFrame:\n    if not perm_rows or not item_rows or not hero_matches:\n        return pd.DataFrame()\n    single = {int(r["item_id"]): int(r["wins"]) / int(r["matches"]) for r in item_rows if int(r.get("matches") or 0)}\n    p_hero = (hero_wins or 0) / hero_matches\n    out = []\n    for r in perm_rows:\n        ids = [int(x) for x in (r.get("item_ids") or [])]\n        n = int(r.get("matches") or 0)\n        if len(ids) != 2 or n < min_matches or any(i not in single for i in ids):\n            continue\n        w = int(r.get("wins") or 0)\n        p_obs = w / n\n        z = _logit(single[ids[0]]) + _logit(single[ids[1]]) - _logit(p_hero)\n        p_exp = 1 / (1 + math.exp(-z))\n        out.append({"item A": (items_by_id.get(ids[0]) or {}).get("name", f"#{ids[0]}"),\n                    "item B": (items_by_id.get(ids[1]) or {}).get("name", f"#{ids[1]}"),\n                    "partidas": n, "win rate do par": p_obs, "esperado sem interação": p_exp,\n                    "interação (pp)": (p_obs - p_exp) * 100, "p": binom_pvalue(w, n, p_exp),\n                    "amostra": sample_label(n, small, reliable)})\n    df = pd.DataFrame(out)\n    if df.empty:\n        return df\n    df["q (BH)"] = bh_adjust(df["p"].tolist())\n    df["significativo"] = df["q (BH)"] < 0.05\n    return df.sort_values("interação (pp)", ascending=False).reset_index(drop=True)\n', 'src.optimizer.objective_function': '"""Função objetivo.\n\nScore(build) = Σ_k w_k × ganho relativo_k  (+ w_stats × evidência estatística, opcional)\n\nganho relativo_k = (métrica_k(build) − métrica_k(herói sem itens)) / métrica_k(herói sem itens)\nObjetivos: arma (DPS efetivo), habilidades (índice heurístico H-ABDMG), sobrevivência (EHP misto),\nmobilidade (velocidade). A eficiência económica entra como restrição de orçamento e desempate por custo.\n\nOs pesos NÃO são inventados como verdade: são escolhas do utilizador (estilos pré-definidos, editáveis)\nou calibrados com dados reais (calibrate_weights), sempre mostrados com o método usado.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nimport numpy as np\nfrom scipy.optimize import nnls\n\nfrom .fast_model import OBJECTIVE_METRICS, FastModel\n\nOBJECTIVE_LABELS = {"weapon": "Dano da arma", "ability": "Dano de habilidades", "survival": "Sobrevivência",\n                    "mobility": "Mobilidade", "stats": "Evidência estatística"}\n\nSTYLES: dict[str, dict[str, float]] = {\n    "Arma": {"weapon": 0.55, "ability": 0.10, "survival": 0.35, "mobility": 0.0, "stats": 0.0},\n    "Spirit": {"weapon": 0.10, "ability": 0.55, "survival": 0.35, "mobility": 0.0, "stats": 0.0},\n    "Híbrido": {"weapon": 0.35, "ability": 0.35, "survival": 0.30, "mobility": 0.0, "stats": 0.0},\n    "Tanque": {"weapon": 0.20, "ability": 0.20, "survival": 0.60, "mobility": 0.0, "stats": 0.0},\n}\nCOST_TIEBREAK = 1e-7  # desempate: com score igual, a build mais barata ganha\n\n\ndef normalize(weights: dict[str, float]) -> dict[str, float]:\n    total = sum(max(0.0, v) for v in weights.values())\n    if total <= 0:\n        return {k: (1.0 if k == "weapon" else 0.0) for k in weights}\n    return {k: max(0.0, v) / total for k, v in weights.items()}\n\n\n@dataclass\nclass Objective:\n    model: FastModel\n    weights: dict[str, float]\n    item_evidence: dict[int, float] = field(default_factory=dict)  # Δ WR encolhido (fração) por item_id\n    base: dict[str, float | None] = field(init=False)\n\n    def __post_init__(self) -> None:\n        self.weights = normalize(self.weights)\n        self.base = self.model.metrics([])\n\n    def relative(self, metrics: dict[str, float | None]) -> dict[str, float]:\n        out = {}\n        for k, mkey in OBJECTIVE_METRICS.items():\n            b, v = self.base.get(mkey), metrics.get(mkey)\n            out[k] = (v - b) / abs(b) if (b and v is not None) else 0.0\n        return out\n\n    def score_metrics(self, metrics: dict[str, float | None], items: list[dict[str, Any]]) -> float:\n        rel = self.relative(metrics)\n        s = sum(self.weights.get(k, 0.0) * rel[k] for k in OBJECTIVE_METRICS)\n        if self.weights.get("stats") and self.item_evidence:\n            s += self.weights["stats"] * sum(self.item_evidence.get(int(i["id"]), 0.0) for i in items)\n        return s - COST_TIEBREAK * sum(int(i.get("cost") or 0) for i in items)\n\n    def score(self, items: list[dict[str, Any]]) -> tuple[float, dict[str, float | None]]:\n        m = self.model.metrics(items)\n        return self.score_metrics(m, items), m\n\n\ndef shrunk_evidence(window_rows: list[dict], prior_n: int = 500) -> dict[int, float]:\n    """Δ win rate vs linha de base da janela, encolhido para 0 com amostras pequenas: Δ × n/(n + prior_n)."""\n    tw = sum(int(r.get("wins") or 0) for r in window_rows)\n    tn = sum(int(r.get("matches") or 0) for r in window_rows)\n    if not tn:\n        return {}\n    base = tw / tn\n    out = {}\n    for r in window_rows:\n        n = int(r.get("matches") or 0)\n        if n:\n            out[int(r["item_id"])] = (int(r.get("wins") or 0) / n - base) * n / (n + prior_n)\n    return out\n\n\n@dataclass\nclass Calibration:\n    ok: bool\n    weights: dict[str, float]\n    r2: float | None\n    n_items: int\n    ci: dict[str, tuple[float, float]]\n    message: str\n\n\ndef calibrate_weights(model: FastModel, window_rows: list[dict], items_by_id: dict[int, dict],\n                      min_matches: int = 200, n_boot: int = 200, seed: int = 7) -> Calibration:\n    """Ajusta pesos aos dados: Δ win rate (por janela de compra) ~ ganhos relativos que o motor atribui a cada item.\n\n    Mínimos quadrados não-negativos com intercepto livre; IC dos pesos por bootstrap. É uma associação\n    observacional — serve para escolher pesos defensáveis, não prova causalidade.\n    """\n    base = model.metrics([])\n    tw = sum(int(r.get("wins") or 0) for r in window_rows)\n    tn = sum(int(r.get("matches") or 0) for r in window_rows)\n    keys = ["weapon", "ability", "survival"]\n    xs, ys, ws = [], [], []\n    for r in window_rows:\n        n = int(r.get("matches") or 0)\n        item = items_by_id.get(int(r["item_id"]))\n        if n < min_matches or item is None or not tn:\n            continue\n        m = model.metrics([item])\n        row = []\n        for k in keys:\n            mk = OBJECTIVE_METRICS[k]\n            b, v = base.get(mk), m.get(mk)\n            row.append((v - b) / abs(b) if (b and v is not None) else 0.0)\n        if not any(row):\n            continue\n        xs.append(row)\n        ys.append(int(r.get("wins") or 0) / n - tw / tn)\n        ws.append(np.sqrt(n))\n    if len(xs) < 8:\n        return Calibration(False, {}, None, len(xs), {},\n                           f"Só {len(xs)} itens com amostra ≥ {min_matches} e efeito modelado — dados insuficientes.")\n    X, y, w = np.array(xs), np.array(ys), np.array(ws)\n\n    def fit(Xs, ys_, ws_):\n        A = np.column_stack([Xs * ws_[:, None], ws_])  # última coluna = intercepto (pode ser negativo)\n        coef_pos, _ = nnls(np.column_stack([A[:, :-1], A[:, -1], -A[:, -1]]), ys_ * ws_)\n        return coef_pos[:len(keys)], coef_pos[len(keys)] - coef_pos[len(keys) + 1]\n\n    coef, icpt = fit(X, y, w)\n    pred = X @ coef + icpt\n    ss_res = float(np.sum(w ** 2 * (y - pred) ** 2))\n    ss_tot = float(np.sum(w ** 2 * (y - np.average(y, weights=w ** 2)) ** 2))\n    r2 = 1 - ss_res / ss_tot if ss_tot > 0 else None\n    rng = np.random.default_rng(seed)\n    boots = []\n    for _ in range(n_boot):\n        idx = rng.integers(0, len(y), len(y))\n        c, _ = fit(X[idx], y[idx], w[idx])\n        boots.append(c / c.sum() if c.sum() > 0 else np.zeros_like(c))\n    boots_arr = np.array(boots)\n    ci = {k: (float(np.percentile(boots_arr[:, i], 2.5)), float(np.percentile(boots_arr[:, i], 97.5)))\n          for i, k in enumerate(keys)}\n    if coef.sum() <= 0:\n        return Calibration(False, {}, r2, len(xs), ci, "Nenhum objetivo mostra associação positiva com o win rate.")\n    weights = {k: float(c / coef.sum()) for k, c in zip(keys, coef)}\n    weights.update({"mobility": 0.0, "stats": 0.0})\n    ok = r2 is not None and r2 >= 0.05\n    msg = (f"Ajuste com {len(xs)} itens, R² = {r2:.2f}." if r2 is not None else f"Ajuste com {len(xs)} itens.")\n    if not ok:\n        msg += " Associação fraca: os dados não sustentam bem estes pesos — prefere os teus."\n    return Calibration(ok, weights, r2, len(xs), ci, msg)\n', 'src.optimizer.pareto': '"""Fronteira de Pareto: builds que não são piores em todos os objetivos que outra build."""\n\nfrom __future__ import annotations\n\nimport numpy as np\n\n\ndef pareto_mask(points: np.ndarray) -> np.ndarray:\n    """True para pontos não dominados (maximizar todas as colunas)."""\n    pts = np.asarray(points, dtype=float)\n    n = len(pts)\n    keep = np.ones(n, dtype=bool)\n    for start in range(0, n, 512):\n        block = pts[start:start + 512]\n        ge = (pts[None, :, :] >= block[:, None, :]).all(axis=2)\n        gt = (pts[None, :, :] > block[:, None, :]).any(axis=2)\n        dominated = (ge & gt).any(axis=1)\n        keep[start:start + 512] = ~dominated\n    return keep\n', 'src.optimizer.purchase_order': '"""Ordem de compra.\n\nDado o conjunto final de itens, procura a sequência de compras que dá mais poder mais cedo:\nmaximiza a área sob a curva score × Souls gastas (∫ score ds). Considera comprar componentes antes\ndas melhorias (paga-se a diferença ao melhorar). A sequência recomendada é a melhor de várias\nTESTADAS: greedy por ganho/Soul, melhorias por troca de vizinhos e centenas de ordens aleatórias.\n"""\n\nfrom __future__ import annotations\n\nimport random\nfrom dataclasses import dataclass\nfrom typing import Any\n\nfrom .objective_function import Objective\n\n\n@dataclass\nclass Step:\n    action: str  # "comprar" | "componente" | "melhorar"\n    item: dict[str, Any]\n    replaces: dict[str, Any] | None\n    cost: int\n\n\n@dataclass\nclass OrderResult:\n    steps: list[dict[str, Any]]\n    area: float\n    greedy_area: float\n    random_areas: list[float]\n    tested: int\n    percentile_vs_random: float\n    total_cost: int\n\n\ndef _options(owned: list[dict], targets: list[dict], by_class: dict[str, dict]) -> list[Step]:\n    owned_cls = {o.get("class_name") for o in owned}\n    opts: list[Step] = []\n    for x in targets:\n        if x.get("class_name") in owned_cls:\n            continue\n        comps = [by_class[c] for c in (x.get("component_items") or []) if c in by_class]\n        have = next((c for c in comps if c.get("class_name") in owned_cls), None)\n        if have is not None:\n            opts.append(Step("melhorar", x, have, max(0, int(x.get("cost") or 0) - int(have.get("cost") or 0))))\n            continue\n        opts.append(Step("comprar", x, None, int(x.get("cost") or 0)))\n        for c in comps:\n            if c.get("class_name") not in owned_cls and all(c.get("class_name") != t.get("class_name") for t in targets):\n                opts.append(Step("componente", c, None, int(c.get("cost") or 0)))\n    return opts\n\n\ndef _apply(owned: list[dict], step: Step) -> list[dict]:\n    if step.replaces is not None:\n        return [o for o in owned if o.get("class_name") != step.replaces.get("class_name")] + [step.item]\n    return owned + [step.item]\n\n\ndef simulate(obj: Objective, steps: list[Step]) -> tuple[float, list[float]]:\n    """Área = Σ score_antes_da_compra × custo da compra (poder mantido enquanto se juntam as Souls)."""\n    owned: list[dict] = []\n    s_prev, _ = obj.score([])\n    area, scores = 0.0, []\n    for st in steps:\n        area += s_prev * st.cost\n        owned = _apply(owned, st)\n        s_prev, _ = obj.score(owned)\n        scores.append(s_prev)\n    return area, scores\n\n\ndef _greedy(obj: Objective, targets: list[dict], by_class: dict[str, dict]) -> list[Step]:\n    owned: list[dict] = []\n    seq: list[Step] = []\n    cur, _ = obj.score(owned)\n    while True:\n        opts = _options(owned, targets, by_class)\n        if not opts:\n            return seq\n        best, best_val = None, None\n        for o in opts:\n            s, _ = obj.score(_apply(owned, o))\n            val = (s - cur) / o.cost if o.cost > 0 else float("inf")\n            if best_val is None or val > best_val or (val == best_val and o.cost < best.cost):  # type: ignore[union-attr]\n                best, best_val = o, val\n        owned = _apply(owned, best)  # type: ignore[arg-type]\n        cur, _ = obj.score(owned)\n        seq.append(best)  # type: ignore[arg-type]\n\n\ndef _random_order(targets: list[dict], by_class: dict[str, dict], rng: random.Random) -> list[Step]:\n    owned: list[dict] = []\n    seq: list[Step] = []\n    while True:\n        opts = _options(owned, targets, by_class)\n        if not opts:\n            return seq\n        st = rng.choice(opts)\n        owned = _apply(owned, st)\n        seq.append(st)\n\n\ndef _valid(steps: list[Step], targets: list[dict], by_class: dict[str, dict]) -> bool:\n    owned: list[dict] = []\n    for st in steps:\n        legal = _options(owned, targets, by_class)\n        if not any(o.action == st.action and o.item is st.item for o in legal):\n            return False\n        owned = _apply(owned, st)\n    return True\n\n\ndef _improve(obj: Objective, steps: list[Step], targets, by_class, rounds: int = 6) -> tuple[list[Step], float]:\n    best, best_area = steps, simulate(obj, steps)[0]\n    for _ in range(rounds):\n        improved = False\n        for i in range(len(best) - 1):\n            cand = best[:i] + [best[i + 1], best[i]] + best[i + 2:]\n            if not _valid(cand, targets, by_class):\n                continue\n            a = simulate(obj, cand)[0]\n            if a > best_area + 1e-12:\n                best, best_area, improved = cand, a, True\n        if not improved:\n            break\n    return best, best_area\n\n\ndef phase_of(cum_after: int, early_max: int, mid_max: int) -> str:\n    if cum_after <= early_max:\n        return "Early game"\n    if cum_after <= mid_max:\n        return "Mid game"\n    return "Late game"\n\n\ndef plan_order(obj: Objective, targets: list[dict], shop_by_class: dict[str, dict], early_max: int, mid_max: int,\n               n_random: int = 300, seed: int = 11, buy_times: dict[int, float] | None = None) -> OrderResult:\n    greedy = _greedy(obj, targets, shop_by_class)\n    g_area, _ = simulate(obj, greedy)\n    improved, i_area = _improve(obj, greedy, targets, shop_by_class)\n    rng = random.Random(seed)\n    rand_areas = []\n    best_steps, best_area = improved, i_area\n    for _ in range(n_random):\n        seq = _random_order(targets, shop_by_class, rng)\n        a, _ = simulate(obj, seq)\n        rand_areas.append(a)\n        if a > best_area + 1e-12:\n            best_steps, best_area = seq, a\n    _, scores = simulate(obj, best_steps)\n    base, _ = obj.score([])\n    rows, cum = [], 0\n    for st, sc in zip(best_steps, scores):\n        cum += st.cost\n        row = {"passo": len(rows) + 1, "fase": phase_of(cum, early_max, mid_max), "ação": st.action,\n               "item": st.item.get("name"), "custo do passo": st.cost, "Souls acumuladas": cum,\n               "score após": sc, "ganho do passo": sc - (rows[-1]["score após"] if rows else base)}\n        if st.replaces is not None:\n            row["substitui"] = st.replaces.get("name")\n        if buy_times and int(st.item["id"]) in buy_times:\n            row["minuto médio observado"] = buy_times[int(st.item["id"])]\n        rows.append(row)\n    pct = sum(1 for a in rand_areas if a <= best_area) / len(rand_areas) * 100 if rand_areas else 100.0\n    return OrderResult(rows, best_area, g_area, rand_areas, n_random + 2, pct, cum)\n', 'src.optimizer.report': '"""Relatório final de uma build: tudo o que é preciso para perceber porque foi escolhida."""\n\nfrom __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\n\nfrom ..engine.model import METRIC_LABELS\nfrom ..engine.rules import RULES\nfrom .fast_model import OBJECTIVE_METRICS\nfrom .objective_function import OBJECTIVE_LABELS, Objective\n\n\ndef justify(obj: Objective, items: list[dict]) -> list[dict[str, Any]]:\n    """Para cada item: quanto o score e cada objetivo caem se o item for retirado (leave-one-out)."""\n    full_s, full_m = obj.score(items)\n    full_rel = obj.relative(full_m)\n    rows = []\n    for it in items:\n        rest = [x for x in items if x is not it]\n        s, m = obj.score(rest)\n        rel = obj.relative(m)\n        cost = int(it.get("cost") or 0)\n        row = {"item": it.get("name"), "slot": it.get("item_slot_type"), "custo": cost,\n               "contributo (pts)": (full_s - s) * 100,\n               "pts por 1000 Souls": ((full_s - s) * 100 / cost * 1000) if cost else None,\n               "cobertura": obj.model.vec(it).coverage}\n        for k in ("weapon", "ability", "survival"):\n            row[f"Δ {OBJECTIVE_LABELS[k]} (%)"] = (full_rel[k] - rel[k]) * 100\n        rows.append(row)\n    return sorted(rows, key=lambda r: -r["contributo (pts)"])\n\n\ndef internal_synergies(obj: Objective, items: list[dict], threshold_pts: float = 0.05) -> list[dict[str, Any]]:\n    from .item_synergy import _stats_of, _why\n\n    s0, _ = obj.score([])\n    single = {int(i["id"]): obj.score([i])[0] - s0 for i in items}\n    out = []\n    for i, a in enumerate(items):\n        for b in items[i + 1:]:\n            sab, _ = obj.score([a, b])\n            syn = ((sab - s0) - single[int(a["id"])] - single[int(b["id"])]) * 100\n            if abs(syn) >= threshold_pts:\n                out.append({"itens": f"{a.get(\'name\')} + {b.get(\'name\')}", "sinergia (pts)": syn,\n                            "porquê": _why(_stats_of(obj, a), _stats_of(obj, b))})\n    return sorted(out, key=lambda r: -r["sinergia (pts)"])\n\n\ndef confidence_summary(obj: Objective, items: list[dict], rules_used: list[str],\n                       window_df=None) -> dict[str, Any]:\n    cov = [obj.model.vec(i).coverage for i in items]\n    cov = [c for c in cov if c is not None]\n    hyp = [r for r in set(rules_used) if r in RULES and RULES[r].status == "hipótese"]\n    out = {"cobertura média do modelo": (sum(cov) / len(cov)) if cov else None,\n           "hipóteses usadas": sorted(hyp)}\n    if window_df is not None and not window_df.empty:\n        names = {i.get("name") for i in items}\n        sub = window_df[window_df["item"].isin(names)]\n        out["itens com evidência empírica positiva (q<0,05)"] = int(((sub["Δ vs janela (pp)"] > 0) & sub["significativo"]).sum())\n        out["itens com evidência empírica negativa (q<0,05)"] = int(((sub["Δ vs janela (pp)"] < 0) & sub["significativo"]).sum())\n        out["itens sem dados suficientes"] = int(len(names) - len(sub))\n    return out\n\n\ndef markdown(report: dict[str, Any]) -> str:\n    L = [f"# Build — {report[\'hero\']}", "",\n         f"- Gerada: {report[\'created\']}  ·  versão do jogo: {report[\'version\']}",\n         f"- Ranking/modo das estatísticas: {report[\'filters\']}",\n         f"- Estilo / pesos: {report[\'weights_text\']}",\n         f"- Orçamento: {report[\'budget\']:,} Souls · custo: {report[\'cost\']:,} Souls".replace(",", " "),\n         f"- Cenário: {report[\'scenario\']}", "", "## Itens", ""]\n    for r in report["justification"]:\n        L.append(f"- **{r[\'item\']}** ({r[\'slot\']}, {r[\'custo\']}) — contributo {r[\'contributo (pts)\']:.2f} pts"\n                 + (f", {r[\'pts por 1000 Souls\']:.2f} pts/1000 Souls" if r.get("pts por 1000 Souls") else ""))\n    L += ["", "## Ordem de compra", ""]\n    for s in report["order"]:\n        extra = f" (substitui {s[\'substitui\']})" if s.get("substitui") else ""\n        L.append(f"{s[\'passo\']}. [{s[\'fase\']}] {s[\'ação\']} **{s[\'item\']}**{extra} — {s[\'custo do passo\']} Souls "\n                 f"(total {s[\'Souls acumuladas\']})")\n    L += ["", "## Métricas estimadas (motor)", ""]\n    for k, v in report["metrics"].items():\n        if k in METRIC_LABELS and v is not None:\n            L.append(f"- {METRIC_LABELS[k]}: {v:.2f}")\n    if report.get("synergies"):\n        L += ["", "## Sinergias na build", ""]\n        L += [f"- {s[\'itens\']}: {s[\'sinergia (pts)\']:+.2f} pts — {s[\'porquê\']}" for s in report["synergies"]]\n    if report.get("alternatives"):\n        L += ["", "## Alternativas", ""]\n        L += [f"- {a}" for a in report["alternatives"]]\n    L += ["", "## Confiança", ""]\n    for k, v in report["confidence"].items():\n        L.append(f"- {k}: {v}")\n    L += ["", "## Regras e hipóteses", ""]\n    L += [f"- {r} — {RULES[r].name} ({RULES[r].status})" for r in sorted(set(report["rules"])) if r in RULES]\n    L += ["", "_Estimativas do motor com as hipóteses acima; não são medições dentro do jogo._"]\n    return "\\n".join(L)\n\n\ndef now() -> str:\n    return datetime.now().strftime("%d/%m/%Y %H:%M")\n\n\n__all__ = ["justify", "internal_synergies", "confidence_summary", "markdown", "now", "OBJECTIVE_METRICS"]\n', 'src.optimizer.sensitivity': '"""Análise de sensibilidade: quão estável é a build quando os pesos mudam um pouco.\n\nPerturba os pesos com uma distribuição de Dirichlet centrada nos pesos escolhidos e volta a otimizar.\nUm item que aparece em quase todas as builds resultantes é uma escolha robusta; um que só aparece com\nos pesos exatos depende dessa escolha.\n"""\n\nfrom __future__ import annotations\n\nfrom collections import Counter\nfrom dataclasses import dataclass\nfrom typing import Callable\n\nimport numpy as np\n\n\n@dataclass\nclass SensitivityResult:\n    runs: int\n    frequency: dict[int, float]   # item_id -> fração das execuções em que aparece\n    jaccard: list[float]          # semelhança de cada execução com a build principal\n    weights: list[dict[str, float]]\n\n\ndef weight_sensitivity(base_weights: dict[str, float], run: Callable[[dict[str, float]], frozenset[int] | None],\n                       main_ids: frozenset[int], runs: int = 10, concentration: float = 30.0,\n                       seed: int = 3) -> SensitivityResult:\n    rng = np.random.default_rng(seed)\n    keys = [k for k, v in base_weights.items() if v > 0]\n    alpha = np.array([max(1e-3, base_weights[k]) * concentration for k in keys])\n    counter: Counter = Counter()\n    jac, used = [], []\n    done = 0\n    for _ in range(runs):\n        draw = rng.dirichlet(alpha)\n        w = {k: 0.0 for k in base_weights}\n        w.update({k: float(x) for k, x in zip(keys, draw)})\n        ids = run(w)\n        if ids is None:\n            continue\n        done += 1\n        used.append(w)\n        counter.update(ids)\n        union = ids | main_ids\n        jac.append(len(ids & main_ids) / len(union) if union else 1.0)\n    freq = {i: c / done for i, c in counter.items()} if done else {}\n    return SensitivityResult(done, freq, jac, used)\n', 'src.ui': '"""Interface Streamlit."""\n', 'src.ui.components': '"""Pequenos componentes visuais reutilizáveis."""\n\nfrom __future__ import annotations\n\nimport html\nimport math\nimport re\nfrom typing import Any\n\nimport pandas as pd\nimport streamlit as st\n\nUNKNOWN = "desconhecido"\nMOBILE_UA = re.compile(r"Mobi|Android|iPhone|iPad|iPod", re.I)\n\n\ndef is_compact() -> bool:\n    """Modo compacto (telemóvel): detetado pelo User-Agent na 1.ª visita; o utilizador pode mudá-lo na barra lateral."""\n    if "compact_mode" not in st.session_state:\n        ua = ""\n        try:\n            ua = st.context.headers.get("User-Agent", "") or ""\n        except Exception:  # noqa: BLE001 — sem contexto HTTP (ex.: testes)\n            ua = ""\n        st.session_state["compact_mode"] = bool(MOBILE_UA.search(ua))\n    return bool(st.session_state["compact_mode"])\n\n\ndef _card_html(label: str, value: Any, sub: str | None) -> str:\n    sub_html = f\'<div class="dbl-kpi-sub">{html.escape(sub)}</div>\' if sub else ""\n    return (f\'<div class="dbl-card"><div class="dbl-kpi-label">{html.escape(label)}</div>\'\n            f\'<div class="dbl-kpi-value">{html.escape(str(value))}</div>{sub_html}</div>\')\n\n\ndef kpi_grid(cards: list[tuple[str, Any, str | None]]) -> None:\n    """Grelha de cartões: várias por linha no PC, 2 por linha no telemóvel."""\n    st.markdown(\'<div class="dbl-kpi-grid">\' + "".join(_card_html(*c) for c in cards) + "</div>",\n                unsafe_allow_html=True)\n\n\ndef kpi(label: str, value: Any, sub: str | None = None) -> None:\n    st.markdown(_card_html(label, value, sub), unsafe_allow_html=True)\n\n\ndef note(text: str, warn: bool = False) -> None:\n    cls = "dbl-note dbl-warn" if warn else "dbl-note"\n    st.markdown(f\'<div class="{cls}">{text}</div>\', unsafe_allow_html=True)\n\n\ndef pills(values: list[str]) -> None:\n    if values:\n        st.markdown("".join(f\'<span class="dbl-pill">{html.escape(v)}</span>\' for v in values),\n                    unsafe_allow_html=True)\n\n\ndef source(url: str | None, fetched_at: str | None, version: str | None) -> None:\n    from .context import fmt_dt\n    st.caption(f"Fonte: `{url or UNKNOWN}` · recolhido {fmt_dt(fetched_at)} · versão do jogo {version or UNKNOWN}")\n\n\ndef pct(x: Any, digits: int = 1) -> str:\n    if x is None or (isinstance(x, float) and math.isnan(x)):\n        return UNKNOWN\n    return f"{x * 100:.{digits}f}%"\n\n\ndef num(x: Any, digits: int = 2) -> str:\n    if x is None or (isinstance(x, float) and math.isnan(x)):\n        return UNKNOWN\n    if isinstance(x, bool):\n        return "sim" if x else "não"\n    if isinstance(x, int):\n        return f"{x:,}".replace(",", " ")\n    if isinstance(x, float):\n        s = f"{x:.{digits}f}"\n        return s.rstrip("0").rstrip(".") if "." in s else s\n    return str(x)\n\n\ndef _arrow_safe(df: pd.DataFrame) -> pd.DataFrame:\n    """Colunas com texto e números misturados passam a texto (o Arrow não aceita tipos mistos)."""\n    out = df\n    for col in df.columns:\n        if df[col].dtype != object:\n            continue\n        vals = [v for v in df[col].tolist() if v is not None and not (isinstance(v, float) and math.isnan(v))]\n        has_str = any(isinstance(v, str) for v in vals)\n        has_other = any(not isinstance(v, str) for v in vals)\n        if has_str and has_other:\n            if out is df:\n                out = df.copy()\n            out[col] = [None if v is None or (isinstance(v, float) and math.isnan(v)) else\n                        (num(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else str(v))\n                        for v in df[col].tolist()]\n    return out\n\n\ndef table(rows: list[dict] | pd.DataFrame, compact: list[str] | None = None,\n          rename: dict[str, str] | None = None, **kwargs: Any) -> None:\n    """Tabela. Em modo compacto mostra só as colunas `compact` (e renomeia-as com `rename`)."""\n    df = rows if isinstance(rows, pd.DataFrame) else pd.DataFrame(rows)\n    if df.empty:\n        st.caption("Sem dados.")\n        return\n    hidden = 0\n    if compact and is_compact():\n        cols = [col for col in compact if col in df.columns]\n        if cols:\n            hidden = len(df.columns) - len(cols)\n            df = df[cols]\n            if rename:\n                df = df.rename(columns=rename)\n                cfg = kwargs.get("column_config")\n                if cfg:\n                    kwargs["column_config"] = {rename.get(k, k): v for k, v in cfg.items()}\n    if "column_config" in kwargs and kwargs["column_config"]:\n        kwargs["column_config"] = {k: v for k, v in kwargs["column_config"].items() if k in df.columns}\n    st.dataframe(_arrow_safe(df), hide_index=True, width="stretch", **kwargs)\n    if hidden:\n        what = "1 coluna oculta" if hidden == 1 else f"{hidden} colunas ocultas"\n        st.caption(f"Modo compacto: {what} (desliga-o na barra lateral para ver tudo).")\n\n\ndef percent_columns(df: pd.DataFrame, cols: list[str]) -> pd.DataFrame:\n    out = df.copy()\n    for c in cols:\n        if c in out:\n            out[c] = out[c].astype(float) * 100\n    return out\n\n\ndef pct_config(cols: list[str]) -> dict[str, Any]:\n    return {c: st.column_config.NumberColumn(c, format="%.1f%%") for c in cols}\n\n\ndef no_data(message: str = "Ainda não há dados guardados.") -> None:\n    st.info(message + " Usa **Atualizar dados** na barra lateral (precisa de Internet na primeira vez).")\n\n\ndef image(src: str | None, width: Any = None) -> None:\n    """Mostra uma imagem; se o ficheiro/URL estiver inválido, não rebenta a página."""\n    if not src:\n        return\n    try:\n        if width is None:\n            st.image(src)\n        else:\n            st.image(src, width=width)\n    except Exception:  # noqa: BLE001 — imagem corrompida/ilegível não deve parar a UI\n        st.caption("(imagem indisponível)")\n', 'src.ui.context': '"""Contexto partilhado da UI: configuração, base de dados, collector e leituras em cache."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any\n\nimport streamlit as st\n\nfrom ..api.analytics_api import StatsFilters\nfrom ..config import load_config\nfrom ..data.collector import Collector\nfrom ..data.database import Database\nfrom ..data.normalizer import find_hero, index_by_class, index_by_id\n\n\n@dataclass\nclass AppContext:\n    cfg: dict[str, Any]\n    collector: Collector\n\n    @property\n    def db(self) -> Database:\n        return self.collector.db\n\n    @property\n    def version(self) -> str | None:\n        return self.collector.active_version\n\n    @property\n    def rev(self) -> str:\n        """Chave de invalidação das caches de leitura (muda a cada atualização)."""\n        rep = self.db.get_kv("last_update_report") or {}\n        return f"{self.version}|{rep.get(\'finished_at\')}"\n\n    def default_filters(self, match_mode: str) -> StatsFilters:\n        st_cfg = self.cfg["statistics"]\n        return StatsFilters(game_mode=st_cfg["game_mode"], match_mode=match_mode,\n                            min_matches=st_cfg["min_matches_query"])\n\n\n@st.cache_resource(show_spinner=False)\ndef get_ctx() -> AppContext:\n    cfg = load_config()\n    return AppContext(cfg, Collector.from_config(cfg))\n\n\n@st.cache_data(show_spinner=False, max_entries=8)\ndef load_heroes(db_path: str, version: str, rev: str) -> list[dict]:\n    return Database(db_path).heroes(version)\n\n\n@st.cache_data(show_spinner=False, max_entries=8)\ndef load_items(db_path: str, version: str, rev: str) -> list[dict]:\n    return Database(db_path).items(version)\n\n\ndef heroes(ctx: AppContext) -> list[dict]:\n    return load_heroes(str(ctx.db.path), ctx.version, ctx.rev) if ctx.version else []\n\n\ndef items(ctx: AppContext) -> list[dict]:\n    return load_items(str(ctx.db.path), ctx.version, ctx.rev) if ctx.version else []\n\n\ndef items_by_class(ctx: AppContext) -> dict[str, dict]:\n    return index_by_class(items(ctx))\n\n\ndef items_by_id(ctx: AppContext) -> dict[int, dict]:\n    return index_by_id(items(ctx))\n\n\ndef heroes_by_id(ctx: AppContext) -> dict[int, dict]:\n    return index_by_id(heroes(ctx))\n\n\ndef hero_names(ctx: AppContext, include_all: bool) -> list[str]:\n    hs = heroes(ctx)\n    initial = [n for n in ctx.cfg["heroes"]["initial"] if find_hero(hs, n)]\n    if not include_all:\n        return initial\n    others = sorted(h["name"] for h in hs if h.get("player_selectable", True) and not h.get("disabled")\n                    and not h.get("in_development") and h["name"] not in initial)\n    return initial + others\n\n\ndef hero_image(ctx: AppContext, hero: dict) -> str | None:\n    img_dir = Path(ctx.collector.base_dir) / "cache" / "images"\n    for p in img_dir.glob(f"hero_{hero[\'id\']}.*"):\n        return str(p)\n    imgs = hero.get("images") or {}\n    return imgs.get("icon_hero_card") or imgs.get("icon_image_small")\n\n\ndef fmt_dt(iso: str | None) -> str:\n    if not iso:\n        return "nunca"\n    try:\n        return datetime.fromisoformat(iso).astimezone().strftime("%d/%m/%Y %H:%M")\n    except ValueError:\n        return iso\n', 'src.ui.engine_ui': '"""Componentes de UI partilhados pelo motor: seletor de itens, cenário, tabelas de métricas."""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nimport pandas as pd\nimport streamlit as st\n\nfrom ..data.normalizer import find_hero, hero_abilities, shop_items\nfrom ..engine.build import Build, Scenario\nfrom ..engine.model import METRIC_LABELS, Evaluation, Evaluator\nfrom ..engine.rules import RULES\nfrom ..models.item import SLOT_LABELS_PT\nfrom . import context as C\nfrom .components import is_compact\n\nRULES_COMPACT = ["regra", "nome", "estado"]\nMETRIC_SHORT = {\n    "weapon_dps_effective": "DPS efetivo", "weapon_dps_sustained": "DPS sustentado", "weapon_dps": "DPS contínuo",\n    "magazine_damage": "Dano/carregador", "ehp_bullet": "EHP balas", "ehp_spirit": "EHP Spirit",\n    "ehp_mixed": "EHP misto", "health": "Vida", "spirit_power": "Spirit Power", "ability_cdr": "CDR",\n    "ability_damage_index": "Índice hab./s", "ability_burst_index": "Burst hab.",\n}\n\nKEY_METRICS = ["weapon_dps_effective", "weapon_dps_sustained", "ehp_bullet", "ehp_spirit", "ehp_mixed",\n               "spirit_power", "ability_cdr", "ability_damage_index"]\nPERCENT_METRICS = {"ability_cdr"}\n\n\ndef evaluator(ctx: C.AppContext) -> Evaluator:\n    eng = ctx.cfg.get("engine", {})\n    return Evaluator(C.items_by_class(ctx), ctx.cfg["ability_property_keys"],\n                     no_crit_heroes=eng.get("no_crit_heroes", []),\n                     apply_indeterminate=bool(eng.get("apply_indeterminate", False)))\n\n\ndef shop_list(ctx: C.AppContext) -> list[dict]:\n    order = {"weapon": 0, "vitality": 1, "spirit": 2}\n    return sorted(shop_items(C.items(ctx)),\n                  key=lambda i: (order.get(i.get("item_slot_type"), 9), i.get("cost") or 0, i.get("name") or ""))\n\n\ndef item_label(it: dict) -> str:\n    slot = SLOT_LABELS_PT.get(it.get("item_slot_type"), it.get("item_slot_type") or "?")\n    act = " · ativo" if it.get("is_active_item") else ""\n    return f"{it.get(\'name\')} · {slot} {it.get(\'cost\') or \'?\'}{act}"\n\n\ndef item_picker(ctx: C.AppContext, key: str, label: str = "Itens", default_ids: list[int] | None = None) -> list[dict]:\n    items = shop_list(ctx)\n    by_id = {i["id"]: i for i in items}\n    chosen = st.multiselect(label, list(by_id), default=[i for i in (default_ids or []) if i in by_id],\n                            format_func=lambda i: item_label(by_id[i]), key=key, max_selections=16)\n    return [by_id[i] for i in chosen]\n\n\ndef hero_picker(ctx: C.AppContext, key: str) -> dict | None:\n    names = C.hero_names(ctx, True)\n    if not names:\n        return None\n    return find_hero(C.heroes(ctx), st.selectbox("Herói", names, key=key))\n\n\ndef ability_tiers(ctx: C.AppContext, hero: dict, key: str) -> dict[str, int]:\n    abil = [a for a in hero_abilities(hero, C.items_by_class(ctx), ctx.cfg["ability_property_keys"])\n            if not a.get("missing")]\n    if not abil:\n        return {}\n    tiers = {}\n\n    def pick(a: dict) -> None:\n        tiers[a["slot"]] = st.selectbox(a["name"], [0, 1, 2, 3], key=f"{key}_{hero[\'id\']}_{a[\'slot\']}",\n                                        format_func=lambda t: "sem melhoria" if t == 0 else f"até T{t}")\n\n    if is_compact():  # no telemóvel: recolhido para não ocupar meio ecrã\n        with st.expander("Melhorias de habilidade", expanded=False):\n            for a in abil:\n                pick(a)\n    else:\n        st.caption("Melhorias de habilidade (pontos de habilidade gastos):")\n        for col, a in zip(st.columns(len(abil)), abil):\n            with col:\n                pick(a)\n    return tiers\n\n\ndef scenario_form(ctx: C.AppContext) -> Scenario:\n    """Cenário partilhado por todas as páginas (as chaves vivem em st.session_state)."""\n    d = ctx.cfg.get("engine", {}).get("default_scenario", {})\n    with st.expander("Cenário de combate — parâmetros escolhidos por ti (não vêm dos dados)", expanded=False):\n        c1, c2, c3, c4 = st.columns(4)\n        with c1:\n            tbr = st.slider("Resist. a balas do alvo (%)", 0, 80, int(d.get("target_bullet_resist", 0)), key="sc_tbr")\n            tsr = st.slider("Resist. Spirit do alvo (%)", 0, 80, int(d.get("target_spirit_resist", 0)), key="sc_tsr")\n        with c2:\n            shb = st.slider("Shred de balas aplicado (%)", 0, 50, 0, key="sc_shb")\n            shs = st.slider("Shred Spirit aplicado (%)", 0, 50, 0, key="sc_shs")\n        with c3:\n            dist = st.number_input("Distância ao alvo (m, 0 = sem queda)", 0.0, 100.0,\n                                   float(d.get("distance_m", 0)), step=1.0, key="sc_dist")\n            hs = st.slider("Headshots (%)", 0, 100, int(d.get("headshot_rate", 0)), key="sc_hs")\n        with c4:\n            inc = st.slider("Dano recebido que é de balas (%)", 0, 100, int(d.get("incoming_bullet_share", 50)),\n                            key="sc_inc")\n            flex = st.slider("Slots flex desbloqueados", 0, 4, int(d.get("flex_slots", 4)), key="sc_flex")\n        dur = st.select_slider("Duração do combate (s)", [5, 10, 20, 30, 60], value=int(d.get("combat_s", 10)),\n                               key="sc_dur")\n    return Scenario(target_bullet_resist=tbr / 100, target_spirit_resist=tsr / 100, shred_bullet=shb / 100,\n                    shred_spirit=shs / 100, distance_m=dist or None, headshot_rate=hs / 100,\n                    incoming_bullet_share=inc / 100, flex_slots=flex, combat_s=float(dur))\n\n\ndef fmt_metric(key: str, value: Any) -> str:\n    if value is None:\n        return "desconhecido"\n    if key in PERCENT_METRICS:\n        return f"{value * 100:.1f}%"\n    return f"{value:,.1f}".replace(",", " ")\n\n\ndef metrics_table(evals: list[tuple[str, Evaluation]], base_index: int = 0) -> pd.DataFrame:\n    rows = []\n    labels = METRIC_SHORT if is_compact() else METRIC_LABELS\n    for key in METRIC_LABELS:\n        row: dict[str, Any] = {"métrica": labels[key]}\n        base_val = evals[base_index][1].metrics.get(key) if evals else None\n        for i, (name, ev) in enumerate(evals):\n            val = ev.metrics.get(key)\n            row[name] = fmt_metric(key, val)\n            if i != base_index:\n                row[f"{name} vs {evals[base_index][0]}"] = (\n                    f"{(val - base_val) / abs(base_val) * 100:+.1f}%" if (val is not None and base_val) else "—")\n        rows.append(row)\n    rows.append({"métrica": "Custo (Souls)", **{name: f"{ev.build.cost:,}".replace(",", " ") for name, ev in evals}})\n    return pd.DataFrame(rows)\n\n\ndef rules_table(rule_ids: list[str]) -> pd.DataFrame:\n    return pd.DataFrame([{"regra": r, "nome": RULES[r].name, "estado": RULES[r].status, "fórmula": RULES[r].formula,\n                          "fonte": RULES[r].source} for r in sorted(set(rule_ids)) if r in RULES])\n\n\ndef effects_tables(ev: Evaluation) -> tuple[pd.DataFrame, pd.DataFrame]:\n    applied = pd.DataFrame([{"item": e.item, "propriedade": e.prop, "valor nos dados": e.raw,\n                             "atributo": e.stat_label, "identificado por": e.how, "regra": e.rule}\n                            for e in ev.applied])\n    reason = {"condicional": "condicional/ativo (H-INNATE)", "indeterminado": "secção desconhecida (H-INNATE)",\n              "inato": "inato mas não mapeado"}\n    out = pd.DataFrame([{"item": e.item, "propriedade": e.prop, "valor nos dados": e.raw,\n                         "motivo": reason[e.kind] if e.stat else f"não mapeado — {e.how}"}\n                        for e in ev.not_applied])\n    return applied, out\n\n\ndef make_build(hero: dict, items: list[dict], tiers: dict[str, int] | None = None, name: str = "Build") -> Build:\n    return Build(hero, items, tiers or {}, name)\n', 'src.ui.pages': '"""Páginas da aplicação (uma função `render()` por página)."""\n', 'src.ui.pages.comparator': '"""Comparador de builds: métricas do motor (Fase 3) + estatísticas observadas por item."""\n\nfrom __future__ import annotations\n\nimport pandas as pd\nimport plotly.graph_objects as go\nimport streamlit as st\n\nfrom ...models.item import SLOT_LABELS_PT\nfrom .. import context as C\nfrom .. import engine_ui as E\nfrom ..components import no_data, note, table\nfrom ..theme import SLOT_COLORS, show_chart\n\nMAX_BUILDS = 4\nCHART_METRICS = ["weapon_dps_effective", "ehp_bullet", "ehp_spirit", "spirit_power", "ability_damage_index"]\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Comparador de Builds")\n    if not ctx.version:\n        no_data()\n        return\n    hero = E.hero_picker(ctx, "cmp_hero")\n    if not hero:\n        return\n    n = st.number_input("Número de builds", 2, MAX_BUILDS, 2)\n    cols = st.columns(int(n))\n    builds = []\n    for i, col in enumerate(cols):\n        with col:\n            label = st.text_input("Nome", f"Build {chr(65 + i)}", key=f"cmp_name_{i}")\n            items = E.item_picker(ctx, f"cmp_items_{i}", "Itens")\n            builds.append(E.make_build(hero, items, {}, label))\n    sc = E.scenario_form(ctx)\n\n    if not any(b.items for b in builds):\n        st.caption("Escolhe itens para comparar.")\n        return\n\n    ev = E.evaluator(ctx)\n    evals = [(b.name, ev.evaluate(b, sc)) for b in builds]\n    for name, e in evals:\n        for issue in e.issues:\n            st.warning(f"{name}: {issue}")\n\n    st.subheader("Métricas calculadas pelo motor")\n    table(E.metrics_table(evals), compact=["métrica"] + [name for name, _ in evals])\n    st.caption("Diferenças percentuais face à primeira build. Melhorias de habilidade: nenhuma (iguais para todas).")\n\n    fig = go.Figure()\n    for name, e in evals:\n        vals = []\n        for m in CHART_METRICS:\n            base = evals[0][1].metrics.get(m)\n            v = e.metrics.get(m)\n            vals.append((v / base * 100) if (v is not None and base) else None)\n        fig.add_trace(go.Bar(x=[E.METRIC_LABELS[m] for m in CHART_METRICS], y=vals, name=name))\n    fig.add_hline(y=100, line_dash="dot")\n    fig.update_layout(barmode="group", title=f"Índice relativo ({evals[0][0]} = 100)", yaxis_title="índice")\n    show_chart(fig, 400)\n\n    st.subheader("Economia")\n    eco = []\n    for name, e in evals:\n        inv = e.build.invested()\n        row = {"build": name, "custo total": e.build.cost,\n               **{f"Souls {SLOT_LABELS_PT[s]}": v for s, v in inv.items()}}\n        for m in ("weapon_dps_effective", "ehp_mixed"):\n            v = e.metrics.get(m)\n            row[f"{E.METRIC_LABELS[m]} por 1000 Souls"] = (v / e.build.cost * 1000) if (v and e.build.cost) else None\n        eco.append(row)\n    table(eco, compact=["build", "custo total", f"{E.METRIC_LABELS[\'weapon_dps_effective\']} por 1000 Souls"],\n          rename={f"{E.METRIC_LABELS[\'weapon_dps_effective\']} por 1000 Souls": "DPS por 1000 Souls"})\n    psd = pd.DataFrame([{"build": name, "slot": SLOT_LABELS_PT[s], "souls": v}\n                        for name, e in evals for s, v in e.build.invested().items()])\n    fig2 = go.Figure()\n    for slot, g in psd.groupby("slot"):\n        fig2.add_trace(go.Bar(x=g["build"], y=g["souls"], name=slot, marker_color=SLOT_COLORS.get(slot)))\n    fig2.update_layout(barmode="stack", title="Souls investidas por slot", yaxis_title="Souls")\n    show_chart(fig2, 320)\n\n    st.subheader("Hipóteses usadas")\n    table(E.rules_table([r for _, e in evals for r in e.rules_used]), compact=E.RULES_COMPACT)\n\n    st.subheader("Estatística observada de cada item (isolado)")\n    mode = st.radio("Modo", ["Ranked", "Normal / Unranked"], horizontal=True, key="cmp_mode")\n    stored = ctx.db.latest_stats("item-stats",\n                                 ctx.default_filters("ranked" if mode == "Ranked" else "unranked").key(), hero["id"])\n    obs = {r["item_id"]: r for r in (stored or {}).get("rows", [])}\n    rows = []\n    for b in builds:\n        for it in b.items:\n            r = obs.get(it["id"])\n            rows.append({"build": b.name, "item": it["name"], "custo": it.get("cost"),\n                         "partidas com item": r["matches"] if r else None,\n                         "win rate (%)": round(r["wins"] / r["matches"] * 100, 1) if r and r["matches"] else None})\n    table(rows, compact=["build", "item", "win rate (%)"])\n    note("Win rates de itens isolados não se somam numa \'win rate da build\' e estão enviesados pelo momento de "\n         "compra. A estatística da combinação (item-permutation-stats) entra na Fase 4.")\n', 'src.ui.pages.dashboard': 'from __future__ import annotations\n\nimport pandas as pd\nimport streamlit as st\n\nfrom ...analytics.confidence import wilson_interval\nfrom ...data.normalizer import find_hero\nfrom .. import context as C\nfrom ..components import image, kpi_grid, no_data, note, pct, table\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Dashboard")\n    version = ctx.version\n    if not version:\n        no_data()\n        _report(ctx)\n        return\n\n    info = ctx.db.get_kv("active_version_info") or {}\n    counts = ctx.db.counts(version)\n    sub = f"Steam: {info.get(\'steam_client_version\') or \'—\'} · {info.get(\'version_datetime\') or \'\'}"\n    kpi_grid([\n        ("Última atualização", C.fmt_dt(ctx.db.get_kv("last_success_at")), None),\n        ("Versão do jogo", version, sub),\n        ("Heróis", counts["heroes"], "jogáveis nesta versão"),\n        ("Itens de loja", counts["shop_items"], f"{counts[\'all_items\']} entradas no total"),\n        ("Builds guardadas", ctx.db.saved_build_count(), "Otimizador → Otimizar"),\n    ])\n\n    errors = ctx.db.get_kv("error_log", []) or []\n    if errors:\n        st.warning(f"{len(errors)} erro(s) registado(s) recentemente — ver Configurações › Diagnóstico rápido.")\n\n    st.subheader("Estado das APIs")\n    status = ctx.db.get_kv("api_status") or {}\n    cols = st.columns(3)\n    with cols[0]:\n        if not status:\n            st.caption("Ainda não verificado.")\n        elif not status.get("reachable"):\n            st.error(f"Deadlock API inacessível ({C.fmt_dt(status.get(\'at\'))}). A usar dados guardados.")\n        else:\n            services = status.get("services") or {}\n            down = [k for k, v in services.items() if v is False]\n            if down:\n                st.warning(f"Deadlock API acessível, serviços em baixo: {\', \'.join(down)}")\n            else:\n                st.success(f"Deadlock API OK ({C.fmt_dt(status.get(\'at\'))})")\n    rep = ctx.db.get_kv("last_update_report") or {}\n    sec = [s for s in rep.get("steps", []) if s["name"].startswith("Fonte secundária")]\n    with cols[1]:\n        if not sec:\n            st.caption("Fonte secundária: sem informação.")\n        elif all(s["ok"] for s in sec):\n            st.success("Deadlock Data API OK")\n        else:\n            st.warning("Deadlock Data API com falhas (ver relatório)")\n    with cols[2]:\n        if rep:\n            st.caption(f"Última tentativa: {C.fmt_dt(rep.get(\'finished_at\'))} — "\n                       f"{\'concluída\' if rep.get(\'ok\') else \'com falhas\'}")\n\n    st.subheader("Heróis iniciais")\n    _initial_heroes(ctx)\n\n    st.subheader("Alterações recentes")\n    diffs = ctx.db.patch_diffs(to_version=version, limit=200)\n    if diffs:\n        st.caption(f"{len(diffs)} alterações detetadas na versão {version} face à anterior.")\n        table(pd.DataFrame(diffs)[["entity_type", "entity_name", "change", "field", "old_value", "new_value"]]\n              .rename(columns={"entity_type": "tipo", "entity_name": "nome", "change": "alteração",\n                               "field": "campo", "old_value": "antes", "new_value": "depois"}).head(50),\n              compact=["nome", "campo", "antes", "depois"])\n    else:\n        st.caption("Sem diferenças registadas (é preciso ter pelo menos duas versões guardadas).")\n    notes = ctx.db.patch_notes(limit=5)\n    if notes:\n        st.markdown("**Notas de patch oficiais**")\n        for n in notes:\n            st.markdown(f"- [{n[\'title\']}]({n[\'link\']}) — {n[\'pub_date\']}")\n\n    _report(ctx)\n\n\ndef _initial_heroes(ctx: C.AppContext) -> None:\n    hs = C.heroes(ctx)\n    stored = ctx.db.latest_stats("hero-stats", ctx.default_filters("ranked").key())\n    rows = {r["hero_id"]: r for r in (stored or {}).get("rows", [])}\n    names = ctx.cfg["heroes"]["initial"]\n    cols = st.columns(max(1, len(names)))\n    for col, name in zip(cols, names):\n        with col:\n            hero = find_hero(hs, name)\n            if not hero:\n                st.warning(f"{name}: não encontrado nos dados")\n                continue\n            img = C.hero_image(ctx, hero)\n            if img:\n                image(img, width=120)\n            st.markdown(f"### {hero[\'name\']}")\n            r = rows.get(hero["id"])\n            if r:\n                lo, hi = wilson_interval(r["wins"], r["matches"], ctx.cfg["statistics"]["confidence_level"])\n                st.markdown(f"Win rate Ranked: **{pct(r[\'wins\'] / r[\'matches\'])}** "\n                            f"(IC 95%: {pct(lo)}–{pct(hi)}, n={r[\'matches\']:,})".replace(",", " "))\n            else:\n                st.caption("Sem estatísticas guardadas.")\n\n\ndef _report(ctx: C.AppContext) -> None:\n    rep = ctx.db.get_kv("last_update_report")\n    if not rep:\n        return\n    with st.expander("Relatório da última atualização"):\n        if not rep.get("online", True):\n            note("Sem ligação: os dados apresentados são os últimos guardados.", warn=True)\n        table([{"passo": s["name"], "ok": s["ok"], "mensagem": s["message"],\n                "alterou dados": s.get("changed"), "cache antiga": s.get("stale")} for s in rep["steps"]],\n              compact=["passo", "ok", "mensagem"])\n        warnings = [w for s in rep["steps"] for w in s.get("warnings", [])]\n        if warnings:\n            st.markdown("**Avisos de validação**")\n            st.code("\\n".join(warnings[:100]))\n', 'src.ui.pages.heroes': 'from __future__ import annotations\n\nimport pandas as pd\nimport streamlit as st\n\nfrom ...analytics.confidence import wilson_interval\nfrom ...analytics.item_stats import item_stats_frame\nfrom ...api.http_client import ApiError\nfrom ...data.normalizer import (find_hero, hero_abilities, hero_base_stats, hero_data_completeness,\n                                hero_level_gains, hero_weapon)\nfrom .. import context as C\nfrom ..components import UNKNOWN, image, kpi, kpi_grid, no_data, note, num, pct, pct_config, percent_columns, pills, source, table\n\nMODE_LABELS = {"Ranked": "ranked", "Normal / Unranked": "unranked"}\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Heróis")\n    if not ctx.version:\n        no_data()\n        return\n\n    show_all = st.toggle("Mostrar todos os heróis (dados base já disponíveis para todos)", value=False)\n    names = C.hero_names(ctx, show_all)\n    if not names:\n        st.warning("Nenhum dos heróis configurados foi encontrado nos dados.")\n        return\n    name = st.selectbox("Herói", names)\n    hero = find_hero(C.heroes(ctx), name)\n    by_class = C.items_by_class(ctx)\n    weapon = hero_weapon(hero, by_class)\n    abilities = hero_abilities(hero, by_class, ctx.cfg["ability_property_keys"])\n\n    left, right = st.columns([1, 4])\n    with left:\n        img = C.hero_image(ctx, hero)\n        if img:\n            image(img, width="stretch")\n    with right:\n        st.markdown(f"## {hero[\'name\']}")\n        desc = hero.get("description") or {}\n        if desc.get("role"):\n            st.markdown(f"**Papel:** {desc[\'role\']}")\n        if desc.get("playstyle"):\n            st.markdown(desc["playstyle"])\n        pills([str(t) for t in hero.get("tags") or []] + ([f"tipo: {hero[\'hero_type\']}"] if hero.get("hero_type") else []))\n        source(hero.get("_source_url"), hero.get("_fetched_at"), hero.get("_version"))\n\n    tabs = st.tabs(["Ficha técnica", "Habilidades", "Estatísticas", "Itens", "Builds calculadas",\n                    "Diagnóstico de dados"])\n    with tabs[0]:\n        _sheet(hero, weapon)\n    with tabs[1]:\n        _abilities(abilities)\n    with tabs[2]:\n        _stats(ctx, hero)\n    with tabs[3]:\n        _items(ctx, hero)\n    with tabs[4]:\n        note("O motor (Fase 3) já <b>avalia</b> qualquer build com justificação item a item — usa "\n             "Otimizador → Avaliar build. A <b>procura automática</b> da melhor build (Fase 4) ainda não existe, "\n             "por isso não há aqui builds \'recomendadas\'.")\n    with tabs[5]:\n        st.caption("Que dados de entrada existem para o motor/simulador deste herói, na versão ativa.")\n        table(hero_data_completeness(hero, weapon, abilities))\n\n\ndef _sheet(hero: dict, weapon: dict | None) -> None:\n    c1, c2 = st.columns(2)\n    with c1:\n        st.markdown("#### Atributos base")\n        rows = hero_base_stats(hero)\n        for r in rows:\n            r["valor"] = UNKNOWN if r["valor"] is None else r["valor"]\n        table(rows, compact=["estatística", "valor"])\n        st.caption("Valores brutos da API (StartingStats). Unidades e escalas tal como o jogo as define; "\n                   "\'desconhecido\' = campo ausente ou nulo nos dados.")\n    with c2:\n        st.markdown("#### Arma principal")\n        if weapon is None:\n            st.warning("Arma principal não encontrada nos dados desta versão.")\n        else:\n            st.markdown(f"**{weapon[\'name\']}** · `{weapon[\'class_name\']}`")\n            table(weapon["rows"], compact=["estatística", "valor"])\n            with st.expander("Todos os campos de weapon_info"):\n                st.json(weapon["weapon_info"], expanded=False)\n        st.markdown("#### Ganhos por nível")\n        table(hero_level_gains(hero))\n    with st.expander("Bónus por investimento em slots (purchase_bonuses) — dados brutos"):\n        st.json(hero.get("purchase_bonuses") or {}, expanded=False)\n    with st.expander("JSON completo do herói"):\n        st.json({k: v for k, v in hero.items() if not k.startswith("_")}, expanded=False)\n\n\ndef _fmt_prop(p: dict | None) -> str:\n    if not p:\n        return UNKNOWN\n    v = p["value"] if p["value"] is not None else p["raw"]\n    return f"{num(v)}{p.get(\'unit\') or \'\'}"\n\n\ndef _abilities(abilities: list[dict]) -> None:\n    if not abilities:\n        st.warning("Habilidades não encontradas para este herói.")\n        return\n    for a in abilities:\n        if a.get("missing"):\n            st.warning(f"{a[\'slot\']}: `{a[\'class_name\']}` não existe nos itens desta versão.")\n            continue\n        with st.expander(f"{a[\'name\']}  ·  {a.get(\'ability_type\') or \'\'}", expanded=False):\n            if a.get("image"):\n                image(a["image"], width=56)\n            kpi_grid([(label, _fmt_prop(a.get(key)), (a.get(key) or {}).get("key"))\n                      for key, label in (("cooldown", "Cooldown"), ("duration", "Duração"),\n                                         ("cast_range", "Alcance"), ("charges", "Cargas"))])\n            if a["scaling"]:\n                st.markdown("**Escalamento**")\n                table([{k: r[k] for k in ("propriedade", "valor", "escala")} for r in a["scaling"]])\n            if a["upgrades"]:\n                st.markdown("**Melhorias (pontos de habilidade)**")\n                table(a["upgrades"], compact=["melhoria", "propriedade", "bónus"])\n            st.markdown("**Todas as propriedades**")\n            table(a["properties"], compact=["propriedade", "valor", "escala"])\n\n\ndef _hero_row(ctx: C.AppContext, hero: dict, match_mode: str) -> tuple[dict | None, dict | None]:\n    stored = ctx.db.latest_stats("hero-stats", ctx.default_filters(match_mode).key())\n    if not stored:\n        return None, None\n    return next((r for r in stored["rows"] if r["hero_id"] == hero["id"]), None), stored\n\n\ndef _stats(ctx: C.AppContext, hero: dict) -> None:\n    conf = ctx.cfg["statistics"]["confidence_level"]\n    cols = st.columns(2)\n    for col, (label, mode) in zip(cols, MODE_LABELS.items()):\n        with col:\n            st.markdown(f"#### {label}")\n            row, stored = _hero_row(ctx, hero, mode)\n            if not row:\n                st.caption("Sem estatísticas guardadas para este modo.")\n                continue\n            total = sum(r["matches"] for r in stored["rows"])\n            lo, hi = wilson_interval(row["wins"], row["matches"], conf)\n            kpi_grid([("Win rate", pct(row["wins"] / row["matches"]), f"IC {conf:.0%}: {pct(lo)} – {pct(hi)}"),\n                      ("Partidas", num(row["matches"]), None),\n                      ("Quota de jogadores", pct(row["matches"] / total if total else None), "popularidade")])\n            st.caption(f"Filtros: {stored[\'filters\']} · recolhido {C.fmt_dt(stored[\'data_fetched_at\'])}")\n    note("Win rate é uma medida observada. Não diz, por si só, se o herói é forte: depende de quem o joga, "\n         "do ranking e da composição das equipas. Todos os ranks juntos; filtros por ranking na página "\n         "Estatísticas.")\n\n\ndef _items(ctx: C.AppContext, hero: dict) -> None:\n    label = st.radio("Modo", list(MODE_LABELS), horizontal=True, key="hero_items_mode")\n    mode = MODE_LABELS[label]\n    f = ctx.default_filters(mode)\n    stored = ctx.db.latest_stats("item-stats", f.key(), hero["id"])\n    if st.button("Atualizar estatísticas de itens deste herói", key="hero_items_refresh"):\n        try:\n            with st.spinner("A consultar a API…"):\n                stored = ctx.collector.fetch_item_stats(int(hero["id"]), f)\n        except ApiError as err:\n            st.error(f"Falha na consulta: {err}")\n    if not stored or not stored.get("rows"):\n        st.caption("Sem estatísticas de itens guardadas para este herói e modo.")\n        return\n    hero_row, _ = _hero_row(ctx, hero, mode)\n    conf = ctx.cfg["statistics"]\n    df = item_stats_frame(stored["rows"], C.items_by_id(ctx), hero_row["wins"] if hero_row else None,\n                          hero_row["matches"] if hero_row else None, confidence=conf["confidence_level"],\n                          small=conf["small_sample"], reliable=conf["reliable_sample"])\n    st.markdown("#### Itens populares (mais comprados)")\n    note("Popularidade e win rate observados <b>não</b> são eficiência. Itens comprados tarde aparecem mais em "\n         "partidas já ganhas (quem ganha tem mais souls), por isso a coluna <i>compra média</i> é mostrada ao lado. "\n         "A seleção por eficiência será feita pelo motor matemático (Fase 3), não por esta tabela.", warn=True)\n    view = percent_columns(df, ["% partidas do herói", "win rate", "IC inferior", "IC superior"])\n    cols = ["item", "slot", "tier", "custo", "partidas com item", "% partidas do herói", "win rate",\n            "IC inferior", "IC superior", "Δ vs herói (pp)", "compra média (min)", "amostra"]\n    table(view[cols].head(40), compact=["item", "partidas com item", "win rate", "Δ vs herói (pp)"],\n          rename={"partidas com item": "partidas", "Δ vs herói (pp)": "Δ pp"}, column_config={\n        **pct_config(["% partidas do herói", "win rate", "IC inferior", "IC superior"]),\n        "Δ vs herói (pp)": st.column_config.NumberColumn(format="%+.1f"),\n        "compra média (min)": st.column_config.NumberColumn(format="%.1f"),\n    })\n    st.caption(f"Filtros: {stored[\'filters\']} · {len(df)} itens · recolhido {C.fmt_dt(stored.get(\'data_fetched_at\'))}")\n    _efficient(ctx, hero)\n\n\ndef _efficient(ctx: C.AppContext, hero: dict) -> None:\n    from ...engine.economy import rank_items\n    from ...engine.model import METRIC_LABELS\n    from .. import engine_ui as E\n\n    st.markdown("#### Itens eficientes (motor matemático)")\n    st.caption("Ganho por 1000 Souls a partir das propriedades reais dos itens, partindo do herói sem itens. "\n               "Cenário e build base ajustáveis em Otimizador → Eficiência por Soul.")\n    metric = st.selectbox("Atributo", ["weapon_dps_sustained", "ehp_mixed", "spirit_power", "ability_damage_index"],\n                          format_func=lambda m: METRIC_LABELS[m], key="hero_eff_metric")\n    rows = rank_items(E.evaluator(ctx), E.make_build(hero, []), E.shop_list(ctx), E.scenario_form(ctx), metric)\n    rows = [r for r in rows if (r["ganho por 1000 Souls"] or 0) > 0][:10]\n    if not rows:\n        st.caption("Nenhum item com ganho modelado neste atributo.")\n        return\n    table([{"item": r["item"], "slot": r["slot"], "custo": r["custo"], "ganho": r["ganho"],\n            "ganho por 1000 Souls": r["ganho por 1000 Souls"], "cobertura": r["cobertura"] or 0.0} for r in rows],\n          compact=["item", "ganho por 1000 Souls", "cobertura"], rename={"ganho por 1000 Souls": "por 1000 Souls"},\n          column_config={"ganho": st.column_config.NumberColumn(format="%.2f"),\n                         "ganho por 1000 Souls": st.column_config.NumberColumn(format="%.3f"),\n                         "cobertura": st.column_config.ProgressColumn("cobertura", min_value=0.0, max_value=1.0,\n                                                                      format="percent")})\n', 'src.ui.pages.optimizer': 'from __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\nimport plotly.graph_objects as go\nimport streamlit as st\n\nfrom ...data.normalizer import item_catalog, property_rows, shop_items\nfrom ...engine.diagnostics import export_sample, h_sust_status, mapping_coverage, weapon_checks_all\nfrom ...engine.economy import marginal_contributions, rank_items\nfrom ...engine.model import METRIC_LABELS\nfrom ...engine.rules import RULES\nfrom .. import context as C\nfrom .. import engine_ui as E\nfrom . import optimizer_phase4 as P4\nfrom ..components import is_compact, kpi_grid, no_data, note, table\nfrom ..theme import SLOT_COLORS, show_chart\n\nRANK_METRICS = ["weapon_dps_effective", "weapon_dps_sustained", "ehp_mixed", "ehp_bullet", "ehp_spirit",\n                "spirit_power", "ability_damage_index", "ability_cdr"]\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Otimizador de Builds")\n    if not ctx.version:\n        no_data()\n        return\n    note("<b>Otimizar</b> procura a melhor build para o teu estilo e orçamento (beam search + pesquisa local, "\n         "comparada com força bruta nos testes), com ordem de compra, Pareto, alternativas e comparação com a build "\n         "popular. Tudo calculado pelo motor a partir das propriedades reais dos itens, com as hipóteses à vista.")\n    sc = E.scenario_form(ctx)\n    tabs = st.tabs(["Otimizar", "Avaliar build", "Eficiência por Soul", "Sinergias", "Builds guardadas",\n                    "Catálogo de itens", "Fórmulas e validação"])\n    with tabs[0]:\n        P4.render_optimize(ctx, sc)\n    with tabs[1]:\n        _evaluate(ctx, sc)\n    with tabs[2]:\n        _efficiency(ctx, sc)\n    with tabs[3]:\n        P4.render_synergies(ctx, sc)\n    with tabs[4]:\n        P4.render_saved(ctx, sc)\n    with tabs[5]:\n        _catalog(ctx)\n    with tabs[6]:\n        _formulas(ctx)\n\n\n# ------------------------------------------------------------------------------------------------ avaliar\ndef _evaluate(ctx: C.AppContext, sc) -> None:\n    hero = E.hero_picker(ctx, "opt_hero")\n    if not hero:\n        return\n    items = E.item_picker(ctx, f"opt_items_{hero[\'id\']}", "Itens da build")\n    tiers = E.ability_tiers(ctx, hero, "opt_tiers")\n    ev = E.evaluator(ctx)\n    base = ev.evaluate(E.make_build(hero, [], tiers, "Herói base"), sc)\n    full = ev.evaluate(E.make_build(hero, items, tiers, "Build"), sc)\n\n    for issue in full.issues:\n        st.warning(issue)\n    cards = []\n    for label, key in [("DPS arma efetivo", "weapon_dps_effective"), ("DPS sustentado", "weapon_dps_sustained"),\n                       ("Vida efetiva vs balas", "ehp_bullet"), ("Vida efetiva vs Spirit", "ehp_spirit"),\n                       ("Spirit Power", "spirit_power")]:\n        b, v = base.metrics.get(key), full.metrics.get(key)\n        sub = f"{(v - b) / b * 100:+.0f}% vs herói base" if (b and v is not None) else "herói base"\n        cards.append((label, E.fmt_metric(key, v), sub))\n    cards.append(("Custo", f"{full.build.cost:,}".replace(",", " "), f"{len(items)} itens"))\n    kpi_grid(cards)\n\n    st.markdown("#### Métricas — herói base vs build")\n    table(E.metrics_table([("Herói base", base), ("Build", full)]), compact=["métrica", "Build", "Build vs Herói base"],\n          rename={"Build vs Herói base": "vs base"})\n\n    if items:\n        st.markdown("#### Justificação por item")\n        st.caption("Quanto cada item acrescenta à build completa (retirando-o e recalculando) e por cada 1000 Souls. "\n                   "\'cobertura\' = fração das propriedades do item que o motor consegue aplicar.")\n        cols = ["weapon_dps_effective", "ehp_mixed", "spirit_power", "ability_damage_index"]\n        rows = marginal_contributions(ev, full.build, sc, cols)\n        df = pd.DataFrame(rows)\n        cfg = {c: st.column_config.NumberColumn(format="%.2f") for c in df.columns if c.startswith("Δ")}\n        cfg["cobertura"] = st.column_config.ProgressColumn("cobertura", min_value=0.0, max_value=1.0, format="percent")\n        df["cobertura"] = df["cobertura"].fillna(0.0)\n        dps_col, ehp_col = f"Δ {METRIC_LABELS[\'weapon_dps_effective\']}", f"Δ {METRIC_LABELS[\'ehp_mixed\']}"\n        table(df, column_config=cfg, compact=["item", dps_col, ehp_col, "cobertura"],\n              rename={dps_col: "Δ DPS", ehp_col: "Δ EHP"})\n\n        applied, out = E.effects_tables(full)\n        c1, c2 = st.columns(2)\n        with c1:\n            st.markdown("#### Efeitos aplicados")\n            table(applied, compact=["item", "atributo", "valor nos dados"], rename={"valor nos dados": "valor"})\n        with c2:\n            st.markdown("#### Efeitos fora do modelo")\n            table(out, compact=["item", "propriedade", "motivo"])\n            st.caption("Passivos condicionais, ativos e propriedades sem mapeamento não entram nos números. "\n                       "Isto subestima itens cujo valor está no efeito especial — é uma limitação explícita.")\n\n    if full.weapon:\n        w = full.weapon\n        st.markdown("#### Arma — detalhe do cálculo")\n        table([\n            {"passo": "Dano por bala (com bónus %)", "valor": w.damage_per_bullet},\n            {"passo": "DPS contínuo (sem recarga)", "valor": w.dps},\n            {"passo": "Carregador / balas por segundo", "valor": f"{w.clip:g} / {w.bullets_per_second:.2f}"\n             if w.clip and w.bullets_per_second else None},\n            {"passo": "Tempo a esvaziar o carregador (s)", "valor": w.magazine_time},\n            {"passo": "Tempo de recarga (s)", "valor": w.reload},\n            {"passo": "DPS sustentado (H-SUST)", "valor": w.sustained_dps},\n            {"passo": "× queda de dano (R-FALL)", "valor": w.falloff_mult if w.falloff_known else "sem dados de queda"},\n            {"passo": "× headshots esperados (R-HS)", "valor": w.headshot_mult},\n            {"passo": "× (1 − resist. efetiva do alvo) (R-RES, R-SHRED)", "valor": w.resist_mult},\n            {"passo": "DPS efetivo", "valor": w.effective_dps},\n        ])\n\n    if full.abilities:\n        st.markdown("#### Habilidades")\n        table([{"habilidade": a["name"], "melhoria": f"T{a[\'tier\']}" if a["tier"] else "—",\n                "cooldown base (s)": a["cooldown_base"], "cooldown com build (s)": a["cooldown_eff"],\n                "dano por ciclo (heurístico)": a["damage_per_cycle"], "melhorias aplicadas": "; ".join(a["upgrades"])}\n               for a in full.abilities],\n              compact=["habilidade", "cooldown com build (s)", "dano por ciclo (heurístico)"],\n              rename={"cooldown com build (s)": "cooldown (s)", "dano por ciclo (heurístico)": "dano/ciclo"})\n        with st.expander("Propriedades escaladas com Spirit Power"):\n            for a in full.abilities:\n                if a["scaled"]:\n                    st.markdown(f"**{a[\'name\']}**")\n                    table(a["scaled"])\n\n    st.markdown("#### Regras e hipóteses usadas neste cálculo")\n    table(E.rules_table(full.rules_used), compact=E.RULES_COMPACT)\n    for n in full.notes:\n        st.caption(n)\n\n\n# ------------------------------------------------------------------------------------------------ eficiência\ndef _efficiency(ctx: C.AppContext, sc) -> None:\n    st.caption("Ganho de cada item de loja no atributo escolhido, por 1000 Souls, quando acrescentado à build "\n               "base. Calculado pelo motor — não usa popularidade nem win rate.")\n    hero = E.hero_picker(ctx, "eff_hero")\n    if not hero:\n        return\n    base_items = E.item_picker(ctx, f"eff_base_{hero[\'id\']}", "Build base (opcional — itens já comprados)")\n    c1, c2 = st.columns(2)\n    with c1:\n        metric = st.selectbox("Atributo", RANK_METRICS, format_func=lambda m: METRIC_LABELS[m], key="eff_metric")\n    with c2:\n        slots = st.multiselect("Slots", ["weapon", "vitality", "spirit"], default=["weapon", "vitality", "spirit"],\n                               format_func=lambda s: s.capitalize(), key="eff_slots")\n    ev = E.evaluator(ctx)\n    cands = [i for i in E.shop_list(ctx) if i.get("item_slot_type") in slots]\n    rows = rank_items(ev, E.make_build(hero, base_items), cands, sc, metric)\n    if not rows:\n        st.caption("Sem candidatos.")\n        return\n    df = pd.DataFrame(rows)\n    top = df.dropna(subset=["ganho por 1000 Souls"]).head(15)\n    top = top[top["ganho por 1000 Souls"] > 0]\n    if not top.empty:\n        fig = go.Figure(go.Bar(x=top["ganho por 1000 Souls"], y=top["item"], orientation="h",\n                               marker_color=[SLOT_COLORS.get(s, "#888") for s in top["slot"]],\n                               customdata=top["cobertura"].fillna(0) * 100,\n                               hovertemplate="%{y}: %{x:.2f} por 1000 Souls<br>cobertura %{customdata:.0f}%<extra></extra>"))\n        fig.update_layout(title="Top 15 — ganho por 1000 Souls", yaxis=dict(autorange="reversed"))\n        st.caption(f"Atributo: {METRIC_LABELS[metric]}")\n        show_chart(fig, max(220, 32 * len(top) + 90))\n    df["cobertura"] = df["cobertura"].fillna(0.0)\n    table(df.drop(columns=["item_id"]), compact=["item", "ganho por 1000 Souls", "cobertura"],\n          rename={"ganho por 1000 Souls": "por 1000 Souls"}, column_config={\n        "ganho": st.column_config.NumberColumn(format="%.2f"),\n        "ganho %": st.column_config.NumberColumn(format="%+.1f%%"),\n        "ganho por 1000 Souls": st.column_config.NumberColumn(format="%.3f"),\n        "cobertura": st.column_config.ProgressColumn("cobertura", min_value=0.0, max_value=1.0, format="percent"),\n    })\n    note("Itens com <b>cobertura baixa</b> têm a maior parte do valor em passivos/ativos que o motor ainda não "\n         "modela — o ganho mostrado é um mínimo, não o valor total do item.", warn=True)\n\n\n# ------------------------------------------------------------------------------------------------ catálogo\ndef _catalog(ctx: C.AppContext) -> None:\n    its = C.items(ctx)\n    rows = item_catalog(its)\n    c1, c2, c3 = st.columns([1, 1, 2])\n    with c1:\n        slots = st.multiselect("Slot", sorted({r["slot"] for r in rows if r["slot"]}), key="cat_slot")\n    with c2:\n        tiers = st.multiselect("Tier", sorted({r["tier"] for r in rows if r["tier"] is not None}), key="cat_tier")\n    with c3:\n        q = st.text_input("Procurar item", key="cat_q")\n    view = [r for r in rows if (not slots or r["slot"] in slots) and (not tiers or r["tier"] in tiers)\n            and (not q or q.lower() in str(r["item"]).lower())]\n    table(pd.DataFrame(view).drop(columns=["class_name"], errors="ignore"), compact=["item", "slot", "tier", "custo"])\n    st.caption(f"{len(view)} de {len(rows)} itens · versão {ctx.version} · fonte /v1/assets/items")\n    df = pd.DataFrame(rows)\n    if not df.empty:\n        st.markdown("#### Custo por tier (observado nos dados)")\n        table(df.groupby("tier")["custo"].agg(["count", "min", "max"]).reset_index()\n              .rename(columns={"count": "itens", "min": "custo mínimo", "max": "custo máximo"}))\n    names = sorted(r["item"] for r in rows)\n    if names:\n        name = st.selectbox("Detalhe de um item", names, key="cat_item")\n        it = next(i for i in shop_items(its) if i.get("name") == name)\n        desc = it.get("description") or {}\n        for k in ("desc", "passive", "active"):\n            if desc.get(k):\n                st.markdown(f"**{k}:** {desc[k]}")\n        table(property_rows(it.get("properties")), compact=["propriedade", "valor", "escala"])\n        with st.expander("JSON completo"):\n            st.json({k: v for k, v in it.items() if not k.startswith("_")}, expanded=False)\n\n\n# ------------------------------------------------------------------------------------------------ fórmulas\ndef _formulas(ctx: C.AppContext) -> None:\n    st.markdown("#### Regras do motor")\n    st.caption("documentado = descrito numa fonte pública · validado = confirmado contra os dados · "\n               "hipótese = necessário mas ainda sem prova · decisão de modelação = escolha explícita do motor.")\n    table(pd.DataFrame([{"regra": r.id, "nome": r.name, "estado": r.status, "fórmula": r.formula, "fonte": r.source,\n                         "nota": r.note} for r in RULES.values()]), compact=E.RULES_COMPACT)\n\n    st.markdown("#### Validação das fórmulas da arma contra a API")\n    checks = weapon_checks_all(C.heroes(ctx), C.items(ctx))\n    st.markdown(f"Estado de **H-SUST** (DPS com recarga): **{h_sust_status(checks)}**")\n    st.caption("Compara o que o motor calcula com os valores derivados que a própria API publica em weapon_info. "\n               "Concordância não é medição dentro do jogo, mas confirma que as fórmulas e os campos são coerentes.")\n    df = pd.DataFrame(checks)\n    if not df.empty:\n        only_bad = st.toggle("Mostrar só divergências", key="frm_bad")\n        if only_bad:\n            df = df[df["resultado"] == "DIVERGE"]\n        table(df, compact=["herói", "verificação", "erro %", "resultado"])\n\n    st.markdown("#### Cobertura do mapeamento de propriedades")\n    st.caption("Cada tipo de efeito (provided_property_type) nos itens de loja da versão ativa, e se o motor o "\n               "converte num atributo. Os não mapeados não entram nos cálculos.")\n    table(mapping_coverage(C.items(ctx)), compact=["tipo / propriedade", "ocorrências", "stat do motor"])\n\n    st.markdown("#### Exportar amostra de diagnóstico")\n    st.caption("Cria um ficheiro com a estrutura real dos dados (heróis iniciais, habilidades, alguns itens, "\n               "cobertura do mapeamento). Só contém dados públicos do jogo. Envia-o numa conversa para validar e "\n               "completar o mapeamento com dados reais.")\n    if st.button("Criar amostra", key="frm_export"):\n        dest = export_sample(ctx.db, ctx.version, ctx.cfg, Path(ctx.collector.base_dir) / "amostra_diagnostico.json")\n        st.session_state["sample_path"] = str(dest)\n    path = st.session_state.get("sample_path")\n    if path and Path(path).exists():\n        st.download_button("Descarregar amostra_diagnostico.json", Path(path).read_bytes(),\n                           file_name="amostra_diagnostico.json", mime="application/json")\n        st.caption(f"Também guardada em `{path}`")\n', 'src.ui.pages.optimizer_phase4': '"""Fase 4 na interface: Otimizar, Sinergias, Builds guardadas."""\n\nfrom __future__ import annotations\n\nimport dataclasses\nimport json\n\nimport numpy as np\nimport pandas as pd\nimport plotly.graph_objects as go\nimport streamlit as st\n\nfrom ...analytics.item_stats import item_window_frame\nfrom ...api.analytics_api import StatsFilters\nfrom ...api.http_client import ApiError\nfrom ...data.normalizer import index_by_class\nfrom ...data.patch_tracker import affected_entities\nfrom ...engine.build import Scenario\nfrom ...engine.model import METRIC_LABELS\nfrom ...models.meta import badge_range_for_tiers\nfrom ...optimizer.build_optimizer import OptimizerConfig, optimize, popular_build\nfrom ...optimizer.fast_model import FastModel\nfrom ...optimizer.item_synergy import empirical_synergies, mechanical_synergies\nfrom ...optimizer.objective_function import OBJECTIVE_LABELS, STYLES, Objective, calibrate_weights, normalize, \\\n    shrunk_evidence\nfrom ...optimizer.pareto import pareto_mask\nfrom ...optimizer.purchase_order import plan_order\nfrom ...optimizer.report import confidence_summary, internal_synergies, justify, markdown, now\nfrom ...optimizer.sensitivity import weight_sensitivity\nfrom .. import context as C\nfrom .. import engine_ui as E\nfrom ..components import is_compact, kpi_grid, note, table\nfrom ..theme import COLORS, show_chart\n\nWINDOWS = {"0–10 min": (0, 600), "10–20 min": (600, 1200), "20–30 min": (1200, 1800), "30+ min": (1800, 7000)}\nWEIGHT_KEYS = ["weapon", "ability", "survival", "mobility", "stats"]\n\n\n# ------------------------------------------------------------------------------------------- auxiliares\ndef _stats_filters(ctx: C.AppContext, key: str) -> tuple[StatsFilters, str]:\n    ranks = ctx.db.ranks(ctx.version)\n    names = {r["tier"]: r["name"] for r in ranks}\n    tiers = sorted(names)\n    c1, c2 = st.columns([1, 2])\n    with c1:\n        mode = st.selectbox("Modo (estatísticas)", ["Ranked", "Normal / Unranked"], key=f"{key}_mode")\n    with c2:\n        rng = None\n        if tiers:\n            rng = st.select_slider("Ranking (badge médio)", options=tiers, value=(tiers[0], tiers[-1]),\n                                   format_func=lambda t: names.get(t, str(t)), key=f"{key}_rank")\n    base = ctx.default_filters("ranked" if mode == "Ranked" else "unranked")\n    label = mode\n    if rng and (rng[0] != tiers[0] or rng[1] != tiers[-1]):\n        lo, hi = badge_range_for_tiers(int(rng[0]), int(rng[1]))\n        base = dataclasses.replace(base, min_average_badge=lo, max_average_badge=hi)\n        label += f", {names.get(rng[0])}–{names.get(rng[1])}"\n    else:\n        label += ", todos os ranks"\n    return base, label\n\n\ndef _fetch(label: str, fn):\n    try:\n        with st.spinner(f"A consultar a Deadlock API ({label})…"):\n            return fn()\n    except ApiError as err:\n        st.error(f"Falha na consulta ({label}): {err}")\n        return None\n\n\ndef _weights_widget(ctx: C.AppContext, key: str) -> tuple[dict[str, float], str]:\n    style = st.selectbox("Estilo", list(STYLES) + ["Personalizado", "Calibrado com dados"], key=f"{key}_style",\n                         help="Os estilos são escolhas explícitas de pesos (não dados). \'Calibrado\' usa a tua "\n                              "última calibração com dados reais.")\n    calibrated = st.session_state.get(f"{key}_calibrated")\n    if style == "Calibrado com dados" and calibrated:\n        base = dict(calibrated)\n    elif style == "Calibrado com dados":\n        st.caption("Ainda não há calibração — usa o botão em \'Pesos\'. A usar \'Híbrido\' entretanto.")\n        base = dict(STYLES["Híbrido"])\n    else:\n        base = dict(STYLES.get(style, STYLES["Híbrido"]))\n    with st.expander("Pesos da função objetivo", expanded=style == "Personalizado"):\n        st.caption("Score = Σ peso × ganho relativo face ao herói sem itens. \'Evidência estatística\' soma o Δ win rate "\n                   "observado dos itens (encolhido para amostras pequenas) — associação, não causalidade.")\n        w = {}\n        for k in WEIGHT_KEYS:\n            w[k] = st.slider(OBJECTIVE_LABELS[k], 0.0, 1.0, float(base.get(k, 0.0)), 0.05,\n                             key=f"{key}_w_{k}_{style}", disabled=style not in ("Personalizado",))\n    return normalize(w), style\n\n\ndef _summary_weights(w: dict[str, float]) -> str:\n    return ", ".join(f"{OBJECTIVE_LABELS[k]} {v:.0%}" for k, v in w.items() if v > 0)\n\n\n# ------------------------------------------------------------------------------------------- Otimizar\ndef render_optimize(ctx: C.AppContext, sc: Scenario) -> None:\n    ocfg = ctx.cfg.get("optimizer", {})\n    hero = E.hero_picker(ctx, "o4_hero")\n    if not hero:\n        return\n    tiers = E.ability_tiers(ctx, hero, "o4_tiers")\n    c1, c2 = st.columns(2)\n    with c1:\n        weights, style = _weights_widget(ctx, "o4")\n    with c2:\n        budget = st.slider("Orçamento (Souls)", 1000, 60000, int(ocfg.get("budget", 25000)), 500, key="o4_budget")\n    f, flabel = _stats_filters(ctx, "o4")\n    shop = E.shop_list(ctx)\n    by_id = {int(i["id"]): i for i in shop}\n    with st.expander("Itens obrigatórios / excluídos · fases da ordem de compra"):\n        locked = st.multiselect("Itens obrigatórios", list(by_id), format_func=lambda i: E.item_label(by_id[i]),\n                                key=f"o4_locked_{hero[\'id\']}")\n        excluded = st.multiselect("Itens excluídos", list(by_id), format_func=lambda i: E.item_label(by_id[i]),\n                                  key=f"o4_excl_{hero[\'id\']}")\n        e1, e2 = st.columns(2)\n        with e1:\n            early = st.number_input("Fim do early game (Souls)", 0, 60000, int(ocfg.get("early_max", 6000)), 500,\n                                    key="o4_early")\n        with e2:\n            mid = st.number_input("Fim do mid game (Souls)", 0, 60000, int(ocfg.get("mid_max", 18000)), 500, key="o4_mid")\n        st.caption("Os limites das fases são escolhas tuas (rótulos da sequência), não dados do jogo.")\n\n    ev = E.evaluator(ctx)\n    item_res = ctx.db.latest_stats("item-stats", f.key(), hero["id"])\n    win_f = dataclasses.replace(f, min_bought_at_s=600, max_bought_at_s=1200)\n    win_res = ctx.db.latest_stats("item-stats", win_f.key(), hero["id"])\n\n    with st.expander("Calibrar pesos com dados reais (opcional)"):\n        st.caption("Relaciona o Δ win rate de cada item (comprado na mesma janela de tempo) com os ganhos que o motor "\n                   "lhe atribui. Mínimos quadrados não-negativos + bootstrap. Associação observacional.")\n        wlabel = st.selectbox("Janela de compra", list(WINDOWS), index=1, key="o4_calwin")\n        cal_f = dataclasses.replace(f, min_bought_at_s=WINDOWS[wlabel][0], max_bought_at_s=WINDOWS[wlabel][1])\n        if st.button("Calibrar", key="o4_cal"):\n            res = ctx.db.latest_stats("item-stats", cal_f.key(), hero["id"]) or \\\n                _fetch("itens na janela", lambda: ctx.collector.fetch_item_stats(int(hero["id"]), cal_f))\n            if res and res.get("rows"):\n                fm0 = FastModel(ev, hero, sc, tiers)\n                cal = calibrate_weights(fm0, res["rows"], C.items_by_id(ctx),\n                                        min_matches=ctx.cfg["statistics"]["small_sample"])\n                st.session_state["o4_cal_result"] = cal\n                if cal.weights:\n                    st.session_state["o4_calibrated"] = cal.weights\n        cal = st.session_state.get("o4_cal_result")\n        if cal is not None:\n            (st.success if cal.ok else st.warning)(cal.message)\n            if cal.weights:\n                table([{"objetivo": OBJECTIVE_LABELS[k], "peso": cal.weights[k],\n                        "IC 95% (bootstrap)": f"{cal.ci[k][0]:.2f}–{cal.ci[k][1]:.2f}"} for k in cal.ci])\n                st.caption("Para usar: Estilo → \'Calibrado com dados\'.")\n\n    if st.button("Otimizar", type="primary", key="o4_run", width="stretch"):\n        fm = FastModel(ev, hero, sc, tiers)\n        evidence = shrunk_evidence(win_res["rows"]) if (win_res and weights.get("stats")) else {}\n        obj = Objective(fm, weights, evidence)\n        cfg = OptimizerConfig(budget=budget, flex_slots=sc.flex_slots, beam_width=int(ocfg.get("beam_width", 12)),\n                              locked=list(locked), excluded=set(excluded))\n        with st.spinner("A procurar a melhor build…"):\n            res = optimize(fm, obj, shop, cfg)\n            order = None\n            if res.best is not None:\n                buy = {int(r["item_id"]): (r.get("avg_buy_time_s") or 0) / 60 for r in (item_res or {}).get("rows", [])}\n                order = plan_order(obj, [by_id[i] for i in sorted(res.best.ids)], index_by_class(shop), int(early),\n                                   int(mid), buy_times=buy)\n        st.session_state["o4"] = {"res": res, "order": order, "obj": obj, "hero": hero, "weights": weights,\n                                  "style": style, "budget": budget, "sc": sc, "tiers": tiers, "flabel": flabel,\n                                  "fkey": f.key(), "cfg": cfg}\n    state = st.session_state.get("o4")\n    if not state or state["hero"]["id"] != hero["id"]:\n        st.caption("Escolhe o estilo e o orçamento e carrega em **Otimizar**.")\n        return\n    _show_result(ctx, state, item_res, win_res, by_id, shop)\n\n\ndef _show_result(ctx: C.AppContext, s: dict, item_res, win_res, by_id: dict[int, dict], shop: list[dict]) -> None:\n    res, obj, order, hero = s["res"], s["obj"], s["order"], s["hero"]\n    for m in res.messages:\n        st.error(m)\n    if res.best is None:\n        return\n    items = [by_id[i] for i in sorted(res.best.ids) if i in by_id]\n    ev = E.evaluator(ctx)\n    full = ev.evaluate(E.make_build(hero, items, s["tiers"], "Build"), s["sc"])\n    base = ev.evaluate(E.make_build(hero, [], s["tiers"], "Herói base"), s["sc"])\n\n    st.markdown("### Build recomendada")\n    kpi_grid([("Score", f"{res.best.score * 100:.1f} pts", s["style"]),\n              ("Custo", f"{res.best.cost:,}".replace(",", " "), f"orçamento {s[\'budget\']:,}".replace(",", " ")),\n              ("Itens", len(items), f"{len(res.candidates)} candidatos"),\n              ("Procura", f"{res.evaluations:,}".replace(",", " "), f"builds avaliadas em {res.seconds:.1f}s")])\n    st.caption(f"Pesos: {_summary_weights(s[\'weights\'])} · estatísticas: {s[\'flabel\']} · versão {ctx.version}")\n    for issue in full.issues:\n        st.warning(issue)\n\n    st.markdown("#### Porque cada item (justificação)")\n    j = pd.DataFrame(justify(obj, items))\n    j["cobertura"] = j["cobertura"].fillna(0.0)\n    table(j, compact=["item", "contributo (pts)", "pts por 1000 Souls"],\n          rename={"contributo (pts)": "pts", "pts por 1000 Souls": "pts/1000"},\n          column_config={c: st.column_config.NumberColumn(format="%.2f") for c in j.columns if "pts" in c or "Δ" in c}\n          | {"cobertura": st.column_config.ProgressColumn("cobertura", min_value=0.0, max_value=1.0, format="percent")})\n    st.caption("Contributo = quanto o score cai se o item sair da build (1 pt = 1% de ganho ponderado face ao herói "\n               "sem itens).")\n\n    if order:\n        st.markdown("#### Ordem de compra")\n        od = pd.DataFrame(order.steps)\n        table(od, compact=["passo", "fase", "ação", "item", "custo do passo"],\n              rename={"custo do passo": "custo"},\n              column_config={"score após": st.column_config.NumberColumn(format="%.4f"),\n                             "ganho do passo": st.column_config.NumberColumn(format="%.4f"),\n                             "minuto médio observado": st.column_config.NumberColumn(format="%.1f")})\n        med = float(np.median(order.random_areas)) if order.random_areas else None\n        st.caption(f"Melhor de {order.tested} ordens testadas (greedy por ganho/Soul, trocas de vizinhos e "\n                   f"{len(order.random_areas)} ordens aleatórias). Supera {order.percentile_vs_random:.0f}% das ordens "\n                   "aleatórias em poder acumulado ao longo das compras"\n                   + (f" (+{(order.area / med - 1) * 100:.1f}% vs mediana)" if med and med > 0 else "") + ".")\n        fig = go.Figure(go.Scatter(x=[0] + [r["Souls acumuladas"] for r in order.steps],\n                                   y=[0] + [(r["score após"] - obj.score([])[0]) * 100 for r in order.steps],\n                                   mode="lines+markers", line_shape="hv", line=dict(color=COLORS["gold"]),\n                                   text=[""] + [r["item"] for r in order.steps],\n                                   hovertemplate="%{text}<br>%{x} Souls: %{y:.1f} pts<extra></extra>"))\n        fig.update_layout(title="Poder ao longo das compras", xaxis_title="Souls gastas", yaxis_title="score (pts)")\n        show_chart(fig, 300)\n\n    st.markdown("#### Métricas estimadas")\n    table(E.metrics_table([("Herói base", base), ("Build", full)]), compact=["métrica", "Build", "Build vs Herói base"],\n          rename={"Build vs Herói base": "vs base"})\n\n    syn = internal_synergies(obj, items)\n    if syn:\n        st.markdown("#### Sinergias na build (motor)")\n        table(syn, compact=["itens", "sinergia (pts)"],\n              column_config={"sinergia (pts)": st.column_config.NumberColumn(format="%+.2f")})\n\n    st.markdown("#### Alternativas")\n    alt_rows = []\n    for out_id, opts in res.replacements.items():\n        if opts and out_id in by_id:\n            alt_id, loss = opts[0]\n            alt_rows.append({"item": by_id[out_id]["name"], "melhor alternativa": by_id[alt_id]["name"],\n                             "perda (pts)": loss * 100})\n    if alt_rows:\n        table(alt_rows, column_config={"perda (pts)": st.column_config.NumberColumn(format="%.2f")})\n        st.caption("Se não puderes comprar um item, esta é a troca que menos baixa o score (dentro do orçamento).")\n    if st.button("Alternativas situacionais (outros cenários)", key="o4_situ"):\n        _situational(ctx, s, by_id, shop)\n\n    _pareto(s, by_id)\n    _popular(ctx, s, item_res, by_id, items)\n\n    st.markdown("#### Confiança")\n    wdf = item_window_frame(win_res["rows"], C.items_by_id(ctx)) if (win_res and win_res.get("rows")) else None\n    conf = confidence_summary(obj, items, full.rules_used, wdf)\n    table([{"indicador": k, "valor": (f"{v:.0%}" if isinstance(v, float) else (", ".join(v) if isinstance(v, list) else v))}\n           for k, v in conf.items()])\n    if wdf is None:\n        st.caption("Sem estatísticas por janela de compra para este herói/filtros — consulta-as em Estatísticas › "\n                   "Itens por janela de compra (10–20 min) para ver a evidência empírica aqui.")\n    if res.unmodeled:\n        with st.expander(f"Itens fora da procura: {len(res.unmodeled)} (efeito não modelado)"):\n            st.caption("O motor não consegue calcular ganho para estes itens (efeitos condicionais, ativos ou não "\n                       "mapeados), por isso a procura não os pode escolher nem justificar.")\n            table([{"item": i.get("name"), "slot": i.get("item_slot_type"), "custo": i.get("cost")}\n                   for i in res.unmodeled])\n\n    if st.button("Analisar sensibilidade aos pesos", key="o4_sens"):\n        _sensitivity(ctx, s, by_id, shop)\n\n    st.markdown("#### Guardar / exportar")\n    name = st.text_input("Nome da build", f"{hero[\'name\']} — {s[\'style\']} {s[\'budget\'] // 1000}k", key="o4_name")\n    report = {\n        "hero": hero["name"], "created": now(), "version": ctx.version, "filters": s["flabel"],\n        "weights_text": f"{s[\'style\']} ({_summary_weights(s[\'weights\'])})", "budget": s["budget"],\n        "cost": res.best.cost, "scenario": ", ".join(f"{k}: {v}" for k, v in s["sc"].describe().items()),\n        "justification": justify(obj, items), "order": order.steps if order else [], "metrics": full.metrics,\n        "synergies": syn, "alternatives": [f"{r[\'item\']} → {r[\'melhor alternativa\']} (−{r[\'perda (pts)\']:.2f} pts)"\n                                           for r in alt_rows],\n        "confidence": conf, "rules": full.rules_used}\n    c1, c2 = st.columns(2)\n    with c1:\n        if st.button("Guardar build", key="o4_save", width="stretch"):\n            params = {"weights": s["weights"], "style": s["style"], "budget": s["budget"],\n                      "scenario": dataclasses.asdict(s["sc"]), "tiers": s["tiers"], "filters": s["flabel"]}\n            ctx.db.save_build(ctx.version, int(hero["id"]), hero["name"], name, params, sorted(res.best.ids),\n                              res.best.score, {k: v for k, v in full.metrics.items()})\n            st.success("Build guardada (ver separador Builds guardadas).")\n    with c2:\n        st.download_button("Descarregar relatório (.md)", markdown(report).encode("utf-8"),\n                           file_name=f"build_{hero[\'name\'].lower()}.md", mime="text/markdown", width="stretch")\n\n\ndef _situational(ctx: C.AppContext, s: dict, by_id: dict[int, dict], shop: list[dict]) -> None:\n    sc: Scenario = s["sc"]\n    variants = [\n        ("Alvo com +30 pp de resistência a balas", dataclasses.replace(sc, target_bullet_resist=min(0.9, sc.target_bullet_resist + 0.3))),\n        ("Recebes sobretudo dano Spirit (80%)", dataclasses.replace(sc, incoming_bullet_share=0.2)),\n        ("Recebes sobretudo dano de balas (80%)", dataclasses.replace(sc, incoming_bullet_share=0.8)),\n    ]\n    main = s["res"].best.ids\n    ev = E.evaluator(ctx)\n    rows = []\n    with st.spinner("A otimizar cenários alternativos…"):\n        for label, vsc in variants:\n            fm = FastModel(ev, s["hero"], vsc, s["tiers"])\n            obj = Objective(fm, s["weights"], s["obj"].item_evidence)\n            r = optimize(fm, obj, shop, dataclasses.replace(s["cfg"], beam_width=6))\n            if r.best is None:\n                continue\n            add = [by_id[i]["name"] for i in sorted(r.best.ids - main)]\n            rem = [by_id[i]["name"] for i in sorted(main - r.best.ids)]\n            rows.append({"cenário": label, "entra": ", ".join(add) or "—", "sai": ", ".join(rem) or "—"})\n    table(rows)\n    st.caption("Mesmos pesos e orçamento; só o cenário muda. \'entra/sai\' = diferenças face à build recomendada.")\n\n\ndef _pareto(s: dict, by_id: dict[int, dict]) -> None:\n    res, obj = s["res"], s["obj"]\n    pool = [c for c in res.pool if c.cost >= 0.85 * res.best.cost][:3000]\n    if len(pool) < 3:\n        return\n    rel = [obj.relative(c.metrics) for c in pool]\n    pts = np.array([[r["weapon"], r["ability"], r["survival"]] for r in rel])\n    mask = pareto_mask(pts)\n    st.markdown("#### Fronteira de Pareto")\n    fig = go.Figure()\n    fig.add_trace(go.Scatter(x=pts[~mask, 0] * 100, y=pts[~mask, 2] * 100, mode="markers", name="outras builds",\n                             marker=dict(size=5, color=COLORS["muted"], opacity=0.35)))\n    fig.add_trace(go.Scatter(x=pts[mask, 0] * 100, y=pts[mask, 2] * 100, mode="markers", name="Pareto",\n                             marker=dict(size=9, color=pts[mask, 1] * 100, colorscale="Viridis", showscale=False,\n                                         line=dict(width=1, color=COLORS["text"]))))\n    b = obj.relative(res.best.metrics)\n    fig.add_trace(go.Scatter(x=[b["weapon"] * 100], y=[b["survival"] * 100], mode="markers", name="recomendada",\n                             marker=dict(size=16, symbol="star", color=COLORS["gold"])))\n    fig.update_layout(title="Arma × sobrevivência", xaxis_title="ganho de DPS da arma (%)",\n                      yaxis_title="ganho de vida efetiva (%)")\n    show_chart(fig, 380)\n    st.caption(f"{int(mask.sum())} builds não dominadas entre {len(pool)} com custo semelhante (cor = ganho de "\n               "habilidades). Uma build Pareto não pode melhorar num objetivo sem piorar noutro.")\n    front = [(c, r) for c, r, m in zip(pool, rel, mask) if m]\n    front.sort(key=lambda x: -x[0].score)\n    table([{"score (pts)": c.score * 100, "arma %": r["weapon"] * 100, "habilidades %": r["ability"] * 100,\n            "sobrevivência %": r["survival"] * 100, "custo": c.cost,\n            "itens": ", ".join(by_id[i]["name"] for i in sorted(c.ids) if i in by_id)} for c, r in front[:8]],\n          compact=["score (pts)", "arma %", "sobrevivência %", "itens"],\n          column_config={k: st.column_config.NumberColumn(format="%.1f")\n                         for k in ("score (pts)", "arma %", "habilidades %", "sobrevivência %")})\n\n\ndef _popular(ctx: C.AppContext, s: dict, item_res, by_id: dict[int, dict], items: list[dict]) -> None:\n    st.markdown("#### Comparação com a build popular")\n    if not item_res or not item_res.get("rows"):\n        st.caption("Sem estatísticas de itens para este herói e filtros. Consulta-as em Estatísticas (ou atualiza "\n                   "os dados) para comparar com o que os jogadores compram.")\n        return\n    obj = s["obj"]\n    pop = popular_build(obj.model, item_res["rows"], by_id, s["budget"], s["sc"].flex_slots)\n    if not pop:\n        return\n    ev = E.evaluator(ctx)\n    e_pop = ev.evaluate(E.make_build(s["hero"], pop, s["tiers"], "Popular"), s["sc"])\n    e_opt = ev.evaluate(E.make_build(s["hero"], items, s["tiers"], "Recomendada"), s["sc"])\n    sp, _ = obj.score(pop)\n    kpi_grid([("Score recomendada", f"{s[\'res\'].best.score * 100:.1f} pts", None),\n              ("Score popular", f"{sp * 100:.1f} pts", f"{(s[\'res\'].best.score - sp) * 100:+.1f} pts de diferença")])\n    table(E.metrics_table([("Popular", e_pop), ("Recomendada", e_opt)]),\n          compact=["métrica", "Popular", "Recomendada"])\n    obs = {int(r["item_id"]): r for r in item_res["rows"]}\n    rows = []\n    for label, lst in (("popular", pop), ("recomendada", items)):\n        for it in lst:\n            r = obs.get(int(it["id"]))\n            rows.append({"build": label, "item": it["name"], "custo": it.get("cost"),\n                         "win rate (%)": round(r["wins"] / r["matches"] * 100, 1) if r and r["matches"] else None})\n    table(rows, compact=["build", "item", "win rate (%)"])\n    st.caption("Build popular = os itens mais comprados (dados observados) que cabem no mesmo orçamento. A diferença "\n               "de score usa o mesmo motor e as mesmas hipóteses para as duas.")\n\n\ndef _sensitivity(ctx: C.AppContext, s: dict, by_id: dict[int, dict], shop: list[dict]) -> None:\n    ev = E.evaluator(ctx)\n    fm = FastModel(ev, s["hero"], s["sc"], s["tiers"])\n    runs = int(ctx.cfg.get("optimizer", {}).get("sensitivity_runs", 10))\n\n    def run(w):\n        obj = Objective(fm, w, s["obj"].item_evidence)\n        r = optimize(fm, obj, shop, dataclasses.replace(s["cfg"], beam_width=6))\n        return r.best.ids if r.best else None\n\n    with st.spinner(f"A otimizar com {runs} variações dos pesos…"):\n        res = weight_sensitivity(s["weights"], run, s["res"].best.ids, runs=runs)\n    st.markdown(f"Semelhança média com a build recomendada: **{np.mean(res.jaccard) * 100:.0f}%** "\n                f"({res.runs} execuções, pesos perturbados ±~15%).")\n    rows = sorted(({"item": by_id[i]["name"] if i in by_id else i, "aparece em": f,\n                    "na recomendada": i in s["res"].best.ids} for i, f in res.frequency.items()),\n                  key=lambda r: -r["aparece em"])\n    table(rows, column_config={"aparece em": st.column_config.ProgressColumn("aparece em", min_value=0.0, max_value=1.0,\n                                                                              format="percent")})\n    st.caption("Itens perto de 100% são escolhas robustas; itens baixos dependem dos pesos exatos.")\n\n\n# ------------------------------------------------------------------------------------------- Sinergias\ndef render_synergies(ctx: C.AppContext, sc: Scenario) -> None:\n    hero = E.hero_picker(ctx, "syn_hero")\n    if not hero:\n        return\n    style = st.selectbox("Estilo (pesos)", list(STYLES), index=2, key="syn_style")\n    ev = E.evaluator(ctx)\n    obj = Objective(FastModel(ev, hero, sc), STYLES[style])\n    st.markdown("#### Sinergias mecânicas (motor)")\n    df = mechanical_synergies(obj, E.shop_list(ctx))\n    if df.empty:\n        st.caption("Sem itens com efeito modelado suficiente.")\n    else:\n        pos = df[df["sinergia (pts)"] > 0.01].head(15)\n        table(pos.drop(columns=["_a", "_b"]), compact=["item A", "item B", "sinergia (pts)"],\n              column_config={c: st.column_config.NumberColumn(format="%+.2f") for c in pos.columns if "pts" in c})\n        st.caption("sinergia = ganho do par − ganho de A − ganho de B (em pts do score). Positiva quando os efeitos se "\n                   "multiplicam nas fórmulas. Calculada entre os 25 itens com mais ganho individual.")\n    st.markdown("#### Sinergias empíricas (dados de partidas)")\n    f, flabel = _stats_filters(ctx, "syn")\n    perm = ctx.db.latest_stats("item-permutation-stats", f.key(), hero["id"])\n    if st.button("Consultar pares de itens (API)", key="syn_fetch"):\n        perm = _fetch("pares de itens", lambda: ctx.collector.fetch_permutation_stats(int(hero["id"]), f)) or perm\n    items_res = ctx.db.latest_stats("item-stats", f.key(), hero["id"])\n    hero_res = ctx.db.latest_stats("hero-stats", f.key())\n    hrow = next((r for r in (hero_res or {}).get("rows", []) if r["hero_id"] == hero["id"]), None)\n    if not perm or not perm.get("rows"):\n        st.caption("Sem dados de pares guardados. Carrega em **Consultar pares de itens**.")\n        return\n    if not items_res or not hrow:\n        st.caption("Faltam as estatísticas de itens/herói para estes filtros (Estatísticas › Consultar).")\n        return\n    conf = ctx.cfg["statistics"]\n    edf = empirical_synergies(perm["rows"], items_res["rows"], hrow["wins"], hrow["matches"], C.items_by_id(ctx),\n                              min_matches=conf["small_sample"], small=conf["small_sample"],\n                              reliable=conf["reliable_sample"])\n    if edf.empty:\n        st.caption("Nenhum par com amostra suficiente.")\n        return\n    view = edf.copy()\n    for c in ("win rate do par", "esperado sem interação"):\n        view[c] = view[c] * 100\n    table(view.head(20), compact=["item A", "item B", "interação (pp)", "significativo"],\n          rename={"significativo": "signif."},\n          column_config={"interação (pp)": st.column_config.NumberColumn(format="%+.1f"),\n                         "win rate do par": st.column_config.NumberColumn(format="%.1f%%"),\n                         "esperado sem interação": st.column_config.NumberColumn(format="%.1f%%"),\n                         "q (BH)": st.column_config.NumberColumn(format="%.3f")})\n    note(f"Filtros: {flabel}. \'esperado sem interação\' assume efeitos aditivos em log-odds de cada item. "\n         "Interações positivas significativas são pistas, não provas: pares comprados tarde aparecem em partidas já "\n         "ganhas.", warn=True)\n\n\n# ------------------------------------------------------------------------------------------- Builds guardadas\ndef render_saved(ctx: C.AppContext, sc: Scenario) -> None:\n    builds = ctx.db.saved_builds()\n    if not builds:\n        st.caption("Ainda não guardaste builds. Em **Otimizar**, carrega em **Guardar build**.")\n        return\n    st.caption("Reavaliar recalcula cada build com os dados da versão ATUAL e os mesmos pesos/cenário de quando foi "\n               "guardada — mostra o efeito dos patches.")\n    by_id = C.items_by_id(ctx)\n    heroes = C.heroes_by_id(ctx)\n    for b in builds:\n        title = f"{b[\'name\']} · {b[\'hero_name\']} · v{b[\'version\']} · {b[\'created_at\'][:16].replace(\'T\', \' \')}"\n        with st.expander(title):\n            names = [by_id[i]["name"] if i in by_id else f"#{i} (não existe na versão atual)" for i in b["item_ids"]]\n            st.markdown("**Itens:** " + ", ".join(names))\n            st.caption(f"Score ao guardar: {b[\'score\'] * 100:.1f} pts · {b[\'params\'].get(\'style\')} · "\n                       f"orçamento {b[\'params\'].get(\'budget\')}")\n            c1, c2 = st.columns(2)\n            with c1:\n                if st.button("Reavaliar na versão atual", key=f"re_{b[\'id\']}", width="stretch"):\n                    hero = heroes.get(int(b["hero_id"]))\n                    if not hero:\n                        st.error("O herói já não existe na versão atual.")\n                    else:\n                        p = b["params"]\n                        bsc = Scenario(**p.get("scenario", {})) if p.get("scenario") else sc\n                        fm = FastModel(E.evaluator(ctx), hero, bsc, p.get("tiers") or {})\n                        obj = Objective(fm, p.get("weights") or STYLES["Híbrido"])\n                        items = [by_id[i] for i in b["item_ids"] if i in by_id]\n                        s_now, m_now = obj.score(items)\n                        rows = [{"métrica": METRIC_LABELS[k], "ao guardar": b["metrics"].get(k), "agora": m_now.get(k)}\n                                for k in METRIC_LABELS if k in m_now]\n                        st.markdown(f"Score: **{b[\'score\'] * 100:.1f} → {s_now * 100:.1f} pts** "\n                                    f"({(s_now - b[\'score\']) * 100:+.1f})")\n                        table(rows, column_config={"ao guardar": st.column_config.NumberColumn(format="%.2f"),\n                                                   "agora": st.column_config.NumberColumn(format="%.2f")})\n                        if b["version"] != ctx.version:\n                            diffs = affected_entities(ctx.db.patch_diffs(b["version"], ctx.version),\n                                                      item_ids=set(b["item_ids"]), hero_ids={int(b["hero_id"])})\n                            if diffs:\n                                st.markdown("**Alterações do patch que tocam nesta build:**")\n                                table([{"nome": d["entity_name"], "campo": d["field"], "antes": d["old_value"],\n                                        "depois": d["new_value"]} for d in diffs])\n                            else:\n                                st.caption("Nenhuma alteração registada entre as versões toca nestes itens/herói.")\n            with c2:\n                if st.button("Apagar", key=f"del_{b[\'id\']}", width="stretch"):\n                    ctx.db.delete_build(int(b["id"]))\n                    st.rerun()\n            st.download_button("Parâmetros (JSON)", json.dumps(b, ensure_ascii=False, indent=1).encode("utf-8"),\n                               file_name=f"build_{b[\'id\']}.json", mime="application/json", key=f"dl_{b[\'id\']}")\n', 'src.ui.pages.patches': 'from __future__ import annotations\n\nimport pandas as pd\nimport streamlit as st\n\nfrom ...data.patch_tracker import diff_heroes, diff_items\nfrom .. import context as C\nfrom ..components import no_data, table\n\nCHANGE_PT = {"added": "adicionado", "removed": "removido", "field": "campo", "property": "propriedade",\n             "upgrades": "melhorias", "starting_stat": "atributo base", "level_up": "ganho por nível",\n             "slot": "habilidade/slot"}\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Histórico de Patches")\n    if not ctx.version:\n        no_data()\n        return\n\n    st.subheader("Versões do jogo vistas")\n    table(ctx.db.game_versions(), compact=["version", "version_datetime", "first_seen"])\n\n    versions = ctx.db.versions_with_data("items")\n    st.subheader("Comparar versões guardadas")\n    if len(versions) < 2:\n        st.caption(f"Só existe uma versão guardada ({versions[0] if versions else \'—\'}). A comparação fica "\n                   "disponível automaticamente quando sair um patch e a app o recolher.")\n    else:\n        c1, c2 = st.columns(2)\n        with c1:\n            new = st.selectbox("Versão nova", versions, index=0)\n        with c2:\n            old = st.selectbox("Versão anterior", [v for v in versions if v != new], index=0)\n        diffs = ctx.db.patch_diffs(old, new)\n        if not diffs:\n            diffs = diff_items(ctx.db.items(old), ctx.db.items(new), old, new)\n            diffs += diff_heroes(ctx.db.heroes(old), ctx.db.heroes(new), old, new)\n        if not diffs:\n            st.success("Sem diferenças entre estas versões.")\n        else:\n            df = pd.DataFrame(diffs)\n            df["change"] = df["change"].map(lambda c: CHANGE_PT.get(c, c))\n            types = st.multiselect("Tipo", sorted(df["entity_type"].unique()))\n            q = st.text_input("Filtrar por nome")\n            if types:\n                df = df[df["entity_type"].isin(types)]\n            if q:\n                df = df[df["entity_name"].fillna("").str.contains(q, case=False)]\n            st.caption(f"{len(df)} alterações")\n            table(df[["entity_type", "entity_name", "change", "field", "old_value", "new_value"]].rename(\n                columns={"entity_type": "tipo", "entity_name": "nome", "change": "alteração", "field": "campo",\n                         "old_value": "antes", "new_value": "depois"}), compact=["nome", "campo", "antes", "depois"])\n\n    st.subheader("Notas de patch oficiais")\n    notes = ctx.db.patch_notes(limit=30)\n    if not notes:\n        st.caption("Sem notas guardadas.")\n    for n in notes:\n        st.markdown(f"- [{n[\'title\']}]({n[\'link\']}) — {n[\'pub_date\']}")\n\n    st.subheader("Histórico da fonte secundária")\n    v = ctx.db.get_kv("data_api_versions")\n    if isinstance(v, dict) and v.get("builds"):\n        table(pd.DataFrame(v["builds"]).drop(columns=["manifests"], errors="ignore"))\n    else:\n        st.caption("Sem histórico da Deadlock Data API.")\n', 'src.ui.pages.settings': 'from __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\nimport streamlit as st\n\nfrom ...config import ROOT_DIR\nfrom ...data.cross_validation import compare_item_costs\nfrom .. import context as C\nfrom ..components import is_compact, note, table\nfrom ..updater import run_update\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Configurações")\n\n    st.subheader("Diagnóstico rápido")\n    from ...engine.diagnostics import quick_checks\n    from .. import engine_ui as E\n\n    checks = quick_checks(ctx.db, ctx.version, ctx.cfg, C.heroes(ctx), C.items(ctx), E.evaluator(ctx))\n    if is_compact():  # no telemóvel: lista com o texto completo (pronta para captura de ecrã)\n        st.markdown("\\n".join(f"- {c[\'estado\']} **{c[\'verificação\']}** — {c[\'detalhe\']}"\n                               + (f"  \\n  ↳ _{c[\'o que fazer\']}_" if c["o que fazer"] else "") for c in checks))\n    else:\n        table(checks)\n    errors = ctx.db.get_kv("error_log", []) or []\n    if errors:\n        with st.expander(f"Erros registados ({len(errors)})"):\n            for e in errors:\n                st.code(f"{e[\'at\']} — {e[\'page\']}\\n{e[\'error\']}\\n\\n{e[\'trace\']}", language=None)\n            if st.button("Limpar registo de erros"):\n                ctx.db.set_kv("error_log", [])\n                st.rerun()\n\n    st.subheader("Dados")\n    c1, c2, c3 = st.columns(3)\n    with c1:\n        if st.button("Atualizar tudo agora", type="primary", width="stretch"):\n            run_update(ctx, include_stats=True, where=st)\n    with c2:\n        if st.button("Limpar cache HTTP", width="stretch"):\n            n = ctx.collector.deadlock.client.cache.clear() if ctx.collector.deadlock.client.cache else 0\n            st.success(f"{n} entradas removidas. A próxima atualização volta a pedir tudo às APIs.")\n    with c3:\n        if st.button("Criar backup da base de dados", width="stretch"):\n            dest = ctx.db.backup(Path(ctx.collector.base_dir) / "backups", ctx.cfg["backups"]["keep"])\n            st.success(f"Backup criado: {dest.name}")\n    st.caption(f"Base de dados: `{ctx.db.path}`")\n\n    st.subheader("Validação cruzada entre fontes")\n    st.caption("Compara o custo dos itens de loja na Deadlock API (fonte principal) com a Deadlock Data API "\n               "(dados extraídos dos ficheiros do jogo). Correspondência pelo nome do item.")\n    if ctx.version:\n        snap = ctx.db.latest_snapshot("data_api_items")\n        res = compare_item_costs(C.items(ctx), snap["payload"] if snap else None)\n        if not res.get("available"):\n            st.caption("Sem dados da fonte secundária.")\n        else:\n            m1, m2, m3 = st.columns(3)\n            m1.metric("Itens correspondidos", res["matched"])\n            m2.metric("Custos diferentes", len(res["mismatches"]))\n            m3.metric("Só numa fonte", len(res["only_main"]) + len(res["only_secondary"]))\n            st.caption(f"Fonte secundária: build {res[\'secondary_build_id\']} · capturada {res[\'secondary_captured_at\']}. "\n                       "Diferenças podem significar versões diferentes entre fontes — não são corrigidas automaticamente.")\n            if res["mismatches"]:\n                table(res["mismatches"], compact=["item", "custo (Deadlock API)", "custo (Data API)"])\n            with st.expander("Itens sem correspondência"):\n                st.write({"só na Deadlock API": res["only_main"], "só na Data API": res["only_secondary"]})\n\n    st.subheader("Atualização automática diária (Windows)")\n    note("A app verifica ao abrir se os dados têm mais de "\n         f"{ctx.cfg[\'update\'][\'check_interval_h\']} h e atualiza sozinha. Para atualizar mesmo com a app fechada, "\n         "cria uma tarefa no Agendador de Tarefas — ver README, secção <i>Atualização diária</i>.")\n    st.code(f\'schtasks /Create /SC DAILY /ST 09:00 /TN "DeadlockBuildLab" /TR "\\\\"{ROOT_DIR / "ATUALIZAR_DADOS.bat"}\\\\""\',\n            language="bat")\n\n    st.subheader("Registo de pedidos às APIs")\n    log = ctx.db.fetch_log(300)\n    if log:\n        df = pd.DataFrame(log)[["at", "source", "ok", "http_status", "from_cache", "stale", "message", "url"]]\n        only_err = st.toggle("Só erros")\n        if only_err:\n            df = df[df["ok"] == 0]\n        table(df, compact=["at", "source", "ok", "message"])\n\n    st.subheader("Configuração ativa")\n    st.caption(f"Ficheiro: `{ctx.cfg.get(\'_config_path\')}` — edita-o e reinicia a app para aplicar.")\n    st.json({k: v for k, v in ctx.cfg.items() if not k.startswith("_")}, expanded=False)\n\n    st.subheader("Snapshots guardados")\n    table(ctx.db.snapshot_meta(), compact=["kind", "version", "fetched_at", "record_count"])\n', 'src.ui.pages.simulator': 'from __future__ import annotations\n\nimport pandas as pd\nimport plotly.graph_objects as go\nimport streamlit as st\n\nfrom ...data.normalizer import find_hero, hero_abilities, hero_data_completeness, hero_weapon\nfrom ...engine.simulate import time_to_kill, weapon_series\nfrom .. import context as C\nfrom .. import engine_ui as E\nfrom ..components import no_data, note, table\nfrom ..theme import COLORS, show_chart\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Simulador de Combate")\n    if not ctx.version:\n        no_data()\n        return\n    tabs = st.tabs(["Simulação da arma", "Diagnóstico de dados"])\n    with tabs[0]:\n        _weapon_sim(ctx)\n    with tabs[1]:\n        _diagnostics(ctx)\n\n\ndef _weapon_sim(ctx: C.AppContext) -> None:\n    note("Primeira parte do simulador (Fase 5): só a <b>arma</b>. Disparo contínuo até esvaziar o carregador, "\n         "recarga, repetir. Habilidades, itens ativos, movimento e precisão variável ainda não entram — as hipóteses "\n         "estão listadas no fim.")\n    hero = E.hero_picker(ctx, "sim_hero")\n    if not hero:\n        return\n    n = st.number_input("Número de builds", 1, 4, 2, key="sim_n")\n    cols = st.columns(int(n))\n    builds = []\n    for i, col in enumerate(cols):\n        with col:\n            label = st.text_input("Nome", f"Build {chr(65 + i)}", key=f"sim_name_{i}")\n            items = E.item_picker(ctx, f"sim_items_{i}", "Itens")\n            builds.append(E.make_build(hero, items, {}, label))\n\n    st.markdown("#### Alvo")\n    c1, c2 = st.columns(2)\n    with c1:\n        target_name = st.selectbox("Herói alvo (vida base dos dados)", C.hero_names(ctx, True), key="sim_target")\n        target = find_hero(C.heroes(ctx), target_name)\n    with c2:\n        extra_hp = st.number_input("Vida extra do alvo (itens, nível…)", 0, 10000, 0, step=50, key="sim_extra")\n    sc = E.scenario_form(ctx)\n    base_hp = ((target or {}).get("starting_stats") or {}).get("max_health", {}) or {}\n    if base_hp.get("value") is None:\n        st.warning("Vida base do alvo desconhecida nos dados.")\n        return\n    target_hp = float(base_hp["value"]) + extra_hp\n    st.caption(f"Vida do alvo: {target_hp:g} · resistência a balas efetiva: "\n               f"{max(0.0, sc.target_bullet_resist - sc.shred_bullet):.0%} (cenário) · duração {sc.combat_s:g} s")\n\n    ev = E.evaluator(ctx)\n    fig = go.Figure()\n    rows = []\n    for b in builds:\n        e = ev.evaluate(b, sc)\n        s = weapon_series(e.weapon, max(sc.combat_s, 5.0))\n        if s is None:\n            rows.append({"build": b.name, "resultado": "dados da arma insuficientes"})\n            continue\n        fig.add_trace(go.Scatter(x=s.t, y=s.damage, mode="lines", name=b.name))\n        ttk = time_to_kill(s, target_hp)\n        rows.append({"build": b.name, "custo": b.cost, "dano em %gs" % sc.combat_s: round(s.damage[-1], 1),\n                     "DPS médio": round(s.damage[-1] / sc.combat_s, 1),\n                     "tempo para matar (s)": ttk if ttk is not None else f"> {sc.combat_s:g}"})\n    fig.add_hline(y=target_hp, line_dash="dot", line_color=COLORS["gold"], annotation_text="vida do alvo",\n                  annotation_font_color=COLORS["gold"])\n    fig.update_layout(title="Dano acumulado da arma", xaxis_title="segundos", yaxis_title="dano")\n    show_chart(fig, 420)\n    table(rows, compact=["build", "tempo para matar (s)", "DPS médio"], rename={"tempo para matar (s)": "TTK (s)"})\n    st.markdown("**Hipóteses desta simulação**")\n    table(E.rules_table(["H-WD", "H-FR", "H-AMMO", "H-SUST", "R-RES", "R-SHRED", "R-FALL", "R-HS", "H-LEVEL",\n                         "H-INNATE"]), compact=E.RULES_COMPACT)\n    st.caption("A regeneração e a vida extra do alvo durante o combate não são simuladas; o alvo não se move.")\n\n\ndef _diagnostics(ctx: C.AppContext) -> None:\n    by_class = C.items_by_class(ctx)\n    matrix: dict[str, dict[str, bool]] = {}\n    for name in ctx.cfg["heroes"]["initial"]:\n        hero = find_hero(C.heroes(ctx), name)\n        if not hero:\n            continue\n        weapon = hero_weapon(hero, by_class)\n        abilities = hero_abilities(hero, by_class, ctx.cfg["ability_property_keys"])\n        for row in hero_data_completeness(hero, weapon, abilities):\n            matrix.setdefault(row["entrada"], {})[hero["name"]] = row["disponível"]\n    if not matrix:\n        st.warning("Heróis iniciais não encontrados nos dados.")\n        return\n    df = pd.DataFrame(matrix).T.reset_index().rename(columns={"index": "entrada do simulador"})\n    table(df)\n    st.caption("✔ = o campo existe na versão ativa. O que faltar é tratado como hipótese explícita — nunca "\n               "preenchido com valores inventados.")\n    st.markdown("**Ainda por modelar:** ganhos por nível/boons, passivos e ativos de itens, mobilidade, "\n                "precisão variável com a distância, curas e escudos durante o combate.")\n', 'src.ui.pages.statistics': 'from __future__ import annotations\n\nimport dataclasses\nimport time\n\nimport pandas as pd\nimport plotly.graph_objects as go\nimport streamlit as st\n\nfrom ...analytics.hero_stats import hero_stats_frame\nfrom ...analytics.item_stats import item_stats_frame, item_window_frame\nfrom ...analytics.matchups import counters, synergies\nfrom ...api.analytics_api import StatsFilters\nfrom ...api.http_client import ApiError\nfrom ...data.normalizer import find_hero\nfrom ...models.meta import badge_range_for_tiers\nfrom .. import context as C\nfrom ..components import no_data, note, pct_config, percent_columns, table\nfrom ..theme import COLORS, SLOT_COLORS, show_chart\n\nMODES = {"Ranked": "ranked", "Normal / Unranked": "unranked", "Ambos (agrupados)": "ranked,unranked"}\nPERIODS = {"Predefinição da API": None, "Últimos 7 dias": 7, "Últimos 14 dias": 14, "Últimos 30 dias": 30}\nWINDOWS = {"0–10 min": (0, 600), "10–20 min": (600, 1200), "20–30 min": (1200, 1800), "30–45 min": (1800, 2700),\n           "45+ min": (2700, 7000)}\nPCT = ["win rate", "IC inferior", "IC superior"]\n\n\ndef _filters(ctx: C.AppContext, mode: str, tiers: tuple[int, int] | None, days: int | None,\n             duration: tuple[int, int | None] | None) -> StatsFilters:\n    min_b = max_b = None\n    if tiers is not None:\n        min_b, max_b = badge_range_for_tiers(*tiers)\n    min_ts = None\n    if days:\n        day = 86400\n        min_ts = int(time.time() // day * day - days * day)  # arredondado ao dia -> cache estável\n    s = ctx.cfg["statistics"]\n    return StatsFilters(game_mode=s["game_mode"], match_mode=mode, min_average_badge=min_b,\n                        max_average_badge=max_b, min_unix_timestamp=min_ts, min_matches=s["min_matches_query"],\n                        min_duration_s=duration[0] * 60 if duration and duration[0] else None,\n                        max_duration_s=duration[1] * 60 if duration and duration[1] else None)\n\n\ndef _run(label: str, fn):\n    try:\n        with st.spinner(f"A consultar a Deadlock API ({label})…"):\n            return fn()\n    except ApiError as err:\n        st.error(f"Falha na consulta ({label}): {err}")\n        return None\n\n\ndef render() -> None:\n    ctx = C.get_ctx()\n    st.title("Estatísticas")\n    if not ctx.version:\n        no_data()\n        return\n    ranks = ctx.db.ranks(ctx.version)\n    tier_names = {r["tier"]: r["name"] for r in ranks}\n    tiers_sorted = sorted(tier_names)\n\n    with st.form("stats_filters"):\n        c1, c2, c3 = st.columns([1, 2, 1])\n        with c1:\n            mode_label = st.selectbox("Modo de jogo", list(MODES))\n        with c2:\n            if tiers_sorted:\n                rng = st.select_slider("Ranking (badge médio da partida)", options=tiers_sorted,\n                                       value=(tiers_sorted[0], tiers_sorted[-1]),\n                                       format_func=lambda t: tier_names.get(t, str(t)))\n            else:\n                rng = None\n                st.caption("Ranks ainda não carregados.")\n        with c3:\n            period = st.selectbox("Período", list(PERIODS))\n        c4, c5 = st.columns([2, 2])\n        with c4:\n            dur = st.slider("Duração da partida (min)", 0, 90, (0, 90), step=5)\n        with c5:\n            hero_name = st.selectbox("Herói (itens e matchups)", C.hero_names(ctx, True))\n        submitted = st.form_submit_button("Consultar", type="primary")\n\n    all_ranks = rng is None or (rng[0] == tiers_sorted[0] and rng[1] == tiers_sorted[-1])\n    duration = None if dur == (0, 90) else (dur[0], dur[1] if dur[1] < 90 else None)\n    f = _filters(ctx, MODES[mode_label], None if all_ranks else (int(rng[0]), int(rng[1])), PERIODS[period], duration)\n    hero = find_hero(C.heroes(ctx), hero_name)\n\n    hero_res = ctx.db.latest_stats("hero-stats", f.key())\n    item_res = ctx.db.latest_stats("item-stats", f.key(), hero["id"]) if hero else None\n    if submitted:\n        hero_res = _run("heróis", lambda: ctx.collector.fetch_hero_stats(f)) or hero_res\n        if hero:\n            item_res = _run("itens", lambda: ctx.collector.fetch_item_stats(int(hero["id"]), f)) or item_res\n\n    note("O filtro de ranking usa o <b>badge médio das duas equipas</b> (min/max_average_badge da API), não o "\n         "rank individual de cada jogador. Um intervalo de ranks agrupa partidas — não corresponde a nenhum rank "\n         "específico. \'Ambos\' mistura Ranked e Unranked.")\n\n    tabs = st.tabs(["Heróis", "Itens", "Itens por janela de compra", "Matchups"])\n    conf = ctx.cfg["statistics"]\n    kw = dict(confidence=conf["confidence_level"], small=conf["small_sample"], reliable=conf["reliable_sample"])\n    hrow = None\n    if hero_res and hero:\n        hrow = next((r for r in hero_res["rows"] if r["hero_id"] == hero["id"]), None)\n\n    with tabs[0]:\n        if not hero_res:\n            st.caption("Sem resultados guardados para estes filtros. Carrega em **Consultar**.")\n        else:\n            if hero_res.get("offline"):\n                st.warning("Sem ligação: a mostrar o último resultado guardado para estes filtros.")\n            df = hero_stats_frame(hero_res["rows"], C.heroes_by_id(ctx), **kw)\n            st.caption(f"Filtros: {f.describe()} · recolhido {C.fmt_dt(hero_res.get(\'data_fetched_at\'))}")\n            _hero_chart(df, ctx.cfg["heroes"]["initial"])\n            view = percent_columns(df, PCT + ["quota de jogadores"])\n            cols = [c for c in ["herói", "partidas", "win rate", "IC inferior", "IC superior", "quota de jogadores",\n                                "amostra", "abates/partida", "mortes/partida", "assistências/partida", "souls/partida"]\n                    if c in view]\n            table(view[cols], column_config=pct_config(PCT + ["quota de jogadores"]),\n                  compact=["herói", "partidas", "win rate", "amostra"])\n\n    with tabs[1]:\n        _items_tab(ctx, hero, item_res, hrow, kw)\n\n    with tabs[2]:\n        _window_tab(ctx, hero, f, kw)\n\n    with tabs[3]:\n        _matchups_tab(ctx, hero, f, hrow, kw)\n\n\ndef _items_tab(ctx, hero, item_res, hrow, kw) -> None:\n    if not hero:\n        return\n    if not item_res or not item_res.get("rows"):\n        st.caption("Sem estatísticas de itens para este herói e filtros. Carrega em **Consultar**.")\n        return\n    idf = item_stats_frame(item_res["rows"], C.items_by_id(ctx), hrow["wins"] if hrow else None,\n                           hrow["matches"] if hrow else None, **kw)\n    note("Associação ≠ causalidade. O gráfico mostra o win rate de quem comprou cada item contra o minuto médio "\n         "de compra: itens tardios aparecem sobretudo em partidas que já estavam a ser ganhas. Para comparar itens "\n         "em condições semelhantes usa o separador <b>Itens por janela de compra</b>.", warn=True)\n    _item_chart(idf, hrow)\n    iview = percent_columns(idf, ["% partidas do herói"] + PCT)\n    icols = ["item", "slot", "tier", "custo", "partidas com item", "% partidas do herói", "win rate", "IC inferior",\n             "IC superior", "Δ vs herói (pp)", "compra média (min)", "compra (% da partida)", "vendido (%)", "amostra"]\n    table(iview[icols], compact=["item", "partidas com item", "win rate", "Δ vs herói (pp)"],\n          rename={"partidas com item": "partidas", "Δ vs herói (pp)": "Δ pp"}, column_config={\n        **pct_config(["% partidas do herói"] + PCT),\n        "Δ vs herói (pp)": st.column_config.NumberColumn(format="%+.1f"),\n        "compra média (min)": st.column_config.NumberColumn(format="%.1f"),\n        "compra (% da partida)": st.column_config.NumberColumn(format="%.0f"),\n        "vendido (%)": st.column_config.NumberColumn(format="%.0f"),\n    })\n\n\ndef _window_tab(ctx, hero, f: StatsFilters, kw) -> None:\n    if not hero:\n        return\n    st.caption("Compara itens comprados no MESMO intervalo de tempo. A linha de base é o win rate de todas as "\n               "compras nessa janela. Teste binomial exato e correção de Benjamini–Hochberg (q < 0,05) para não "\n               "confundir sorte com sinal quando se testam dezenas de itens ao mesmo tempo.")\n    wlabel = st.radio("Janela de compra", list(WINDOWS), horizontal=True, key="win")\n    lo, hi = WINDOWS[wlabel]\n    fw = dataclasses.replace(f, min_bought_at_s=lo, max_bought_at_s=hi)\n    res = ctx.db.latest_stats("item-stats", fw.key(), hero["id"])\n    if st.button("Consultar esta janela", key="win_btn"):\n        res = _run("itens na janela", lambda: ctx.collector.fetch_item_stats(int(hero["id"]), fw)) or res\n    if not res or not res.get("rows"):\n        st.caption("Sem dados guardados para esta janela. Carrega em **Consultar esta janela**.")\n        return\n    df = item_window_frame(res["rows"], C.items_by_id(ctx), **kw)\n    base = df.attrs.get("baseline")\n    st.markdown(f"Linha de base da janela: **{base * 100:.1f}%** "\n                f"({int(df[\'compras na janela\'].sum()):,} compras)".replace(",", " ") if base else "")\n    view = percent_columns(df, PCT)\n    table(view[["item", "slot", "custo", "compras na janela", "win rate", "IC inferior", "IC superior",\n                "Δ vs janela (pp)", "q (BH)", "significativo", "amostra"]],\n          compact=["item", "compras na janela", "win rate", "significativo"],\n          rename={"compras na janela": "compras", "significativo": "signif."},\n          column_config={**pct_config(PCT), "Δ vs janela (pp)": st.column_config.NumberColumn(format="%+.1f"),\n                         "q (BH)": st.column_config.NumberColumn(format="%.3f")})\n    st.caption(f"Filtros: {fw.describe()} · recolhido {C.fmt_dt(res.get(\'data_fetched_at\'))}")\n\n\ndef _matchups_tab(ctx, hero, f: StatsFilters, hrow, kw) -> None:\n    if not hero:\n        return\n    baseline = (hrow["wins"] / hrow["matches"]) if hrow and hrow.get("matches") else None\n    cres = ctx.db.latest_stats("hero-counter-stats", f.key())\n    sres = ctx.db.latest_stats("hero-synergy-stats", f.key())\n    if st.button("Consultar matchups", key="mu_btn"):\n        cres = _run("counters", lambda: ctx.collector.fetch_counter_stats(f)) or cres\n        sres = _run("sinergias", lambda: ctx.collector.fetch_synergy_stats(f)) or sres\n    if baseline is None:\n        st.caption("Consulta primeiro as estatísticas de heróis (botão Consultar) para ter a linha de base.")\n    c1, c2 = st.columns(2)\n    hb = C.heroes_by_id(ctx)\n    for col, res, fn, title in ((c1, cres, counters, "Contra cada inimigo (mesma lane)"),\n                                (c2, sres, synergies, "Com cada aliado")):\n        with col:\n            st.markdown(f"#### {title}")\n            if not res or not res.get("rows"):\n                st.caption("Sem dados. Carrega em **Consultar matchups**.")\n                continue\n            df = fn(res["rows"], int(hero["id"]), hb, baseline, **kw)\n            if df.empty:\n                st.caption("Sem linhas para este herói.")\n                continue\n            view = percent_columns(df, PCT)\n            cols = [c for c in ["herói", "partidas", "win rate", "IC inferior", "IC superior",\n                                "Δ vs média do herói (pp)", "significativo", "amostra"] if c in view]\n            table(view[cols], compact=["herói", "partidas", "win rate", "significativo"],\n                  rename={"significativo": "signif."}, column_config={**pct_config(PCT),\n                                             "Δ vs média do herói (pp)": st.column_config.NumberColumn(format="%+.1f")})\n    st.caption("Ordenado do pior para o melhor. \'significativo\' = q < 0,05 após Benjamini–Hochberg contra o win "\n               "rate médio do herói. Matchups também dependem de quem joga cada herói — são associações.")\n\n\ndef _hero_chart(df: pd.DataFrame, initial: list[str]) -> None:\n    if df.empty:\n        return\n    top = df.head(25)\n    extra = df[df["herói"].isin(initial) & ~df["herói"].isin(top["herói"])]\n    d = pd.concat([top, extra]).sort_values("win rate")\n    colors = [COLORS["gold"] if h in initial else COLORS["muted"] for h in d["herói"]]\n    fig = go.Figure(go.Scatter(\n        x=d["win rate"] * 100, y=d["herói"], mode="markers", marker=dict(color=colors, size=9),\n        error_x=dict(type="data", symmetric=False, array=(d["IC superior"] - d["win rate"]) * 100,\n                     arrayminus=(d["win rate"] - d["IC inferior"]) * 100, color=COLORS["muted"], thickness=1.5, width=4),\n        hovertemplate="%{y}: %{x:.1f}%<extra></extra>",\n    ))\n    fig.add_vline(x=50, line_dash="dot", line_color=COLORS["muted"])\n    fig.update_layout(title="Win rate (IC 95%)", xaxis_title="win rate (%)")\n    st.caption("25 heróis mais jogados + heróis iniciais (a dourado). Barras = intervalo de confiança de 95%.")\n    show_chart(fig, max(380, 22 * len(d)))\n\n\ndef _item_chart(idf: pd.DataFrame, hrow: dict | None) -> None:\n    d = idf.dropna(subset=["compra média (min)", "win rate"])\n    if d.empty:\n        return\n    fig = go.Figure()\n    for slot, g in d.groupby("slot", dropna=False):\n        fig.add_trace(go.Scatter(\n            x=g["compra média (min)"], y=g["win rate"] * 100, mode="markers", name=str(slot),\n            marker=dict(size=(g["partidas com item"] ** 0.5).clip(4, 30), color=SLOT_COLORS.get(str(slot), COLORS["muted"]),\n                        opacity=0.8, line=dict(width=0)),\n            text=g["item"], hovertemplate="%{text}<br>compra ~%{x:.1f} min<br>WR %{y:.1f}%<extra></extra>",\n        ))\n    if hrow and hrow.get("matches"):\n        fig.add_hline(y=hrow["wins"] / hrow["matches"] * 100, line_dash="dot", line_color=COLORS["gold"],\n                      annotation_text="win rate do herói", annotation_font_color=COLORS["gold"])\n    fig.update_layout(title="Win rate vs minuto de compra", xaxis_title="minuto médio de compra",\n                      yaxis_title="win rate (%)")\n    st.caption("Cada ponto é um item; tamanho = nº de partidas; linha = win rate do herói.")\n    show_chart(fig, 420)\n', 'src.ui.phone': '"""Acesso pelo telemóvel na mesma rede Wi-Fi: endereço local do PC e QR code."""\n\nfrom __future__ import annotations\n\nimport io\nimport os\nimport socket\nfrom pathlib import Path\n\nimport streamlit as st\n\n\ndef lan_ip() -> str | None:\n    """IP do PC na rede local (não envia nada: só pergunta ao sistema que interface usaria)."""\n    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n    try:\n        s.connect(("10.255.255.255", 1))\n        ip = s.getsockname()[0]\n        return None if ip.startswith("127.") else ip\n    except OSError:\n        return None\n    finally:\n        s.close()\n\n\ndef phone_url() -> str | None:\n    ip = lan_ip()\n    if not ip:\n        return None\n    try:\n        port = int(st.get_option("server.port") or 8501)\n    except (TypeError, ValueError):\n        port = 8501\n    return f"http://{ip}:{port}"\n\n\ndef qr_png(text: str) -> bytes | None:\n    try:\n        import qrcode\n    except ImportError:\n        return None\n    img = qrcode.make(text, box_size=6, border=2)\n    buf = io.BytesIO()\n    img.save(buf, format="PNG")\n    return buf.getvalue()\n\n\ndef running_in_cloud() -> bool:\n    """Streamlit Community Cloud corre a app a partir de /mount/src/<repositório>."""\n    return str(Path(__file__).resolve()).startswith("/mount/src/") or os.environ.get("HOSTNAME") == "streamlit"\n\n\ndef sidebar_panel() -> None:\n    if running_in_cloud():  # na nuvem o endereço local do servidor não serve para nada\n        return\n    with st.expander("📱 Abrir no telemóvel"):\n        url = phone_url()\n        if not url:\n            st.caption("Não foi possível descobrir o endereço do PC na rede local.")\n            return\n        png = qr_png(url)\n        if png:\n            st.image(png, width=180)\n        st.code(url, language=None)\n        st.caption("Telemóvel na mesma rede Wi-Fi que o PC, com a app aberta no PC. "\n                   "Fora de casa não funciona (ver README › Usar no telemóvel).")\n', 'src.ui.theme': '"""Tema escuro inspirado na estética de Deadlock (art déco sombrio, creme e dourado)."""\n\nfrom __future__ import annotations\n\nimport streamlit as st\n\nCOLORS = {\n    "bg": "#0d0f0e",\n    "panel": "#161a18",\n    "border": "#2a302c",\n    "text": "#e9e2cf",\n    "muted": "#9c9684",\n    "gold": "#c9a45c",\n    "weapon": "#e0913a",\n    "vitality": "#74b04a",\n    "spirit": "#a56ad8",\n    "good": "#74b04a",\n    "bad": "#d0594a",\n}\n\nSLOT_COLORS = {"Weapon": COLORS["weapon"], "Vitality": COLORS["vitality"], "Spirit": COLORS["spirit"],\n               "weapon": COLORS["weapon"], "vitality": COLORS["vitality"], "spirit": COLORS["spirit"]}\n\nCSS = f"""\n<style>\n.stApp {{\n  background: radial-gradient(1100px 520px at 0% -10%, #1c221e 0%, {COLORS[\'bg\']} 60%) fixed;\n}}\nh1, h2, h3, h4 {{\n  font-family: Georgia, \'Times New Roman\', serif !important;\n  letter-spacing: .03em;\n}}\nh1 {{\n  text-transform: uppercase;\n  color: {COLORS[\'text\']};\n  border-bottom: 1px solid {COLORS[\'border\']};\n  padding-bottom: .35rem;\n}}\n[data-testid="stSidebar"] {{\n  background: #101311;\n  border-right: 1px solid {COLORS[\'border\']};\n}}\n.dbl-card {{\n  background: {COLORS[\'panel\']};\n  border: 1px solid {COLORS[\'border\']};\n  border-radius: 6px;\n  padding: 12px 16px;\n  height: 100%;\n}}\n.dbl-kpi-label {{\n  font-size: .72rem; text-transform: uppercase; letter-spacing: .09em; color: {COLORS[\'muted\']};\n}}\n.dbl-kpi-value {{\n  font-family: Georgia, serif; font-size: 1.55rem; color: {COLORS[\'text\']}; line-height: 1.25;\n}}\n.dbl-kpi-sub {{ font-size: .78rem; color: {COLORS[\'muted\']}; }}\n.dbl-note {{\n  border-left: 3px solid {COLORS[\'gold\']};\n  background: #18190f80;\n  padding: 8px 12px; margin: 6px 0 12px 0;\n  color: #d4ccb6; font-size: .9rem; border-radius: 0 4px 4px 0;\n}}\n.dbl-warn {{ border-left-color: {COLORS[\'bad\']}; }}\n.dbl-pill {{\n  display: inline-block; padding: 0 8px; margin-right: 4px; border-radius: 10px;\n  font-size: .75rem; border: 1px solid {COLORS[\'border\']}; color: {COLORS[\'muted\']};\n}}\n.dbl-kpi-grid {{\n  display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\n  gap: .5rem; margin: .25rem 0 .9rem 0;\n}}\n.dbl-kpi-grid .dbl-card {{ height: auto; }}\n.dbl-brand {{\n  font-family: Georgia, serif; text-transform: uppercase; letter-spacing: .18em;\n  color: {COLORS[\'gold\']}; font-size: .95rem; margin-bottom: .2rem;\n}}\n@media (max-width: 640px) {{\n  h1 {{ font-size: 1.65rem !important; letter-spacing: .02em; padding-bottom: .2rem !important; }}\n  h2 {{ font-size: 1.3rem !important; }}\n  h3 {{ font-size: 1.12rem !important; }}\n  h4 {{ font-size: 1rem !important; }}\n  [data-testid="stMainBlockContainer"], .block-container {{\n    padding-left: .75rem !important; padding-right: .75rem !important; padding-top: 2.6rem !important;\n  }}\n  .dbl-kpi-grid {{ grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .4rem; }}\n  .dbl-card {{ padding: 8px 10px; }}\n  .dbl-kpi-label {{ font-size: .64rem; letter-spacing: .06em; }}\n  .dbl-kpi-value {{ font-size: 1.2rem; }}\n  .dbl-kpi-sub {{ font-size: .7rem; }}\n  .dbl-note {{ font-size: .84rem; padding: 6px 10px; }}\n}}\n</style>\n"""\n\n\ndef apply() -> None:\n    st.markdown(CSS, unsafe_allow_html=True)\n\n\ndef plotly_layout(fig, height: int = 380, compact: bool = False):\n    fig.update_layout(\n        template="plotly_dark", height=height, margin=dict(l=6, r=6, t=78 if compact else 40, b=6),\n        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",\n        font=dict(color=COLORS["text"], size=11 if compact else 12),\n        title_font=dict(size=13 if compact else 16),\n        legend=dict(orientation="h", yanchor="bottom", y=1.0, x=0, font=dict(size=10)) if compact else {},\n    )\n    fig.update_xaxes(gridcolor=COLORS["border"])\n    fig.update_yaxes(gridcolor=COLORS["border"])\n    return fig\n\n\ndef show_chart(fig, height: int = 380) -> None:\n    """Gráfico sem barra de ferramentas (no telemóvel tapava o título) e adaptado ao modo compacto."""\n    from .components import is_compact\n\n    compact = is_compact()\n    st.plotly_chart(plotly_layout(fig, height, compact), width="stretch",\n                    config={"displayModeBar": False, "responsive": True, "scrollZoom": False})\n', 'src.ui.updater': '"""Execução da atualização a partir da UI, com barra de progresso."""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nimport streamlit as st\n\nfrom ..data.collector import UpdateReport\nfrom .context import AppContext\n\n\ndef run_update(ctx: AppContext, include_stats: bool = True, where: Any = st) -> UpdateReport:\n    bar = where.progress(0.0, text="A preparar…")\n\n    def progress(msg: str, frac: float) -> None:\n        bar.progress(min(1.0, max(0.0, frac)), text=msg)\n\n    rep = ctx.collector.update_all(include_stats=include_stats, progress=progress)\n    bar.empty()\n    st.cache_data.clear()\n    if not rep.online:\n        where.warning("Sem ligação à Deadlock API. A app continua com os últimos dados guardados.")\n    elif rep.ok:\n        msg = f"Dados atualizados — versão {rep.version}."\n        if rep.new_version:\n            msg += f" Nova versão detetada (anterior: {rep.previous_version})."\n        where.success(msg)\n    else:\n        failed = [s.name for s in rep.steps if not s.ok]\n        where.warning(f"Atualização com falhas em: {\', \'.join(failed)}. Dados válidos anteriores mantidos.")\n    return rep\n'}
_PACKAGES = ['src', 'src.analytics', 'src.api', 'src.data', 'src.engine', 'src.models', 'src.optimizer', 'src.ui', 'src.ui.pages']


class _BundleImporter(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    bundle_id = _BUNDLE_ID

    def find_spec(self, name, path=None, target=None):
        if name in _SOURCES:
            return importlib.util.spec_from_loader(name, self, is_package=name in _PACKAGES)
        return None

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__name__
        rel = name.replace(".", "/") + ("/__init__.py" if name in _PACKAGES else ".py")
        module.__file__ = str(_BUNDLE_ROOT / rel)
        exec(compile(_SOURCES[name], module.__file__, "exec"), module.__dict__)


def _install_bundle() -> bool:
    """Instala o importador. Se este app.py for uma versão nova (o Streamlit Cloud recarrega o ficheiro sem
    reiniciar o processo), descarta os módulos antigos já carregados para não ficar a correr código velho.
    Devolve True se havia código antigo carregado."""
    with sys.__dict__.setdefault("_dbl_bundle_lock", threading.Lock()):
        mine = [f for f in sys.meta_path if type(f).__name__ == "_BundleImporter"]
        same = [f for f in mine if getattr(f, "bundle_id", None) == _BUNDLE_ID]
        if same:  # mesma versão: manter um só importador (evita acumular um por cada rerun)
            for f in mine:
                if f is not same[0]:
                    sys.meta_path.remove(f)
            return False
        for f in mine:
            sys.meta_path.remove(f)
        stale = [m for m in list(sys.modules) if m == "src" or m.startswith("src.")]
        for m in stale:
            sys.modules.pop(m, None)
        sys.meta_path.insert(0, _BundleImporter())
        return bool(stale)


if _install_bundle():
    import streamlit as _st

    _st.cache_resource.clear()
    _st.cache_data.clear()

