def show_error(exc: Exception, where: str) -> None:
    """Mostra o erro no ecrã (com detalhes) e regista-o em Configurações › Diagnóstico rápido."""
    import traceback

    from src.data.database import utc_now

    tb = traceback.format_exc()
    st.error(f"Ocorreu um erro ({where}). Os dados guardados estão intactos. Faz uma captura de ecrã desta "
             "mensagem (incluindo os detalhes) se quiseres que seja corrigido.")
    with st.expander("Detalhes técnicos", expanded=True):
        st.code(f"{type(exc).__name__}: {exc}\n\n{tb[-3000:]}", language=None)
    try:
        log = ctx.db.get_kv("error_log", []) or []
        log.insert(0, {"at": utc_now(), "page": where, "error": f"{type(exc).__name__}: {exc}",
                       "trace": tb[-2000:]})
        ctx.db.set_kv("error_log", log[:20])
    except Exception:  # noqa: BLE001
        pass


