            with st.container():
                st.info("Os dados têm mais de "
                        f"{ctx.cfg['update']['check_interval_h']} h (ou ainda não existem). A atualizar…")
                run_update(ctx, include_stats=ctx.cfg["update"]["fetch_stats_on_update"])
